#!/usr/bin/env bash
#
# lucx-dual-domain.sh
# --------------------
# Установка + healthcheck для lucx-ui с двумя доменами и Reality на 443.
# Версия с автоматическим фиксом подписок (подтверждённые ключи БД + nginx location).
#
# v0.0.1: baseline — первая версия скрипта. Установка lucx-ui с двумя
#   доменами, Reality на 443, nginx SNI-роутер, decoy-сайты, подписки.
#
# v0.0.2: certbot переведён с --standalone на --webroot, чтобы плановое
#   продление (certbot renew из cron) не падало из-за занятого nginx'ом
#   80-го порта. Раньше renew молча фейлился каждые ~60-90 дней.
#
# v0.0.3 (правки Кими): AWG_SECRET_PATH и remark/tag Reality-инбаунда
#   рандомизированы вместо жёстких /awg/ и reality-auto/inbound-443;
#   проверка на существующий inbound перед вставкой (повторный запуск
#   не создаёт дубликат); запись в client_traffics (чинит "Сбросить
#   трафик" в панели); dig +short теперь с явным типом A.
#
# v0.0.4: XUI_CLI ищется по нескольким путям (/usr/local/x-ui/x-ui в
#   приоритете — это реальный бинарник, а не /usr/bin/x-ui, который
#   просто menu-обёртка); username/password/port/webBasePath форсятся
#   и через SQL-фолбэк; после рестарта x-ui факт бинда на 127.0.0.1
#   проверяется через `ss -tlnp`, и если панель всё ещё видна на
#   0.0.0.0 — установка падает, а не просто предупреждает.
#
# v0.0.5: nginx stream теперь шлёт proxy_protocol на panel_backend и
#   reality_backend; xray Reality инбаунд принимает его через
#   acceptProxyProtocol:true в tcpSettings — реальные IP клиентов
#   VLESS/Reality снова видны в inbound_client_ips (подтверждено
#   вживую на всех трёх продакшн-серверах).
#
# v0.0.6: на панельном vhost'е `listen ... proxy_protocol;` сам по себе
#   только парсит заголовок, но не подставляет его в $remote_addr — без
#   `set_real_ip_from`/`real_ip_header proxy_protocol;` IP посетителей
#   панели/подписок так и оставались 127.0.0.1. Добавлено и проверено
#   вживую на всех трёх серверах 27-28 авг 2026 — реальные IP пошли.
#   Также возвращён банк из 12 decoy-шаблонов (выбор по хешу домена),
#   он был потерян в промежуточных версиях. healthcheck теперь тоже
#   проверяет наличие proxy_protocol/set_real_ip_from/real_ip_header,
#   чтобы регресс этого фикса не проходил незамеченным.
#   (правка: PANEL_CONF в этой новой проверке использовался до своего
#   определения — под `set -u` это падало с "unbound variable" прямо
#   посреди healthcheck; объявление переставлено выше первого использования.)
#
#   Добавлен интерактивный выбор версии lucx-ui при установке: показывает
#   последние 10 стабильных релизов, Enter = последняя. Можно также
#   зафиксировать версию без вопросов через переменную окружения:
#     LUCX_PIN_VERSION=v3.7.0-lucx.192 sudo bash lucx-dual-domain.sh install
#   При неинтерактивном запуске (без терминала) молча берёт последнюю.
#
# v0.0.7: версия САМОГО этого скрипта (не lucx-ui) теперь выводится и
#   при install, и при healthcheck — раньше нигде не показывалась, и
#   на сервере не было способа быстро понять, какая версия там стоит,
#   не открывая сам файл.
#
# v0.0.8: не выпускалась (после v0.0.7 сразу пошли срочные правки
#   совместимости с lucx-ui v3.7.0-lucx.203, версия получила номер 0.0.9).
#
# v0.0.9 (правки Claude, совместимость с lucx-ui v3.7.0-lucx.203):
#   - set -e включён сразу, а не после интерактива.
#   - Убран GITHUB_TOKEN — с v3.7.0-lucx.203 AWG качается tarball'ом
#     (curl codeload.github.com), git clone больше не используется.
#   - Добавлено ожидание создания x-ui.db после install.sh — раньше
#     SQL-фолбэк мог пропуститься, если бинарник ещё не создал файл.
#
# v0.1.0: финальная стабилизация на базе v0.0.9.
#   - Исправлен баг в decoy extras — robots.txt и sitemap.xml для
#     второго домена (REALITY_DOMAIN) ошибочно ссылались на первый
#     (DOMAIN), что могло выдать связь между доменами при индексации.
#     Теперь каждый decoy-site получает правильные доменные ссылки.
#   - Decoy-шаблоны стали «живыми»: даты в 4 шаблонах генерируются
#     динамически (date -d), сайты выглядят актуальными.
#   - Добавлены error_page 404 и decoy extras (robots.txt, sitemap.xml,
#     404.html) для обоих доменов — лучшая мимикрия под реальные сайты.
#
# v0.1.1: добавлено предупреждение про tproxy (Telegram WEB proxy) и порт 443.
#   В lucx-ui v3.7.0-lucx.203+ появился inbound tproxy, который жёстко привязан
#   к порту 443. Скрипт уже занимает 443 через nginx stream (SNI-роутер).
#   Чтобы не было конфликта, в финальном выводе добавлен пункт 7:
#   при использовании tproxy нужно включить externalTLS в форме инбаунда.
#
# v0.1.2: 404-страницы стали уникальными для каждого шаблона.
#   Раньше все 12 decoy-сайтов и оба домена использовали одну и ту же
#   generic 404.html — это был статичный маркер, объединяющий разные
#   серверы как "поставленные этим скриптом". Теперь для каждого из
#   12 шаблонов своя 404-страница в соответствующем стиле/шрифтах.
#
# v0.1.3: install.sh теперь скачивается из того же тега, что и lucx-ui,
#   а не из main. Раньше при выборе .207 через интерактив скачивался
#   install.sh из main, который ссылался на sidecar'ы (tproxy/mtproxy),
#   отсутствующие в .207 — и установка шла с curl 404. Теперь URL
#   install.sh формируется как raw.githubusercontent.com/.../${LUCX_TAG}/install.sh.
#
# v0.1.4: экспорт LUCX_BRANCH перед запуском install.sh.
#   Внутри install.sh (даже от .207) LUCX_BRANCH="main" захардкожена,
#   и sidecar'ы (tproxy/mtproxy) тянутся через lucx_raw_url из main.
#   Переопределение LUCX_BRANCH="${LUCX_TAG}" заставляет install.sh
#   скачивать sidecar'ы из того же тега, что и основной tarball.
#
# v0.1.5: export LUCX_BRANCH не работает — install.sh ПЕРЕОПРЕДЕЛЯЕТ
#   переменную строкой LUCX_BRANCH="main" в своём теле, и sidecar'ы
#   снова ломятся в main. Теперь install.sh патчится через sed ПЕРЕД
#   запуском: строка LUCX_BRANCH заменяется на LUCX_BRANCH="${LUCX_TAG}".
#   Проверено: tproxy/mtproxy больше не 404 при выборе .207.
#
# v0.1.6: healthcheck — проверка UDP/443 заменена с ss на awg show.
#
# v0.1.7: nginx connection limits — фикс "worker_connections are not enough".
#   При нагрузке ~400 активных сессий через nginx stream (SNI-роутер)
#   дефолтных 768 worker_connections не хватало: каждая проксируемая сессия
#   занимает 2 слота (клиент→nginx + nginx→backend), и при ~400 сессиях
#   получалось ~800 слотов — выше лимита. Теперь скрипт выставляет:
#     - worker_connections 4096 (вместо дефолтных 768)
#     - worker_rlimit_nofile 65535
#     - systemd LimitNOFILE=65535 через override
#   Healthcheck тоже проверяет эти три параметра.
#
# v0.1.8: гибрид v0.1.7 + улучшения Claude.
#   - [7.5/10] добавлен nginx -t сразу после правок лимитов — ошибка
#     всплывает с точной привязкой к шагу, а не позже в общем тесте.
#   - healthcheck: помимо файлов проверяется /proc/<nginx-pid>/limits —
#     ловит сценарий, когда override.conf на диске есть, но реальный
#     процесс живёт со старым лимитом (не сделан restart/daemon-reload).
#   В lucx-ui .213+ AWG работает через kernel interface (awg2), и ss
#   не всегда показывает UDP/443 корректно, хотя порт реально слушается.
#   Теперь проверяем любой AWG-интерфейс с listening port: 443.
#
# Режимы:
#   sudo bash lucx-dual-domain.sh install      — установить всё с нуля
#   sudo bash lucx-dual-domain.sh healthcheck  — проверить текущую связку
#   sudo bash lucx-dual-domain.sh              — по умолчанию install
#
# Запускать от root на чистой Debian/Ubuntu.


# ================== Версия ==================
# v0.1.9: healthcheck на лимиты nginx давал ложный FAIL на реальном
#   продакшн-сервере (prod-node-3). Проверка "Max open files" сравнивала
#   фактический hard limit процесса на точное равенство 65535, а сервер
#   (systemd default DefaultLimitNOFILE=524288 без нашего override.conf)
#   реально имел 524288 — то есть с большим запасом ВЫШЕ требуемого, но
#   проверка "==" считала это провалом. Аналогично "override.conf НЕ
#   найден" падал в FAIL, хотя файл вообще не нужен, если эффективный
#   лимит и так достаточен (например, за счёт system-wide default).
#   Теперь:
#     - Max open files: сравнение "-ge 65535" вместо "== 65535"
#     - override.conf: FAIL только если РЕАЛЬНЫЙ лимит процесса < 65535
#       (т.е. override реально нужен, но его нет); если лимит и так
#       >= 65535 без override — warn ("не обязателен, но и так ОК"),
#       а не FAIL.
# v0.2.0: предупреждение и healthcheck-проверка про новый инбаунд Cover
#   site (lucx-ui v3.7.0-lucx.215+). Он жёстко занимает :80 и :443 на
#   хосте (как раньше tproxy) и по словам самого разработчика несовместим
#   с REALITY/AnyTLS/TrustTunnel/AWG — то есть с обоими протоколами,
#   которые тут используются. В финальный вывод install добавлен пункт 8
#   с явным предупреждением не создавать Cover site в панели.
#   В healthcheck [7] добавлены две проверки: инбаунды на порту 80
#   (конфликт с certbot webroot) и инбаунды на 443 не на loopback
#   (конфликт с nginx SNI-роутером) — по портам, а не по имени protocol,
#   т.к. точное значение protocol для Cover site в схеме БД не
#   подтверждено (не подтверждено и то, что Cover site вообще хранится
#   в таблице inbounds, а не в отдельной таблице для sidecar'ов/Caddy —
#   если это так, эта проверка его не увидит).
# v0.2.1: healthcheck-проверка "инбаунд на 443 не на loopback" (из v0.2.0,
#   для отлова Cover site) давала ложный FAIL на AWG. Подтверждено дампом
#   с prod-node-3: protocol='awg', port=443, listen='' — и это корректно,
#   т.к. AmneziaWG работает по UDP, а nginx ssl_preread/stream-проксирование
#   умеет только TCP. AWG физически не может идти через SNI-роутер и обязан
#   слушать публичный интерфейс напрямую, в отличие от vless/Reality (TCP),
#   который специально проксируется через nginx и поэтому сидит на
#   127.0.0.1. Теперь protocol='awg' явно исключён из этой проверки —
#   как и protocol='vless', который и так ожидается на loopback.
# v0.2.2: cmd_healthcheck не возвращал код завершения по числу FAIL —
#   функция заканчивалась на echo (всегда exit 0), так что healthcheck
#   из cron/monitoring/CI никогда не сигнализировал о проблеме через
#   код возврата, только через текст в stdout. Теперь при fail>0
#   healthcheck явно завершается exit 1, при fail=0 — exit 0.
# v0.2.3: healthcheck проверял только адрес:порт, не владельца процесса —
#   любой процесс на 127.0.0.1:443 или ${SERVER_IP}:443 засчитывался как
#   "Reality"/"nginx" соответственно. Теперь оба + публичный :80
#   verify'ятся через PID из `ss -tlnp` -> /proc/PID/cmdline (полный путь
#   к бинарнику, не обрезанный /proc/PID/comm — угадывать усечённое имя
#   процесса не стал, это тот же грех, что уже ловили в этом скрипте не
#   раз). Также ужесточена проверка VLESS listen: раньше пустая строка
#   считалась допустимой наравне с '127.0.0.1' — теперь только точное
#   '127.0.0.1' проходит, всё остальное (включая пустое) — FAIL, т.к.
#   на обоих живых серверах (prod-node-3, prod-node-4) реальный
#   listen всегда '127.0.0.1', пустое значение никогда не наблюдалось
#   и означало бы xray на wildcard 443 — прямой конфликт с nginx.
# v0.2.4: совместимость с lucx-ui v3.8.0-lucx.231 … v3.8.5-lucx.235
#   (проверено по коду тега v3.8.5-lucx.235 + живому дампу БД prod-node-1,
#   16 сен 2026):
#   - [КЛЮЧЕВОЕ] install.sh из 3.8.x принимает версию ПОЗИЦИОННЫМ
#     АРГУМЕНТОМ (install_x-ui $1). Скрипт запускал его БЕЗ аргумента —
#     install.sh тогда резолвил releases/latest и ставил ПОСЛЕДНИЙ релиз
#     вне зависимости от выбранного LUCX_TAG (sed-патч LUCX_BRANCH
#     переопределял только URL sidecar'ов). Пин версии фактически не
#     работал со времён v0.1.5, просто это было незаметно, пока latest
#     совпадал с выбранным тегом. Теперь: bash install.sh "$LUCX_TAG".
#   - Матрица сборки 231+ публикует ТОЛЬКО amd64 и arm64 (armv7/v6/386
#     больше не собираются) — добавлена явная проверка архитектуры до
#     скачивания review-tarball, иначе curl умирал на 404 с пугающим
#     выводом HTML-страницы GitHub.
#   - Схема подписок ПОДТВЕРЖДЕНА на живой БД 3.8.x: subEnable, subListen,
#     subPort, subPath, subURI, subClashURI, subAwgEnable, subAwgURI — все
#     на месте (блок [5a] и healthcheck [8] работают без изменений).
#     subClashAutoDetect=true по умолчанию — авто-детект Clash по
#     User-Agent сохранился. Новые ключи 3.8.x (subJsonPath, subClashPath,
#     subJsonEnable и т.д.) просто сосуществуют и на нашу настройку не
#     влияют.
#   - install-awg-module.sh по-прежнему внутри release-tarball
#     (x-ui/bin/install-awg-module.sh, ассерт в release.yml) и по-прежнему
#     качает исходники tarball'ом через curl (codeload.github.com) — фикс
#     CLAUDE-FIX-v203 держится, GITHUB_TOKEN не нужен. Скрипт стал
#     безопаснее: pinned SHA, build-first (не выгружает старый модуль до
#     успешной сборки), флаг /etc/x-ui/.awg-reboot-needed вместо ребута
#     посреди установки, ставит iptables (совместимо с нашим ufw) и
#     sysctl-тюнинг BBR (с nginx не конфликтует). Healthcheck [9] валиден.
#   - Рекомендация по версиям: ставить v3.8.5-lucx.235. В 231–234 сломан
#     /usr/bin/x-ui (merge: два if, один fi — не парсится bash'ем,
#     падают x-ui restart/меню/setup-fail2ban). Наш скрипт использует
#     /usr/local/x-ui/x-ui и systemctl напрямую, поэтому даже 231–234
#     прошли бы, но админу на таком сервере будет больно — 235 чинит.
#   - sed-патч LUCX_BRANCH в install.sh оставлен: строка LUCX_BRANCH="main"
#     захардкожена и на 235 (патч безвреден; на 233+ часть sidecar'ов уже
#     внутри тарболла, так что патч всё чаще no-op).
#   - Тарболлы 231+ публикуются с .sha256-ассетами — верификацию пока не
#     добавлял (nice-to-have).
# v0.2.5: совместимость с lucx-ui v3.8.5-lucx.245 (проверено по коду тега:
# install.sh, release.yml). Механика установки НЕ изменилась: позиционный
# аргумент версии в install.sh, захардкоженный LUCX_BRANCH="main" (sed-патч
# жив), неинтерактивный путь XUI_SSL_MODE=none, tarball-раскладка
# (install-awg-module.sh, xray-linux-{amd64,arm64}, матрица amd64/arm64) —
# всё как в 235, фиксы v0.2.4 держатся без изменений. install.sh обзавёлся
# --yandex/--github, авто-проверкой sha256 tarball'а и XUI_ENABLE_FAIL2BAN —
# на нас не влияет (всё нефатально/опционально).
#   Новое в .245 — фича «SNI gateway / Masking» (страница Masking в панели):
# свой bundled nginx-sidecar (bin/nginx-linux-*, зашит в tarball) слушает
# публичный IPv4:443, gateway-inbound, PROXY protocol, «панель за Cover»,
# «Cover забирает свой SNI (REALITY оставляй microsoft.com)». Это OPT-IN
# (кнопка Apply на странице Masking) — install.sh её не применяет, чистая
# установка скриптом не затронута. НО на уже развёрнутых dual-domain серверах
# Apply сломает нашу схему: bundled-nginx перехватит публичный 443, заменив
# наш stream SNI-роутер (decoy-сайты, location подписок, certbot webroot
# окажутся под чужим роутингом). Хуже того, healthcheck по имени процесса
# эту подмену НЕ видит — бинарь sidecar'а тоже называется nginx.
#   Поэтому: (1) в финальный вывод install добавлен пункт 9 — НЕ нажимать
# Apply на Masking; (2) healthcheck [2] теперь различает системный nginx
# (/usr/sbin/nginx) и bundled-nginx lucx по ПУТИ бинарника в /proc/PID/
# cmdline — второй даёт WARN «Masking/SNI gateway применён — конфликт
# со схемой скрипта». Проверки [7] (инбаунды на 443/80) прежним образом
# ловят gateway-inbound, если он не vless/awg.
# v0.2.6: healthcheck [7] больше не падает на дополнительных
#   vless-инбаундах. Раньше проверялся только ПОСЛЕДНИЙ по id vless-инбаунд
#   и от него требовался порт 443 — любой экспериментальный инбаунд
#   пользователя (вживую на prod-node-1 18 сен 2026: 'vless-xhttp-test'
#   на 127.0.0.1:8445) давал ложный FAIL «Порт инбаунда НЕ 443», хотя
#   Reality на 443 loopback был на месте. Теперь:
#     - OK/FAIL: существует ХОТЯ БЫ ОДИН vless-инбаунд на 127.0.0.1:443
#       (это и есть скриптовый Reality);
#     - все vless-инбаунды перечисляются информационной строкой;
#     - доп. инбаунды НЕ на 443: WARN, если на loopback (безобидный
#       эксперимент), FAIL, если слушают не-loopback (открытый порт мимо
#       nginx SNI-роутера).
# v0.2.7: healthcheck [1] больше не WARN'ит на известной гонке lucx-ui при
#   загрузке: «awg: ensure xray routing (ip route replace default dev tun2
#   table 1002): exit status 2 / Device for nexthop is not up». Панель
#   прописывает маршрут до старта xray-ядра, а tun2 создаёт xray — WARNING
#   появляется на каждом ребуте (детерминировано, подтверждено вживую на
#   prod-node-1 18 сен 2026, x-ui 3.8.5-lucx.244), но маршрут восстанавливается
#   ensure-циклом панели (table 1002 заполнена после boot), функционал не
#   теряется. Паттерн отфильтрован из подсчёта ошибок; всё прочее в логе
#   по-прежнему ловится. Настоящий фикс — на стороне lucx (ensure routing
#   после старта core, а не до).
# v0.2.8: уточнено сообщение проверки логов из v0.2.7 — раньше ветка OK
#   всегда писала «гонка отфильтрована», даже когда гонки в этот boot не
#   было (сообщение статичное, вводило в заблуждение). Теперь известные
#   строки считаются отдельно: «ошибок нет, отфильтрована гонка tun2
#   (N строк)» только когда они реально присутствовали, иначе просто
#   «ошибок не обнаружено».
# v0.2.9: healthcheck [1] — сообщение про гонку tun2 теперь выводится
#   только когда гонка реально присутствовала в логе. Раньше changelog
#   v0.2.8 описывал это поведение, но код остался статичным — "отфильтрована"
#   писалось всегда. Теперь считаем известные строки отдельно и формируем
#   сообщение по факту.
# v0.3.0: совместимость с lucx-ui v3.8.5-lucx.246. В .246 bundled SNI-шлюз
#   заменён с nginx на Caddy L4 (bin/caddy-layer4-linux-* вместо nginx-linux-*).
#   install.sh diff — 1 строка (имя sidecar'а), установка не сломана. НО:
#   (1) предупреждение в финальном выводе (п. 9) теперь универсально —
#   "bundled SNI-шлюз lucx-ui", а не конкретно "nginx-sidecar";
#   (2) healthcheck [2] теперь ловит ОБА sidecar'а: и bundled-nginx (.245),
#   и caddy-layer4 (.246+) — по пути бинарника в /proc/PID/cmdline.
#   Проверка системного nginx (/usr/sbin/nginx) сохранена.
# v0.3.1: Hysteria 2 — третий штатный протокол + полное покрытие healthcheck.
#   Схема проверена вживую на тестовом стенде (prod-node-1, 18 сен 2026):
#   hy2-инбаунд внутри xray на UDP/443, masquerade -> decoy-сайт REALITY_DOMAIN
#   (proxy + rewriteHost), TLS-сертификат того же домена, ALPN h3, клиент с
#   auth-паролем автоматически попадает в подписку. AWG освобождает 443/udp
#   и переезжает на отдельный порт (по умолчанию 52911).
#   INSTALL: [10a] создаёт hy2-инбаунд через SQLite по СНЯТОЙ ДАМПОМ схеме
#   lucx-ui .246 (protocol='hysteria', network='hysteria',
#   hysteriaSettings.version=2, tlsSettings.certificateFile/keyFile) —
#   JSON не угадан, скопирован с рабочей БД. Создаётся клиент с auth-паролем,
#   запись client_traffics (как для Reality в v0.0.3), ссылка hysteria2://
#   выводится в финале и пишется в креды. Salamander/UDP Mask намеренно НЕ
#   включается: дефолт — чистый QUIC/HTTP/3 к домену (согласованность с
#   decoy-концепцией и работа masquerade-пробы), обфускация остаётся опцией
#   в UI панели. Порт AWG спрашивается при install [Enter = 52911], валидируется
#   (не 443 — его занимает hy2), открывается в ufw и пишется в креды.
#   Также: deploy-hook certbot теперь перезапускает x-ui (xray читает
#   сертификаты при старте — без этого hy2 отдал бы протухший серт).
#   HEALTHCHECK: [1] фильтр tun2-гонки расширен второй строкой
#   (sysctl rp_filter / cannot stat .../tun2); [2] владелец UDP/443
#   верифицируется по PID/cmdline (xray=hy2 ok, чужой процесс -> FAIL),
#   порт AWG читается из БД вместо хардкода 443; [7] 'hysteria' добавлен
#   в whitelist не-loopback проверки (как awg — UDP легитимно публичный)
#   + блок диагностики hy2: версия=2, masquerade -> REALITY_DOMAIN,
#   наличие клиентов, SNI в tlsSettings, INFO про obfs-режим; [8] живой
#   запрос subURI+subId: подписка реально отдаёт hysteria2://-ноду.
#   Системный аудит после ревью №3: все grep-пайпы в $( ) без страховки
#   получили '|| true' (read_domains, креды-параметры, worker_connections) —
#   pipefall-ловушка закрыта по всему файлу, не только в двух известных местах.
#   Ревью №3 добило корень проблемы: та же ловушка сидела в общей
#   get_listener_pid() (владельцы nginx/xray/панели/80) — healthcheck падал
#   бы молча в ЛЮБОЙ аварии с незанятым портом, не дойдя до FAIL-вывода.
#   Теперь оба 'pid=\K'-пайпа защищены; пустой PID корректно разбирается
#   ниже по коду через [[ -n "$PID" ]].
#   Фикс третьего ревью/прод-прогона: UDP443_PID без '|| true' — на серверах
#   до v0.3.1 (AWG ядром на 443/udp, в ss нет pid=) pipefail гасил пайплайн
#   и set -e молча ронял healthcheck посередине [2] (prod-node-2).
#   Фиксы второго ревью (поведенческие, bash -n их не ловит): (1) явные
#   проверки systemctl stop/cp/start в create_hy2_inbound — set -e не
#   действует в теле функции, вызванной под "||"; (2) финальный вывод
#   add-hy2 защищён от unbound variable при повторном запуске (идемпотентность).
#   Режим retrofit `add-hy2`: cmd_install валиден только для чистого сервера,
#   поэтому создание hy2 вынесено в общую функцию create_hy2_inbound (её
#   вызывает и install [10a], и `bash $0 add-hy2`). Ретрофит читает домены из
#   кредов, валидирует сертификаты и свободность UDP/443 (с подсказкой про
#   переезд AWG, если 443 ещё занят), чинит cron deploy-hook и дописывает креды.
#   Ревью-правки по итогам аудита: else-ветка UDP/443 закрыта полностью
#   (свободен -> ok, чужой процесс -> fail), комментарий AWG уточнён под
#   переезд с 443, json_extract-пути приведены к консистентному '$.'.
#   (путь в БД — префикс lucx 3.8.x, полный URL = префикс + subId клиента)
# v0.3.2: банк decoy-шаблонов расширен с 12 до 22 (TEMPLATE_COUNT=12 -> 22).
#   Добавлены template_13..template_22 — новый жанр "login-decoy" (статичная
#   форма входа под вымышленную самохостed-панель, вместо лендинга): 5 с
#   ED-тематикой (Wing Ops / route.ledger / Ashfall Wing / Intel dashboard /
#   stream_cms) и 5 тематически нейтральных для баланса банка (sensor-net /
#   vault admin / home bridge / relay_admin / private gallery), плюс
#   err404_13..err404_22 под каждый в том же тоне. Общая функция
#   render_login_page() — карточка логина с двумя полями, параметризуется
#   палитрой/шрифтами/текстом; submit перехватывается чисто на клиенте
#   (onsubmit="return false" + JS показывает "Invalid credentials") — НИКАКОГО
#   бэкенда, ни одного нового nginx location, ни одного нового пакета. Активный
#   бан за неудачные попытки (fail2ban-стиль, по мотивам ss.sh) сознательно
#   отложен отдельным треком — не в этой версии.
#   ВАЖНО: pin-механизм (${DECOY_ROOT}/.template_idx) НЕ добавлен в этой
#   версии — по явному решению внешний вид decoy на уже развёрнутых серверах
#   при апдейте скрипта поменяется (hash(domain) % TEMPLATE_COUNT считается
#   от нового делителя 22, а не 12). Если на каком-то сервере это нежелательно —
#   не катить эту версию поверх него без ручной проверки, либо сначала
#   реализовать pin отдельным патчем.
# v0.3.3: nginx stream-роутер (SNI-роутинг на 443) снят с явной привязки к
#   публичному IP. Найдено по факту разбора аварийного сценария "заблокировали
#   IP, сервер жив" — install генерировал "listen ${SERVER_IP}:443;" (IP,
#   определённый на МОМЕНТ install), из-за чего смена IP у провайдера требовала
#   бы ручной правки конфига + reload nginx, иначе новый IP не отвечал бы
#   вообще, хотя DNS уже переключён. Аудит по всему файлу (правки Кими,
#   независимо перепроверены построчно): install [9/10] -> "listen 443;"
#   (wildcard, слушает все интерфейсы); healthcheck [2] NGINX443_PID теперь
#   ищет по паттерну "(${SERVER_IP}|0\.0\.0\.0):443\b" (тот же приём уже был
#   в PUBLIC80_PID для порта 80 — используется как прецедент); отдельная
#   ветка "nginx на 0.0.0.0:443 -> fail, конфликт с xray" УБРАНА — она была
#   нужна только чтобы компенсировать узкий паттерн выше, после его
#   расширения стала недостижима (nginx на wildcard теперь находится и
#   подтверждается тем же кодом, что и раньше подтверждал explicit-IP,
#   просто через ok, не через отдельный fail-фолбэк); healthcheck [4]
#   (проверка stream-конфига) принимает обе формы — новую "listen 443;" и
#   legacy "listen ${SERVER_IP}:443;" на серверах, установленных до этой
#   версии, плюс отдельный WARN на случай явного дрейфа (IP в конфиге не
#   совпадает ни с wildcard, ни с текущим определённым публичным IP).
#   Технически подтверждено: одновременный bind nginx на 0.0.0.0:443 и
#   xray на 127.0.0.1:443 (Reality-инбаунд) не конфликтует — более
#   специфичный bind (127.0.0.1) перехватывает трафик на свой адрес,
#   wildcard берёт остальное; это уже штатная связка в схеме (reality_backend
#   всегда был на 127.0.0.1:443, отдельно проверяется REALITY443_PID).
#   Побочный эффект патча: сервер с несколькими публичными IP на этой машине
#   теперь слушает 443 на всех них, не только на том, что был при install —
#   для схемы с одним публичным IP на сервер (текущий случай всех трёх
#   продакшн-серверов) поведенчески не отличается.
#   ЧТО НЕ ЗАТРОНУТО (проверено явно): preflight-проверка занятости 443 при
#   install (уже address-agnostic, "grep -q ':443 '"), ufw (правила по порту,
#   не по IP), certbot (валидирует владение доменом, не IP), REALITY443_PID
#   и все curl --resolve проверки decoy/подписки (резолвят домен принудительно
#   в SERVER_IP, работают при любом виде bind), весь hy2/AWG-блок (отдельный
#   UDP-бинд, xray, без nginx).
# v0.3.4: микропатч — три косметические правки по итогам дифф-аудита v0.3.3
#   (поведение установки/healthcheck не меняется, функциональных
#   изменений нет, только сообщения и комментарии):
#   - Баннер шага [7/10] install писал «банк из 12 шаблонов», хотя банк
#     расширен до 22 ещё в v0.3.2 (TEMPLATE_COUNT=22). Строка теперь
#     подставляет ${TEMPLATE_COUNT} — рассинхрон исключён и для будущих
#     расширений банка.
#   - Комментарий над bundled-sidecar проверкой в healthcheck [2] ссылался
#     на «v0.2.10» — версии, которой не существовало (опечатка из ранней
#     сессии, унаследована через несколько релизов). Исправлено на
#     фактические версии появления детектов: v0.2.5 (bundled-nginx .245)
#     и v0.3.0 (caddy-layer4 .246+).
#   - Трёхветочная проверка listen-директивы в healthcheck [4] (из v0.3.3):
#     else-ветка «похоже, IP сменился у провайдера, а конфиг не обновлён»
#     срабатывала и при пустом SERVER_IP (get_server_ip не определил IP —
#     внешний сбой api4.ipify.org/ifconfig.me), сообщение врало про дрейф.
#     Добавлена отдельная ветка «публичный IP не определён — пропускаю»
#     warn, по аналогии с [2] и [6].
#   - (правка по собственному ревью патча: первая редакция правки баннера
#     [7/10] ссылалась на ${TEMPLATE_COUNT} ДО строки TEMPLATE_COUNT=22,
#     под set -u это убило бы install с «unbound variable» — ровно та
#     болезнь, что уже ловилась в v0.0.6 с PANEL_CONF. Присваивание
#     перенесено выше echo.)
# v0.3.5: ОТКАТ wildcard-бинда из v0.3.3 (подтверждённый регресс) + новый
#   режим rebind-ip как штатное решение смены IP у провайдера.
#   СИМПТОМ (A/B на rose421: Ubuntu 24.04, kernel 6.8.0-142, lucx-ui
#   v3.8.5-lucx.268, оба домена свежие): установка v0.3.4 → decoy №2
#   (REALITY_DOMAIN) НЕ открывается; decoy №1, панель, подписки — работают.
#   Установка v0.3.1 на ту же машину → всё работает. Все прочие переменные
#   исключены: панель .268 одинакова (0.3.1+.268 = ОК), DNS-кэш невозможен
#   (домены новые), шаблон decoy №2 (#8 Fieldwork) рендерится валидным HTML
#   (проверено извлечением функции из скрипта: сбалансированные теги,
#   раскрытые переменные). Единственная оставшаяся дельта install-пути —
#   "listen 443;" (wildcard) из v0.3.3. Механизм ПОДТВЕРЖДЁН логом с prod-node-2 (27 сен 2026): nginx,
#   заняв wildcard 0.0.0.0:443, БЛОКИРУЕТ последующий бинд xray'ем
#   127.0.0.1:443 — в журнале x-ui бесконечный цикл раз в ~2 сек:
#     "ERROR - XRAY: Failed to start: ... failed to listen TCP on 443 ...
#      listen tcp 127.0.0.1:443: bind: address already in use".
#   Ключевой нюанс, сделавший баг невидимым: xray-core — дочерний процесс
#   панели, его краш-луп НЕ роняет юнит: `systemctl is-active x-ui`
#   остаётся active, install завершается «успешно». Ловит только
#   healthcheck [2] («xray слушает 127.0.0.1:443») — именно он и выловил
#   баг на третьем сервере. Клиентских ссылок баг не касается (порт в БД
#   по-прежнему 443), страдает ровно один элемент: decoy №2 — единственный,
#   зависящий от dest-fallback Reality (decoy №1 ходит напрямую в nginx
#   vhost :8443, поэтому жив).
#   ОТВЕТВЛЁННАЯ ВЕТКА (НЕ ПРИМЕНЯТЬ): перенос Reality-инбаунда на «свободный»
#   внутренний порт (8443/9443) ломает генерацию ссылок — поле `port` в
#   таблице inbounds ДВОЙНОЕ: это и listen-порт, и порт в vless-ссылках
#   клиентов (отдельного external_port в схеме БД нет — подтверждено дампами
#   ещё в v0.2.4). Живая попытка на 8443 дала второй конфликт — 8443 занят
#   панельным vhost'ом (PANEL_INTERNAL_PORT). Верный internal-порт Reality —
#   только 443 на loopback; конфликт снимается не портом, а формой bind
#   nginx (явный публичный IP, см. ниже).
#   ИЗВЛЕЧЁННЫЙ УРОК: асимметрия бинда wildcard/specific на одном порту
#   ядро-зависима, «должно работать по man ip» — недостаточная проверка;
#   wildcard-бинд рядом с loopback-биндом xray отзывается. Также: любой
#   healthcheck после install обязан включать проверку «xray реально слушает
#   127.0.0.1:443» — она есть в [2] и ловила бы регресс сразу.
#   ИЗМЕНЕНИЯ:
#   - install [9/10]: снова "listen ${SERVER_IP}:443;" (проверенная форма
#     со времён v0.0.1, работает на всех четырёх серверах);
#   - НОВЫЙ РЕЖИМ `rebind-ip`: sudo bash lucx-dual-domain.sh rebind-ip —
#     определяет текущий IP, сверяет A-записи (warn если DNS не переключён),
#     правит listen-строку (обе формы: legacy explicit и отозванный
#     wildcard), бэкап, nginx -t, restart, проверка бинда через ss.
#     Идемпотентен. Решает исходную задачу v0.3.3 (смена IP без ручной
#     правки конфига) без wildcard-рисков;
#   - healthcheck [4]: ветка «wildcard -> ok» заменена на warn с
#     рекомендацией rebind-ip (на wildcard-форме Reality может быть мёртв);
#   - финальный вывод install: блок «ПРИ СМЕНЕ IP У ПРОВАЙДЕРА» с двумя
#     шагами (A-запись + rebind-ip);
#   - паттерн NGINX443_PID в [2] без изменений (ловит обе формы бинда).
#   (same-day fix: в комментарии этого самого блока [9/10] слово было
#   обёрнуто в обратные кавычки — не-квотированный heredoc выполнил его как
#   командную подстановку, в логе установки "rebind-ip: command not found",
#   комментарий в сгенерированном stream-конфиге потерял слово. Косметика,
#   на работу не влияло; backticks убраны. Поймано при разборе лога установки
#   на prod-node-2, 27 сен 2026.)
# v0.3.6: два фикса сообщений/комментариев v0.3.5, пойманные при живом
#   прогоне на prod-node-2 (27 сен 2026, 47/47 OK после установки v0.3.5):
#   1. ЛОЖНОЕ СРАБАТЫВАНИЕ healthcheck [4]: поясняющий комментарий, который
#      v0.3.5 вписывает в ГЕНЕРИРУЕМЫЙ stream-конфиг, содержал строку-литерал
#      "listen 443;" — детектор wildcard-формы (grep "listen 443;") матчил
#      сам комментарий и выдавал WARN «wildcat-форма, Reality может быть
#      мёртв» на ПОЛНОСТЬЮ ЗДОРОВОМ сервере с явным IP. Урок: детектор
#      конфиг-форм нельзя оставлять тривиальным grep по файлу, в который мы
#      сами пишем пояснительные строки. Двойная защита: комментарий
#      переформулирован без литерала директивы И детекторы [4] переведены
#      на якорь "^\s*listen ..." — матчат только реальную директиву, а не
#      любое упоминание в комментариях (устойчиво к будущим правкам текста).
#   2. Устаревшее сообщение ветки explicit-IP в [4] («legacy-форма, сервер
#      установлен до v0.3.3») — после отката v0.3.5 явный IP снова ШТАТНАЯ
#      форма, а не legacy. Теперь ok + подсказка про rebind-ip.
# v0.3.7: правки по результатам внешнего аудита v0.3.6. Пять тем:
#   1. CRONTAB-ПАЙП ГАСИЛ СКРИПТ И ТЕРЯЛ СТРОКУ renew (найдено при подготовке
#      этого релиза; в аудите v0.3.6 пункт был ошибочно признан корректным).
#      Конструкция ( crontab -l 2>/dev/null | grep -v 'certbot renew' ;
#      echo "..." ) | crontab - под set -euo pipefail: grep -v — ПОСЛЕДНИЙ
#      элемент внутреннего пайпа, его exit 1 (у root нет crontab, либо все
#      строки были certbot-овыми) НЕ подавляется правилом «не-последние
#      элементы пайпа исполняются с подавленным -e» (оно защищает только
#      crontab -l). Сабшелл умирал ДО echo, crontab - получал пустоту: на
#      свежем сервере строка certbot renew вообще не ставилась, а на
#      повторном запуске — СТИРАЛАСЬ (пустой crontab поверх существующего).
#      Внешний пайп возвращал 1, и set -e добивал скрипт: в install — сразу
#      после всего финального вывода (глазом незаметно, но exit 1 и без
#      очистки REVIEW_DIR), в add-hy2 — до финального блока. Прод выживал,
#      вероятно, потому что lucx-ui install.sh создаёт root-кронтаб со своими
#      строками и grep -v было что отбирать. Фикс: '|| true' после grep -v в
#      обоих местах (add-hy2 и финал install). В healthcheck [5] добавлена
#      проверка наличия строки certbot renew в crontab — урон на
#      задеплоенных серверах теперь виден.
#   2. КРЕДЫ В ЛОГЕ УСТАНОВКИ. exec > >(tee -a "$LOG_FILE") создавал лог с
#      дефолтным umask (0644, мир-читаемо), а в него идут username/password
#      панели, hy2-ссылка с auth-паролем и секретные пути подписок; chmod 600
#      был только на CREDS_FILE. Теперь touch+chmod 600 ДО exec (tee -a права
#      существующего файла не меняет). umask 077 на весь install сознательно
#      НЕ ставится: decoy-файлы и webroot должны остаться читаемыми
#      www-data. CREDS_FILE теперь тоже создаётся сразу с 600 (touch под
#      локальным umask 077 перед heredoc) — закрыто короткое окно 0644 между
#      "cat >" и chmod. В healthcheck [10] добавлена проверка прав лога: на
#      серверах, установленных ранее, файл остался 0644 — теперь FAIL с
#      готовой командой фикса.
#   3. add-hy2 ПРОПУСКАЛ kernel-AWG НА 443/udp. Preflight ретрофита проверял
#      занятость UDP/443 только через ss -ulnp, но AWG на kernel-интерфейсе
#      в ss НЕ ВИДЕН (известно со времён v0.1.6/v0.1.8). Аудитория add-hy2 —
#      как раз серверы до v0.3.1 с AWG на 443/udp: проверка проходила, hy2
#      вставлялся поверх занятого порта, xray уходил в краш-луп. Добавлен
#      второй preflight через awg show (listening port: 443) — тот же
#      проверенный приём, что в healthcheck [2].
#   4. «УСПЕХ» БОЛЬШЕ НЕ ВЕРИТ systemctl is-active. Урок v0.3.5: краш-луп
#      xray-core (дочерний процесс панели) НЕ роняет юнит x-ui — install/
#      add-hy2 отчитывались успехом при мёртвом протоколе, ловил только
#      healthcheck. После старта x-ui в create_hy2_inbound (UDP-порт hy2) и
#      в блоке [10/10] (TCP 127.0.0.1:443 Reality) добавлена проверка
#      фактического листенера: pid из ss -> /proc/PID/cmdline содержит xray,
#      ретраи 5x2с на медленный старт ядра, иначе ОШИБКА и ненулевой exit.
#   5. Мелочи того же аудита:
#      - trap cleanup EXIT INT TERM -> trap cleanup EXIT: INT/TERM-обработчик
#        сам скрипт не завершает (дальше set -e его ронял, и EXIT-ловушка
#        выполняла cleanup второй раз); с одним EXIT сигнал так же доходит
#        до cleanup — один прогон.
#      - baseline install-awg-module.sh из шага [4/10] вынесен из REVIEW_DIR
#        в постоянный /root/.lucx-awg-baseline: финальный rm -rf REVIEW_DIR
#        раньше стирал сохранённую копию, и baseline не переживал установку,
#        ради которой сохранялся.
#      - healthcheck [3]: в ufw-проверки добавлены 80/tcp (webroot certbot —
#        без него продление сертов падает) и UDP-порт AWG (AWG_PORT_HC из
#        [2]); паттерны заякорены на начало строки — без якоря «443/tcp»
#        матчил и «8443/tcp» (класс ловушки «детектор матчит не то, что
#        думает», как с listen-литералом в комментарии из v0.3.6).
# v0.3.8: три правки по второму аудиту v0.3.7 (после живого прогона на семи
#   серверах флота 2026-09-29) + один микро-фикс. Честная оговорка: install-
#   путь v0.3.7 живой чистой установкой ещё не гонялся — первая установка
#   новому клиенту будет приёмкой релиза.
#   1. AAAA-ПРЕФЛАЙТ [2/10] + мониторинг в hc [5]. Схема IPv4-only: nginx и
#      stream-роутер биндят только IPv4, а Let's Encrypt при наличии AAAA-
#      записи предпочитает её и не достучится («Timeout during connect»).
#      Раньше: install падал громко на [6/10] с непонятной причиной, а
#      появление AAAA ПОСЛЕ установки роняло продление ТИХО. Теперь preflight
#      стопорит установку с внятной причиной до certbot, hc [5] ловит
#      появление AAAA в любой момент жизни сервера (FAIL с адресом проблемы).
#      Preflight стоит после A-проверки — к нему dig доказанно работает.
#      УТОЧНЕНИЕ ПОСЛЕ РЕВЬЮ (Claude, прямой дифф vs v0.3.7, 2026-09-29):
#      «Timeout during connect» — ОБЩИЙ симптом «LE не смог подключиться»,
#      НЕ заявление о причине конкретного инцидента. Для протокола: флейк на
#      legacy-wan-ip (2026-09-29) случился при ПУСТОЙ AAAA (исключено проверкой),
#      его причина остаётся «сетевой флейк на маршруте до LE» — открытый вопрос.
#      AAAA-патч — генерическая защитная мера от другого, реального класса
#      отказов, НЕ объяснение того инцидента. Контрольная проверка при сборке:
#      AAAA отсутствует на всех 14 доменах флота (через 1.1.1.1).
#   2. SSH-ПОРТ В UFW ПО ФАКТУ [3/10]. Слепой allow 22/tcp на сервере с
#      кастомным портом sshd давал блокировку после "ufw --force enable".
#      Порт(ы) определяются по запущенному sshd (ss -tlnp, sort -u) и
#      открываются ОНИ; 22 открывается только если sshd на нём и слушает.
#      Фолбэк 22 + явный WARN, если sshd не найден (оператор подключён по
#      SSH, так что ss его показывает практически всегда). "ufw allow" без
#      "|| true": упасть ДО --force enable безопаснее, чем включить ufw без
#      подтверждённого SSH-правила.
#   3. СВЕРКА СЕРТОВ «ДИСК vs ОТДАЁТСЯ» в hc [5]. Единственный детектор
#      сценария «дистрибутивный таймер продлил серт на диске, а nginx/xray
#      держат старый в памяти» (продление без deploy-hook): проверка [6]
#      ходит с curl -k и протухший отдающийся серт не видит. Зонд через
#      реальный путь (--resolve на публичный IP -> stream SNI-роутер ->
#      vhost / xray-fallback decoy), приём обкатан вручную на всех семи
#      серверах флота. Несовпадение = FAIL с готовой командой фикса; пустой
#      ответ (сетевой флейк, см. legacy-wan-ip) = WARN, не FAIL.
#   4. Микро: rm -f перед созданием CREDS_FILE — touch не меняет права
#      существующего файла, реинсталл поверх оставлял суб-секундное окно 0644
#      до chmod; пересоздание под umask 077 гарантирует 600 с первого байта.
#   Не вошло (косметика, в следующем релизе): неинтерактивные промпты install,
#   ротация LOG_FILE, чистка старых бэкапов БД, заякоривание grep в rebind-ip.
# v0.3.9: VLESS+TLS как основной протокол 443 (эмпирика RU, 2026-09-30) +
#   ретрофит-режимы add-vls / add-reality. Предыстория: на новых ядрах
#   (mihomo/xray) Reality с fp=firefox у владельца НЕ работал, fp=chrome и
#   прочие — блокируются на RU-маршрутах; vless+plain-TLS — работает
#   (живой эксперимент на prod-node-1: инбаунд переведён вручную через
#   панель, клиенты подключились). Что сделано:
#   1. INSTALL спрашивает режим 443: [1] VLESS+TLS (дефолт, RU-совместимо)
#      [2] Reality (классика, вне RU). Архитектура TLS-режима = ровно то,
#      что проверено живьём на сервере №1: xray сам терминирует TLS на
#      127.0.0.1:443 (серт REALITY_DOMAIN с диска, ALPN http/1.1,
#      acceptProxyProtocol ON — nginx stream по-прежнему спереди, его
#      конфиги НЕ меняются), fallbacks -> 127.0.0.1:80 (пробы/браузеры
#      получают 301-фасад от nginx вместо обрыва). Дефолты клиентских
#      ссылок — по рабочей связке владельца: type=tcp, security=tls,
#      fp=firefox, flow=none (Vision с plain-TLS совместим, но выключен
#      по умолчанию — эмпирика). Ссылка печатается в финале и пишется
#      в креды.
#      ЧЕСТНОЕ УТОЧНЕНИЕ к плану v0.3.9: decoy №2 по https в TLS-режиме
#      ПОЛНОСТЬЮ не отдаётся (пробы получают 301 через fallback, не сайт)
#      — вернуть сайт на https-пробах в этом режиме невозможно без
#      HTTP-транспорта (ws/xhttp); healthcheck [6] стал mode-aware и
#      считает 301 успехом в TLS-режиме, 200 — как раньше в Reality.
#   2. РЕЖИМЫ add-vls / add-reality: переключение существующего сервера
#      между режимами без переустановки (для 6 серверов флота; клиентские
#      серверы НЕ трогаем по решению владельца). add-vls: сохраняет ТЕКУЩИЕ
#      stream_settings+settings в /root/.lucx-mode-backup/ (плюс бэкап БД),
#      обновляет их на TLS-вариант (клиенты/UUID/subId НЕ трогаются —
#      ссылки меняют только security-параметры), стартует, верифицирует
#      листенер. add-reality: откат из бэкапа. Идемпотентность: повторный
#      add-vls при уже-tls — no-op с сообщением.
#   3. HEALTHCHECK: [6] decoy №2 и [7] vless-инбаунд понимают режим
#      (security из БД); в TLS-режиме 301 = OK, в Reality 200 = OK;
#      неизвестный security -> WARN.
# v0.4.0: ФИКС ЦИКЛА РЕДИРЕКТОВ decoy №2 в TLS-режиме (найден живой приёмкой
#   v0.3.9 на prod-node-1, 2026-10-02). v0.3.9 направлял fallback xray'а на
#   127.0.0.1:80 — а там vhost с "return 301 https://...", и браузер получал
#   301 на тот же https-URL: бесконечный цикл («Циклическое перенаправление»).
#   Healthcheck слепую зону не увидел: curl без -L делает ОДИН запрос, видел
#   честный 301 и пропускал как «фасад». Урок: зонд редиректов обязан смотреть
#   глазами клиента — а клиент следует за 301. ИЗМЕНЕНИЯ: фасад decoy №2
#   переехал на отдельный plain-HTTP vhost 127.0.0.1:8080 (root=/var/www/
#   decoy-reality, loopback-only, ufw не трогается) — пробы теперь получают
#   НАСТОЯЩИЙ decoy-сайт (200), фасад лучше запланированного в v0.3.9.
#   ensure_decoy2_http_vhost() вызывается из install [8/10] и add-vls
#   (идемпотентна). Fallback везде :8080 (install, add-vls; долечка мигрирует
#   и старый :80). hc [6]: ветка «301 = ок» УДАЛЕНА как ошибочная — 301 в
#   TLS-режиме теперь FAIL с диагнозом цикла и командой фикса; штатный
#   исход TLS-режима — 200.
# v0.4.1: МАРКЕР ВЕРСИИ УСТАНОВКИ (запланировано владельцем 2026-10-03).
#   Проблема: не определить, какой версией скрипта ставился/переключался
#   живой сервер — только по памяти и changelog'у. РЕШЕНИЕ: install,
#   add-vls и add-reality при успехе пишут VERSION в
#   /root/.lucx-script-version (install — и строку "Script Version" в креды).
#   add-hy2 и rebind-ip маркер НЕ пишут: семантика маркера — «версия,
#   установившая или переключившая текущую архитектуру сервера», мелкие
#   операции её не меняют. HEALTHCHECK [10]: маркер есть и равен VERSION →
#   OK; маркер СТАРРЕ скрипта → OK с пометкой (штатное состояние после
#   заливки нового скрипта — режимы add-* накатят его при следующем
#   запуске); маркер НОВЕЕ скрипта → WARN (на диске откат?); маркера НЕТ,
#   а схема развёрнута (креды есть) → WARN с готовой командой бэкфилла
#   (все установки до v0.4.1 — флот и старые клиентские серверы: один
#   echo на сервер, после которого сравнение работает). Сравнение версий —
#   через sort -V (GNU). Шапка healthcheck печатает версию управления
#   рядом с версией скрипта. Отличия install-пути от принятого v0.4.0 —
#   только маркер; отдельная приёмка не требуется (bash -n + healthcheck).
# v0.4.2: ГЕО-СТРАЖ — защита от каскадного отказа lucx.278, пойманного живой
#   установкой на сервере №3 (prod-node-4, 2026-10-03). Цепочка: lucx
#   скачивает 8 файлов геоданных; geoip_RU.dat (runetfreedom,
#   releases/latest/download/) отдал 404 — воспроизведено на двух серверах
#   в разных сетях с интервалом 12 часов (при том что из других точек URL
#   отвечает 200, а релизы runetfreedom вокруг инцидентов ассет содержат —
#   видимо, окно публикации/CDN). Дефолтный конфиг панели ссылается на
#   geoip_RU.dat, поэтому xray при его отсутствии ОТКАЗЫВАЕТСЯ СТАРТОВАТЬ
#   (infra/conf: invalid geodata asset file, exit status 23, краш-луп
#   каждые 2 сек) — сервер после установки полностью нерабочий, хотя lucx
#   пишет лишь best-effort предупреждение «update later via x-ui menu».
#   РЕШЕНИЕ: ensure_geodata() — вызывается из install, add-vls/add-reality
#   и add-hy2; проверяет 4 ключевых .dat (geoip/geosite/geoip_RU/geosite_RU),
#   недостающие докачивает (3 попытки, пауза 5с), при безнадёжном
#   geoip_RU.dat — восстанавливает копией полного geoip.dat (Loyalsoldier
#   содержит geoip:ru, ссылки маршрутизации удовлетворяет). Выбор lucx.277
#   вместо .278 от проблемы НЕ защищает: install.sh тегов байт-в-байт
#   идентичен, список URL геоданных тот же — разница только в моменте
#   публикации апстрима. Плюс: [10/10] больше не создаёт дубликат
#   vless-инбаунда при перезапуске прерванной установки — существование
#   проверяется по port+listen+protocol, а не по случайному remark
#   (сценарий «прервал install → перезапустил» реален, см. сервер №3).
# v0.4.3: ФИКС ПО РЕВЬЮ КЛОДА (внешний дифф v0.3.9→v0.4.2, 2026-10-03) —
#   найден пропущенный вызов ensure_decoy2_http_vhost() в cmd_switch_mode:
#   вызов стоял только в ветке «уже TLS, долечиваем fallback» и в install,
#   а в ОСНОВНОМ пути переключения Reality→TLS (целевой сценарий для флота)
#   fallback на :8080 записывался в БД БЕЗ создания самого vhost на 8080 —
#   первый add-vls на Reality-сервере оставлял decoy №2 недоступным (000)
#   до повторного запуска той же команды. ФИКС: ensure_decoy2_http_vhost()
#   вызывается в основном пути перед UPDATE (после проверки сертов, до
#   остановки-перезаписи). Ущерба в момент находки ноль — add-vls ещё не
#   гонялся ни на одном сервере; баг пойман ревью до эксплуатации.
# v0.4.4: HEALTHCHECK [11] — скан открытых (публичных) портов. Повод: кейс
#   клиента (xhttp-инбаунд на публичном порту мимо nginx) — старый healthcheck
#   проверял «порт занят ТЕМ, кем должен», но не замечал посторонних
#   слушателей. Теперь [11] инвентаризирует ВСЕ слушающие сокеты
#   (ss -tlnp/-ulnp) и делит их: loopback — не публичный, пропускается;
#   публичный слушатель обязан быть в белом списке схемы (TCP 22/SSH, 80, 443;
#   UDP 443/hy2 + AWG-порт из БД) ИЛИ разрешён осознанно через
#   файлы-исключения /root/.lucx-public-tcp-ports.txt и
#   /root/.lucx-public-udp-ports.txt (порт на строку, # — комментарий;
#   сценарий — OpenFlux direct 2053). Слушатель вне списка: ufw ALLOW —
#   FAIL (сканер видит); ufw закрыт — WARN (снаружи не виден, но слушает
#   зря). Дубликаты портов схлопываются, имена процессов — из
#   /proc/PID/cmdline, как в [2]. Обратная совместимость полная: серверам
#   со сторонними осознанными портами достаточно один раз создать
#   файл-исключение.
# v0.4.6: HC11 — SSH-ПОРТ В БЕЛОМ СПИСКЕ БЕРЁТСЯ С ФАКТА, А НЕ ХАРДКОДОМ
#   (по ревью Клоуда, внешний аудит v0.4.4, 2026-10-10). Регрессия v0.4.4:
#   HC11_ALLOW_TCP захардкоживал " 22 80 443 ", тогда как install [3/10]
#   с v0.3.8 детектит фактические порты sshd (ss -tlnp | grep sshd) и
#   открывает в ufw именно их. cmd_healthcheck — ОТДЕЛЬНЫЙ прогон скрипта:
#   SSH_PORTS из install в его сессии не существует (ни в файлах, ни в env
#   не сохраняется), поэтому [11] видел собственный штатный SSH-порт как
#   «слушает и разрешён ufw, но НЕ из схемы» — FAIL на каждом прогоне
#   healthcheck на сервере с нестандартным SSH-портом, пока порт не внесёшь
#   руками в файл-исключение. ФИКС: перед формированием HC11_ALLOW_TCP
#   порты sshd пересчитываются той же командой, что в install; пусто →
#   фоллбэк "22 " (зеркалит поведение install'а). Живой флот на 22 не
#   затронут (приёмка №1 63/0 — sshd на 22); мина была под будущие
#   установки с кастомным SSH-портом в образе хостера. v0.4.5 пропущена
#   стабильной линией (экспериментальная xhttp-ветка, направление закрыто).
# v0.4.7: КОМАНДА UPGRADE + INFO о версиях + правила панели в конце install.
#   `upgrade`: качает новейший скрипт с GitHub-репо (raw main) во временный файл,
#   bash -n, сравнение VERSION (актуальна -> no-op), атомарная замена себя
#   (бэкап *.upgrade-old; запущенный bash держит старый inode - безопасно),
#   затем exec healthcheck новой версией. Запуск не из файла (/dev/fd/*) - отказ.
#   healthcheck: INFO «доступна версия X (установлена Y)» через GitHub API
#   (тихо без сети). install: в конце печатает правила «панель: можно / нельзя»
#   (дублируют README; грабли 2026-10-10/11: форма инбаунда теряет proxy protocol
#   и клиентов, TLS<->Reality руками, Masking на 443, порт 8443, диалоги без
#   «Сохранить», неинтерактивный x-ui update без 'y\n4\n').
#   Файл публикуется в репо Shepard86rus/3x-ui-dual-domain (скраб-политика:
#   в комментариях нет хостнеймов/IP/имён клиентов).
#   Патч по ревью Клоуда (2026-10-11): sort -V (защита от даунгрейда при локальной
#   версии новее remote), единый источник версий (raw main для INFO и upgrade,
#   а не releases/latest), tmp рядом со скриптом (rename-атомарность, не
#   copy+unlink через /tmp).
# v0.4.8: ОПЦИОНАЛЬНЫЙ TELEGRAM-БОТ УПРАВЛЕНИЯ (решение владельца 2026-10-13).
#   В конце install вопрос «Поставить Telegram-бота управления? [y/N]» — дефолт НЕТ,
#   шаг полностью пропускается. Если да: токен @BotFather (пусто — вписать позже),
#   Telegram ID (пусто — режим обучения: бот пришлёт chat_id по /start), имя ноды
#   в боте [hostname] — префикс всех ответов. Ставится: /etc/tgbot/env (600:
#   TOKEN/CHAT_ID/NODE_NAME/SCRIPT_PATH), тело бота /opt/tgbot/tgbot.sh,
#   systemd-юнит tgbot (включается только при вписанном токене). Ноль новых
#   открытых портов — бот сам ходит в api.telegram.org (long polling). Команды —
#   карточками: статус/версии/диск/лог/hc/бэкап; деструктив (рестарты, upgrade,
#   update панели) — только через подтверждение кнопками (120 сек). Словарь
#   фиксированный, whitelist по CHAT_ID, чужие молча игнорируются, /exec нет.
#   Новые команды: add-bot (на живую установку; идемпотентен, env не затирает),
#   remove-bot. HEALTHCHECK [12]: юнит/токен/chat_id/версия тела (не установлен —
#   строка-пропуск, не FAIL).
# v0.4.9: ПРЕДОХРАНИТЕЛИ совместимости с панелью .291+ (по живому тесту на №5
#   от 2026-10-13 и двум аудитам Клоуда).
#   (1) ГАРАНТИЯ SQLITE: install.sh уже запускается в NONINTERACTIVE с
#       XUI_DB_TYPE=sqlite (env-блок был и в v0.4.8) — v0.4.9 добавляет
#       ПРОВЕРКУ ФАКТА после install.sh: install-result.env обязан сказать
#       sqlite, иначе СТОП до наших манипуляций с БД (create_hy2_inbound/
#       бэкапы/hc работают с SQLite-файлом; PostgreSQL не поддерживается).
#       Защита от scenario «апстрим изменил обработку env или дефолт».
#   (2) hc [13] «БД и песочница»: (а) БД = SQLite — FAIL при PG; (б) если стоит
#       sandbox-дропин апстрима (10-xui-sandbox.conf, появляется с lucx.291) и в БД
#       есть AWG-инбаунд — требуется 20-local.conf с ReadWritePaths=/etc/amnezia,
#       иначе FAIL: без него панель не может писать /etc/amnezia/amneziawg/*.conf
#       и AWG ляжет при обновлении/рестарте (живой кейс №5 от 2026-10-13 —
#       «read-only file system» каждые 10 сек).
#   (3) ensure_xui_sandbox_awg_dropin(): идемпотентно ставит 20-local.conf при
#       install и после upgrade (на панелях без песочницы безвреден).
#   (4) README: процедура printf для .291+ (SSL-меню исчезло — достаточно 'y'),
#       строки про SQLite и дропин.
#   Тело бота не менялось (маркер поднят до 0.4.9 для консистентности hc [12]).
# v0.5.0: убран drop-in песочницы для AWG (ensure_xui_sandbox_awg_dropin), т.к.
#   lucx.292 (13.10.2026) сам держит /etc/amnezia в ReadWritePaths юнита x-ui.
#   (1) install/upgrade больше не ставят 20-awg-amnezia.conf; команда
#       ensure-awg-dropin оставлена как безвредная заглушка (апгрейд из v0.4.9 её вызывает).
#   (2) hc [13] проверяет факт (systemctl show x-ui -p ReadWritePaths), а не наш файл:
#       FAIL только если AWG-инбаунды есть, а юнит не может писать /etc/amnezia (lucx.291).
#   (3) hc [13]: WARN при подвисаниях диска (PSI full avg300 >= 3%).
#   (4) Бот: «Бэкап БД» через sqlite3 .backup (cp живой БД в WAL даёт неполную копию).
#   (5) Текст ошибки про выбор БД обновлён (меню в install.sh нет, БД передаётся env).
#   Уже стоящие на нодах drop-in'ы безвредны; скрипт их не трогает и не удаляет.
# v0.5.1: реакция на волну блокировок РКН (15.10.2026) + мелкие улучшения.
#   (1) HSTS (max-age=31536000, без includeSubDomains/preload) в трёх шаблонах nginx:
#       decoy2-http (в TLS-режиме именно он отдаёт заглушку: fallback xray ->
#       127.0.0.1:8080), заглушка Reality-домена и vhost домена панели.
#       На УЖЕ установленных нодах конфиги не переписываются (правится вручную).
#   (2) VLESS+TLS: flow=xtls-rprx-vision по умолчанию (install, add-vls, ссылки):
#       убирает отпечаток вложенного TLS. Старые клиенты без flow подключиться не смогут.
#   (3) hc [14] (только INFO, на итог не влияет): число попыток входа на SSH за 1ч/24ч,
#       уникальные адреса, fail2ban (в бане сейчас / всего); подсказка про add-swap.
#   (4) hc [13]: порог PSI вынесен в переменную PSI_WARN_PCT (по умолчанию 3.0).
#   (5) Новые команды add-swap / remove-swap (по явному запуску, не из install).
#   (6) Тексты про маркер версии управления поясняют, что это версия при установке.
# v0.5.2: install не создаёт дубли строк webListen/webPort/webBasePath в settings
#   (INSERT OR IGNORE без уникального индекса по key вставлял вторую строку; теперь
#   INSERT ... SELECT ... WHERE NOT EXISTS, как в блоке подписок).
VERSION="0.5.2"

# CLAUDE-FIX-v203: GITHUB_TOKEN больше не нужен.
# С v3.7.0-lucx.203 install-awg-module.sh качает исходники tarball'ом
# через curl (codeload.github.com), а не git clone.
set -euo pipefail

# ================== Цвета ==================
OK="\033[0;32mOK\033[0m"
FAIL="\033[0;31mFAIL\033[0m"
WARN="\033[0;33mWARN\033[0m"

pass=0
fail=0

# ================== Общие переменные ==================
LUCX_REPO="AlexeyLCP/lucx-ui"
# install.sh теперь качается из того же тега, что и сам lucx-ui,
# а не из main — иначе main может ссылаться на sidecar'ы, которых
# нет в выбранном релизе (например, tproxy 404 в .207).
# LUCX_INSTALL_URL формируется ниже, после выбора LUCX_TAG.
CREDS_FILE="/root/.lucx-credentials"
LOG_FILE="/var/log/lucx-install.log"
XUIDB="/etc/x-ui/x-ui.db"
# v0.5.1: порог WARN по io-давлению диска (PSI full avg300, %); можно переопределить окружением
PSI_WARN_PCT="${PSI_WARN_PCT:-3.0}"

# ================== Общие функции ==================

check() {
  local desc="$1" result="$2"
  if [[ "$result" == "ok" ]]; then
    echo -e "[$OK] $desc"
    pass=$((pass+1))
  elif [[ "$result" == "warn" ]]; then
    echo -e "[$WARN] $desc"
  else
    echo -e "[$FAIL] $desc"
    fail=$((fail+1))
  fi
}

# v0.5.0: функция ensure_xui_sandbox_awg_dropin удалена — с lucx.292 апстрим сам
# держит /etc/amnezia в ReadWritePaths юнита x-ui (см. hc [13]).

read_domains() {
  if [[ -f "$CREDS_FILE" ]]; then
    # || true: битый/пустой creds-файл не должен молча убивать скрипт —
  # пустой DOMAIN ловится валидацией ниже.
  DOMAIN=$(grep -m1 '^URL:' "$CREDS_FILE" | sed -E 's|^URL: ||; s|https://||; s|/.*||' || true)
    DOMAIN="${DOMAIN,,}"
    REALITY_DOMAIN=$(grep '^Reality Domain:' "$CREDS_FILE" | sed 's/Reality Domain: //' || true)
    REALITY_DOMAIN="${REALITY_DOMAIN,,}"
    echo "Домены взяты из ${CREDS_FILE}"
    echo "  Панель:  ${DOMAIN}"
    echo "  Reality: ${REALITY_DOMAIN:-<не найден>}"
    echo
  else
    echo "Введи домены:"
    read -rp "Домен панели (напр. panel.example.com): " DOMAIN
    read -rp "Домен-обложка Reality (напр. reality.example.com): " REALITY_DOMAIN
    echo
  fi
}

get_server_ip() {
  curl -4s --max-time 5 https://api4.ipify.org || curl -4s --max-time 5 ifconfig.me || true
}

# ================== ГЕО-СТРАЖ (v0.4.2) ==================
# lucx_fetch_geofiles в install.sh качает 8 файлов геоданных best-effort; при
# 404 на geoip_RU.dat дефолтный конфиг панели делает xray нерабочим (см.
# changelog v0.4.2). Эта функция проверяет 4 ключевых .dat и докачивает
# недостающие; никогда не валит скрипт — в худшем случае печатает ВНИМАНИЕ.
ensure_geodata() {
  local geo_bin="/usr/local/x-ui/bin"
  local -a glist=(
    "geoip.dat|https://github.com/Loyalsoldier/v2ray-rules-dat/releases/latest/download/geoip.dat"
    "geosite.dat|https://github.com/Loyalsoldier/v2ray-rules-dat/releases/latest/download/geosite.dat"
    "geoip_RU.dat|https://github.com/runetfreedom/russia-v2ray-rules-dat/releases/latest/download/geoip.dat"
    "geosite_RU.dat|https://github.com/runetfreedom/russia-v2ray-rules-dat/releases/latest/download/geosite.dat"
  )
  local entry gfile gurl gok try
  for entry in "${glist[@]}"; do
    gfile="${entry%%|*}"
    gurl="${entry#*|}"
    if [[ -s "${geo_bin}/${gfile}" ]]; then
      continue
    fi
    echo "  Гео-страж: ${gfile} отсутствует — докачиваю (3 попытки)..."
    gok=0
    for try in 1 2 3; do
      if curl -fL --max-time 300 -o "${geo_bin}/${gfile}" "$gurl" 2>/dev/null; then
        gok=1
        break
      fi
      sleep 5
    done
    if [[ "$gok" == "0" && "$gfile" == "geoip_RU.dat" && -s "${geo_bin}/geoip.dat" ]]; then
      if cp "${geo_bin}/geoip.dat" "${geo_bin}/${gfile}"; then
        gok=1
        echo "  Гео-страж: ${gfile} восстановлен копией geoip.dat (Loyalsoldier содержит geoip:ru)"
      fi
    fi
    if [[ "$gok" == "1" ]]; then
      echo "  Гео-страж: ${gfile} на месте"
    else
      echo "  ВНИМАНИЕ: ${gfile} не скачался — xray может не стартовать. Вручную:"
      echo "    curl -fL -o ${geo_bin}/${gfile} '${gurl}'"
    fi
  done
  return 0
}

# ================== HY2: общая функция создания инбаунда ==================
# v0.3.1: используется и полным install ([10a]), и режимом retrofit add-hy2.
# Схема stream_settings/settings снята дампом с рабочей БД lucx-ui .246
# (проверено вживую на тестовом стенде 18 сен 2026) — не угадана.
# masquerade -> decoy-сайт REALITY_DOMAIN (proxy + rewriteHost): чужая
# QUIC-проба получает настоящий сайт. Salamander не включается — дефолт
# чистый QUIC/HTTP/3 (см. changelog). Результаты — в глобальных HY2_*.
create_hy2_inbound() {
  HY2_OK=0
  if [[ ! -f "$XUIDB" ]]; then
    echo "x-ui.db не найден — hy2 не создан."
    return 1
  fi
  if sqlite3 "$XUIDB" "SELECT 1 FROM inbounds WHERE protocol='hysteria' AND port='${REALITY_XRAY_PORT:-443}' LIMIT 1;" 2>/dev/null | grep -q 1; then
    echo "Hy2-инбаунд на порту ${REALITY_XRAY_PORT:-443} уже существует. Пропускаю."
    HY2_OK=1
    return 0
  fi

  # Явные проверки: set -e в теле функции отключён (вызов идёт под "||"),
  # поэтому полагаться на него нельзя — до этого ровно этот код лежал
  # инлайном в cmd_install, где set -e ловил такие провалы сам.
  if ! systemctl stop x-ui; then
    echo "ОШИБКА: не удалось остановить x-ui перед правкой БД. Правка отменена."
    return 1
  fi
  sleep 1
  if ! cp "$XUIDB" "${XUIDB}.backup.$(date +%s)"; then
    echo "ОШИБКА: не удалось сделать бэкап БД."
    systemctl start x-ui
    return 1
  fi

  HY2_TAG="inbound-hy2-$(openssl rand -hex 4)"
  HY2_EMAIL="hy2-$(openssl rand -hex 3)"
  HY2_SUBID=$(openssl rand -hex 8)
  HY2_AUTH=$(openssl rand -hex 8)
  NOW_MS_HY2=$(( $(date +%s) * 1000 ))

  sqlite3 "$XUIDB" <<SQL || {
INSERT INTO "inbounds" ("user_id","up","down","total","remark","enable","expiry_time","listen","port","protocol","settings","stream_settings","tag","sniffing") VALUES (
  '1','0','0','0','Hy2-443','1','0','','${REALITY_XRAY_PORT:-443}','hysteria',
  '{"clients":[{"auth":"${HY2_AUTH}","comment":"","created_at":${NOW_MS_HY2},"email":"${HY2_EMAIL}","enable":true,"expiryTime":0,"limitIp":0,"reset":0,"subId":"${HY2_SUBID}","tgId":0,"totalGB":0,"updated_at":${NOW_MS_HY2}}],"version":2}',
  '{"network":"hysteria","hysteriaSettings":{"version":2,"udpIdleTimeout":60,"masquerade":{"type":"proxy","dir":"","url":"https://${REALITY_DOMAIN}","rewriteHost":true,"insecure":false,"content":"","headers":{},"statusCode":0}},"security":"tls","tlsSettings":{"serverName":"${REALITY_DOMAIN}","minVersion":"1.2","maxVersion":"1.3","cipherSuites":"","rejectUnknownSni":false,"disableSystemRoot":false,"enableSessionResumption":false,"certificates":[{"ocspStapling":0,"oneTimeLoading":false,"usage":"encipherment","buildChain":false,"certificateFile":"/etc/letsencrypt/live/${REALITY_DOMAIN}/fullchain.pem","keyFile":"/etc/letsencrypt/live/${REALITY_DOMAIN}/privkey.pem"}],"alpn":["h3"],"echServerKeys":"","settings":{"echConfigList":"","pinnedPeerCertSha256":[],"verifyPeerCertByName":""}}}',
  '${HY2_TAG}',
  '{"enabled":false,"destOverride":["http","tls","quic","fakedns"],"metadataOnly":false,"routeOnly":false}'
);
SQL
    echo "ОШИБКА: SQLite INSERT hy2 не удался. Бэкап: ${XUIDB}.backup.*"
    systemctl start x-ui
    return 1
  }

  # client_traffics с email из JSON, иначе "Сбросить трафик" падает (как v0.0.3).
  # Явная проверка: функция вызывается под "||", set -e здесь не работает.
  if ! sqlite3 "$XUIDB" "INSERT INTO client_traffics (inbound_id, email, up, down, total, expiry_time, reset, enable) SELECT id, json_extract(settings, '$.clients[0].email'), 0, 0, 0, 0, 0, 1 FROM inbounds WHERE tag='${HY2_TAG}' ON CONFLICT DO NOTHING;"; then
    echo "WARN: client_traffics для hy2 не создан — кнопка 'Сбросить трафик' в панели будет падать."
  fi

  if ! systemctl start x-ui; then
    echo "ОШИБКА: systemctl start x-ui не отработал. Смотри: journalctl -u x-ui -n 50"
    return 1
  fi
  sleep 2
  if ! systemctl is-active --quiet x-ui; then
    echo "ОШИБКА: x-ui не запустился после создания hy2. Смотри: journalctl -u x-ui -n 50"
    return 1
  fi
  # v0.3.7: is-active недостаточен — краш-луп xray-core (дочерний процесс
  # панели) юнит не роняет (урок v0.3.5). Проверяем фактический UDP-листенер
  # hy2-порта и владельца через /proc/PID/cmdline; ретраи на медленный
  # старт ядра.
  HY2_UDP_PID=""
  for _ in 1 2 3 4 5; do
    HY2_UDP_PID=$(ss -ulnp 2>/dev/null | grep -E ":${REALITY_XRAY_PORT:-443} " | grep -oP 'pid=\K[0-9]+' | head -n1 || true)
    if [[ -n "$HY2_UDP_PID" ]] && tr '\0' ' ' < "/proc/${HY2_UDP_PID}/cmdline" 2>/dev/null | grep -qi xray; then
      break
    fi
    HY2_UDP_PID=""
    sleep 2
  done
  if [[ -z "$HY2_UDP_PID" ]]; then
    echo "ОШИБКА: xray не подтверждён на UDP/${REALITY_XRAY_PORT:-443} после старта (порт не слушается или владелец не xray — краш-луп?). Смотри: journalctl -u x-ui -n 50"
    return 1
  fi
  HY2_OK=1
  return 0
}

# ================== РЕЖИМ: ADD-HY2 (ретрофит на существующий сервер) ==================
# v0.3.1: cmd_install валиден только для чистого сервера (preflight-проверки
# портов упрутся в уже работающую схему). Этот режим добавляет hy2 на сервер
# с развёрнутой v0.3.0-схемой: читает домены из кредов, проверяет сертификаты
# и свободность UDP/443, вставляет инбаунд, чинит cron deploy-hook, пишет креды.
# Не трогает nginx, decoy, подписки, Reality и AWG (AWG при необходимости
# переезжает с 443 вручную через панель ДО запуска этого режима).
cmd_add_hy2() {
  if [[ $EUID -ne 0 ]]; then
    echo "Запусти от root: sudo bash $0 add-hy2"
    exit 1
  fi
  REALITY_XRAY_PORT=443
  read_domains
  if [[ -z "${DOMAIN:-}" || -z "${REALITY_DOMAIN:-}" ]]; then
    echo "ОШИБКА: не удалось определить домены из ${CREDS_FILE}."
    exit 1
  fi

  echo "Ретрофит Hysteria 2 на ${REALITY_DOMAIN} (UDP/443)"
  echo

  if [[ ! -f "$XUIDB" ]]; then
    echo "ОШИБКА: ${XUIDB} не найден — на этом сервере не развёрнута схема скрипта."
    exit 1
  fi
  ensure_geodata
  for f in "/etc/letsencrypt/live/${REALITY_DOMAIN}/fullchain.pem" "/etc/letsencrypt/live/${REALITY_DOMAIN}/privkey.pem"; do
    if [[ ! -f "$f" ]]; then
      echo "ОШИБКА: сертификат ${f} не найден."
      exit 1
    fi
  done
  if ss -ulnp 2>/dev/null | grep -qE '(\*|0\.0\.0\.0):443 '; then
    echo "ОШИБКА: UDP/443 уже занят:"
    ss -ulnp | grep ':443 ' || true
    echo "Если там AWG — переедь его на другой порт в панели (AmneziaWG -> порт),"
    echo "обнови ufw (ufw allow <новый_порт>/udp) и перезапусти этот режим."
    exit 1
  fi
  # v0.3.7: ss -ulnp НЕ видит kernel-интерфейс AmneziaWG (awg2 держит порт
  # мимо socket-таблицы, ограничение известно со времён v0.1.6/v0.1.8).
  # Аудитория add-hy2 — как раз серверы до v0.3.1 с AWG на 443/udp: раньше
  # проверка проходила, hy2 вставлялся поверх занятого порта, xray уходил
  # в краш-луп. Второй preflight — через awg show, как в healthcheck [2].
  if command -v awg >/dev/null 2>&1 && awg show 2>/dev/null | grep -qE '^  listening port: 443$'; then
    echo "ОШИБКА: UDP/443 занят kernel-интерфейсом AmneziaWG (awg show подтверждает; в ss он не виден)."
    echo "Переедь AWG на другой порт в панели (AmneziaWG -> порт),"
    echo "обнови ufw (ufw allow <новый_порт>/udp) и перезапусти этот режим."
    exit 1
  fi
  if ! systemctl is-active --quiet x-ui; then
    echo "ОШИБКА: x-ui не запущен. Сначала подними панель."
    exit 1
  fi

  create_hy2_inbound || exit 1

  # deploy-hook cron: xray читает серты при старте, нужен restart после renew
  if ! crontab -l 2>/dev/null | grep 'certbot renew' | grep -q 'restart x-ui'; then
    # v0.3.7: '|| true' после grep ОБЯЗАТЕЛЕН. grep -v — ПОСЛЕДНИЙ элемент
    # внутреннего пайпа, его провал (нет crontab у root / все строки были
    # certbot-овыми) НЕ подавляется правилом «не-последние элементы пайпа»
    # и под set -e убивал сабшелл ДО echo: на свежем сервере строка renew
    # не ставилась, при повторном — crontab - получал пустоту и СТИРАЛ
    # старую строку renew. Внешний пайп возвращал 1 — set -e ронял скрипт.
    ( crontab -l 2>/dev/null | grep -v 'certbot renew' || true ; \
      echo "0 0 * * * certbot renew --quiet --deploy-hook 'systemctl reload nginx && systemctl restart x-ui'" ) | crontab -
    echo "cron: deploy-hook certbot обновлён (restart x-ui добавлен)"
  fi

  # креды
  if [[ -f "$CREDS_FILE" ]] && [[ -n "${HY2_AUTH:-}" ]]; then
    grep -q '^Hy2 Auth:' "$CREDS_FILE" || cat >> "$CREDS_FILE" <<EOF

# Hysteria 2 (add-hy2, $(date -Iseconds))
Hy2 Tag: ${HY2_TAG}
Hy2 Client Email: ${HY2_EMAIL}
Hy2 Auth: ${HY2_AUTH}
Hy2 Link: hysteria2://${HY2_AUTH}@${REALITY_DOMAIN}:443/?sni=${REALITY_DOMAIN}&insecure=0#Hy2-443
EOF
    chmod 600 "$CREDS_FILE"
  fi

  if [[ -n "${HY2_AUTH:-}" ]]; then
    echo
    echo "================= HY2 ГОТОВО ================="
    echo "Hysteria 2: UDP/443, masquerade -> https://${REALITY_DOMAIN}"
    echo "Ссылка: hysteria2://${HY2_AUTH}@${REALITY_DOMAIN}:443/?sni=${REALITY_DOMAIN}&insecure=0#Hy2-443"
    echo "Далее: bash $0 healthcheck — блок Hy2 должен быть зелёным."
    echo "================================================"
  else
    # Идемпотентность: hy2 уже существовал, HY2_AUTH не генерировался заново.
    echo
    echo "Hy2 уже был настроен ранее — ничего не менялось."
    echo "Ссылка и креды: ${CREDS_FILE} (строки Hy2 *)."
    echo "Проверка: bash $0 healthcheck"
  fi
}

# v0.4.0: plain-HTTP фасад decoy №2 — цель fallback'а TLS-режима (loopback
# :8080). v0.3.9 направлял fallback на :80, где vhost отдаёт 301 https->сам
# на себя: браузеры уходили в бесконечный цикл (найдено живой приёмкой).
# Отдельный plain-HTTP vhost с содержимым decoy отдаёт пробам настоящий сайт.
ensure_decoy2_http_vhost() {
  if [[ -f /etc/nginx/sites-enabled/decoy2-http.conf ]] && \
     grep -qF "listen 127.0.0.1:8080" /etc/nginx/sites-enabled/decoy2-http.conf 2>/dev/null; then
    return 0
  fi
  cat > /etc/nginx/sites-available/decoy2-http.conf <<EOF
server {
    listen 127.0.0.1:8080;
    server_name ${REALITY_DOMAIN};
    server_tokens off;
    add_header Strict-Transport-Security "max-age=31536000" always;
    root /var/www/decoy-reality;
    index index.html;
    error_page 404 /404.html;
    location / { try_files \$uri \$uri/ =404; }
}
EOF
  ln -sf /etc/nginx/sites-available/decoy2-http.conf /etc/nginx/sites-enabled/decoy2-http.conf
  if ! nginx -t 2>/dev/null; then
    echo "ОШИБКА: nginx -t не прошёл после создания decoy2-http.conf"
    return 1
  fi
  systemctl reload nginx
}

# ================== РЕЖИМ: ADD-VLS / ADD-REALITY (переключение режима 443) ==================
# v0.3.9: перевод существующего сервера между vless+TLS и Reality без
# переустановки. UUID/subId/клиенты НЕ меняются — обновляются только
# settings (flow/fallbacks) и stream_settings инбаунда 127.0.0.1:443.
# Уход с Reality сохраняет его stream_settings в /root/.lucx-mode-backup/,
# и add-reality восстанавливает ИМЕННО их (те же ключи/shortIds — клиентские
# ссылки с pbk оживают без перевыпуска). Если бэкапа нет — Reality
# генерируется заново с НОВЫМИ ключами (владельцу печатается новый pbk).
cmd_switch_mode() {
  local target="$1"
  if [[ $EUID -ne 0 ]]; then
    echo "Запусти от root: sudo bash $0 add-vls | add-reality"
    exit 1
  fi
  read_domains
  if [[ -z "${DOMAIN:-}" || -z "${REALITY_DOMAIN:-}" ]]; then
    echo "ОШИБКА: домены не определены из ${CREDS_FILE}."
    exit 1
  fi
  if [[ ! -f "$XUIDB" ]]; then
    echo "ОШИБКА: ${XUIDB} не найден — схема не развёрнута."
    exit 1
  fi
  ensure_geodata

  local cur_sec uuid
  cur_sec=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'\$.security') FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1' LIMIT 1;" 2>/dev/null || true)
  echo "Текущий security инбаунда 127.0.0.1:443: ${cur_sec:-<не найден>}"
  if [[ -z "$cur_sec" ]]; then
    echo "ОШИБКА: vless-инбаунд на 127.0.0.1:443 не найден — переключать нечего."
    exit 1
  fi
  if [[ "$cur_sec" == "$target" ]]; then
    if [[ "$target" == "tls" ]]; then
      # долечка ручного эксперимента: TLS уже включён, но fallback мог
      # не быть настроен (панельная форма его не добавляет)
      local has_fb
      has_fb=$(sqlite3 "$XUIDB" "SELECT json_extract(settings,'\$.fallbacks[0].dest') FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1' LIMIT 1;" 2>/dev/null || true)
      if [[ "$has_fb" == "127.0.0.1:8080" ]]; then
        echo "Уже в TLS-режиме с fallback'ом — ничего не делаю."
        exit 0
      fi
      echo "Уже в TLS-режиме; перенаправляю fallback на :8080 (фасад decoy, v0.4.0)..."
      systemctl stop x-ui
      sleep 1
      cp "$XUIDB" "${XUIDB}.backup.$(date +%s)"
      ensure_decoy2_http_vhost || { systemctl start x-ui; echo "ОШИБКА: не создать decoy2-http vhost."; exit 1; }
      if ! sqlite3 "$XUIDB" "UPDATE inbounds SET settings = json_set(settings, '\$.fallbacks', json('[{\"dest\":\"127.0.0.1:8080\",\"xver\":0}]')) WHERE protocol='vless' AND port=443 AND listen='127.0.0.1';"; then
        echo "ОШИБКА: не удалось добавить fallback. Бэкап: ${XUIDB}.backup.*"
        systemctl start x-ui
        exit 1
      fi
      systemctl start x-ui
      sleep 2
      if ! systemctl is-active --quiet x-ui; then
        echo "ОШИБКА: x-ui не запустился после добавления fallback."
        exit 1
      fi
      # v0.3.7-приём: is-active не ловит краш-луп ядра — верифицируем листенер
      local fb_pid="" i
      for i in 1 2 3 4 5; do
        fb_pid=$(ss -tlnp 2>/dev/null | grep -E '127\.0\.0\.1:443\b' | grep -oP 'pid=\K[0-9]+' | head -n1 || true)
        if [[ -n "$fb_pid" ]] && tr '\0' ' ' < "/proc/${fb_pid}/cmdline" 2>/dev/null | grep -qi xray; then
          break
        fi
        fb_pid=""
        sleep 2
      done
      if [[ -z "$fb_pid" ]]; then
        echo "ОШИБКА: xray не слушает 127.0.0.1:443 после добавления fallback (краш-луп?). Бэкап БД: ${XUIDB}.backup.*"
        exit 1
      fi
      echo "Готово: fallback на :8080, xray подтверждён на 127.0.0.1:443. Пробы на https://${REALITY_DOMAIN} получают decoy-сайт (200)."
      echo "$VERSION" > /root/.lucx-script-version
      exit 0
    fi
    echo "Уже в Reality-режиме — ничего не делаю."
    exit 0
  fi

  local now_ms
  now_ms=$(( $(date +%s) * 1000 ))
  uuid=$(sqlite3 "$XUIDB" "SELECT json_extract(settings,'\$.clients[0].id') FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1' LIMIT 1;" 2>/dev/null || true)
  if [[ -z "$uuid" ]]; then
    echo "ОШИБКА: не прочитал UUID клиента из инбаунда."
    exit 1
  fi

  echo "Переключаю 443: ${cur_sec} -> ${target}. x-ui будет перезапущен (сессии оборвутся)."
  systemctl stop x-ui
  sleep 1
  mkdir -p /root/.lucx-mode-backup
  cp "$XUIDB" "${XUIDB}.backup.$(date +%s)"
  local stream_backup="" stamp2
  stamp2=$(date +%Y%m%d-%H%M%S)

  if [[ "$target" == "tls" ]]; then
    if [[ ! -f "/etc/letsencrypt/live/${REALITY_DOMAIN}/fullchain.pem" || ! -f "/etc/letsencrypt/live/${REALITY_DOMAIN}/privkey.pem" ]]; then
      echo "ОШИБКА: серт ${REALITY_DOMAIN} не найден в /etc/letsencrypt/live/ — TLS невозможен. Отменено."
      systemctl start x-ui
      exit 1
    fi
    ensure_decoy2_http_vhost || { systemctl start x-ui; echo "ОШИБКА: не создать decoy2-http vhost."; exit 1; }
    stream_backup="/root/.lucx-mode-backup/stream-reality-${stamp2}.json"
    sqlite3 "$XUIDB" "SELECT stream_settings FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1' LIMIT 1;" > "$stream_backup"
    if ! sqlite3 "$XUIDB" "UPDATE inbounds SET settings = json_set(settings, '\$.clients[0].flow', 'xtls-rprx-vision', '\$.fallbacks', json('[{\"dest\":\"127.0.0.1:8080\",\"xver\":0}]')), stream_settings = json('{\"network\":\"tcp\",\"security\":\"tls\",\"tlsSettings\":{\"serverName\":\"${REALITY_DOMAIN}\",\"minVersion\":\"1.2\",\"maxVersion\":\"1.3\",\"cipherSuites\":\"\",\"rejectUnknownSni\":false,\"disableSystemRoot\":false,\"enableSessionResumption\":false,\"certificates\":[{\"ocspStapling\":0,\"oneTimeLoading\":false,\"usage\":\"encipherment\",\"buildChain\":false,\"certificateFile\":\"/etc/letsencrypt/live/${REALITY_DOMAIN}/fullchain.pem\",\"keyFile\":\"/etc/letsencrypt/live/${REALITY_DOMAIN}/privkey.pem\"}],\"alpn\":[\"http/1.1\"],\"echServerKeys\":\"\",\"settings\":{\"echConfigList\":\"\",\"pinnedPeerCertSha256\":[],\"verifyPeerCertByName\":\"\"}},\"tcpSettings\":{\"acceptProxyProtocol\":true,\"header\":{\"type\":\"none\"}}}') WHERE protocol='vless' AND port=443 AND listen='127.0.0.1';"; then
      echo "ОШИБКА: UPDATE не удался. Бэкап БД: ${XUIDB}.backup.*, stream: ${stream_backup}"
      systemctl start x-ui
      exit 1
    fi
    echo "stream_settings переключены на TLS (серт ${REALITY_DOMAIN}, ALPN http/1.1)."
  else
    local latest json1 xray_bin keys_out priv pub s1 s2
    latest=$(ls -1t /root/.lucx-mode-backup/stream-reality-*.json 2>/dev/null | head -n1 || true)
    if [[ -n "$latest" ]]; then
      stream_backup="$latest"
      json1=$(tr -d '\n\r' < "$latest" | sed "s/'/''/g")
      if ! sqlite3 "$XUIDB" "UPDATE inbounds SET stream_settings = json('${json1}') WHERE protocol='vless' AND port=443 AND listen='127.0.0.1';"; then
        echo "ОШИБКА: не удалось восстановить Reality-stream из ${latest}."
        systemctl start x-ui
        exit 1
      fi
      echo "Восстановлен сохранённый Reality-stream из ${latest} (те же ключи/shortIds)."
    else
      xray_bin=$(find /usr/local/x-ui -maxdepth 3 -name "xray-linux-*" -type f 2>/dev/null | head -n1 || true)
      if [[ -z "$xray_bin" ]]; then
        echo "ОШИБКА: xray не найден — генерация Reality-ключей невозможна."
        systemctl start x-ui
        exit 1
      fi
      keys_out=$("$xray_bin" x25519 2>/dev/null || true)
      priv=$(echo "$keys_out" | jq -r '.privateKey // empty' 2>/dev/null || echo "$keys_out" | grep -oP '(?<=Private key: ).*' || true)
      pub=$(echo "$keys_out" | jq -r '.publicKey // empty' 2>/dev/null || echo "$keys_out" | grep -oP '(?<=Public key: ).*' || true)
      if [[ -z "$priv" || -z "$pub" ]]; then
        echo "ОШИБКА: не сгенерировать Reality-ключи."
        systemctl start x-ui
        exit 1
      fi
      s1=$(openssl rand -hex 8)
      s2=$(openssl rand -hex 8)
      if ! sqlite3 "$XUIDB" "UPDATE inbounds SET stream_settings = json('{\"network\":\"tcp\",\"security\":\"reality\",\"realitySettings\":{\"show\":false,\"dest\":\"127.0.0.1:8444\",\"xver\":0,\"serverNames\":[\"${REALITY_DOMAIN}\"],\"privateKey\":\"${priv}\",\"minClient\":\"\",\"maxClient\":\"\",\"maxTimediff\":0,\"shortIds\":[\"${s1}\",\"${s2}\"],\"settings\":{\"publicKey\":\"${pub}\",\"fingerprint\":\"chrome\",\"serverName\":\"\",\"spiderX\":\"/\"}},\"tcpSettings\":{\"acceptProxyProtocol\":true,\"header\":{\"type\":\"none\"}}}') WHERE protocol='vless' AND port=443 AND listen='127.0.0.1';"; then
        echo "ОШИБКА: UPDATE не удался."
        systemctl start x-ui
        exit 1
      fi
      echo "ВНИМАНИЕ: Reality-бэкапа не было — сгенерированы НОВЫЕ ключи."
      echo "Новый Public key для клиентских ссылок: ${pub}"
    fi
    if ! sqlite3 "$XUIDB" "UPDATE inbounds SET settings = json_set(settings, '\$.clients[0].flow', 'xtls-rprx-vision', '\$.fallbacks', json('[]')) WHERE protocol='vless' AND port=443 AND listen='127.0.0.1';"; then
      echo "ОШИБКА: не вернуть flow/fallbacks."
      systemctl start x-ui
      exit 1
    fi
  fi

  systemctl start x-ui
  sleep 2
  if ! systemctl is-active --quiet x-ui; then
    echo "ОШИБКА: x-ui не запустился. Откат stream_settings: ${stream_backup:-<нет>}; бэкап БД: ${XUIDB}.backup.*"
    exit 1
  fi
  # фактический листенер — тот же приём, что в install [10/10] (v0.3.7)
  local ok_pid="" i
  for i in 1 2 3 4 5; do
    ok_pid=$(ss -tlnp 2>/dev/null | grep -E '127\.0\.0\.1:443\b' | grep -oP 'pid=\K[0-9]+' | head -n1 || true)
    if [[ -n "$ok_pid" ]] && tr '\0' ' ' < "/proc/${ok_pid}/cmdline" 2>/dev/null | grep -qi xray; then
      break
    fi
    ok_pid=""
    sleep 2
  done
  if [[ -z "$ok_pid" ]]; then
    echo "ОШИБКА: xray не слушает 127.0.0.1:443 после переключения."
    echo "Откат: stream из ${stream_backup:-/root/.lucx-mode-backup/} и/или БД ${XUIDB}.backup.*"
    exit 1
  fi

  echo "$VERSION" > /root/.lucx-script-version
  echo
  echo "================= ГОТОВО ================="
  echo "Режим 443: ${cur_sec} -> ${target}"
  if [[ "$target" == "tls" ]]; then
    echo "Ссылка для клиентов (fp из рабочей связки RU-клиентов):"
    echo "  vless://${uuid}@${REALITY_DOMAIN}:443?type=tcp&security=tls&sni=${REALITY_DOMAIN}&fp=firefox&flow=xtls-rprx-vision#vls"
  else
    echo "Public key (сверь с клиентскими ссылками):"
    sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'\$.realitySettings.settings.publicKey') FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1' LIMIT 1;" 2>/dev/null || true
  fi
  echo "Клиенты на подписке обновятся сами; ручные ссылки — перевыпустить."
  echo "Проверка: bash $0 healthcheck (блоки [6]/[7] учитывают режим)."
  echo "=========================================="
}

# ================== РЕЖИМ: INSTALL ==================


cmd_install() {
  if [[ $EUID -ne 0 ]]; then
    echo "Запусти от root: sudo bash $0 install"
    exit 1
  fi

  # Логирование
  # v0.3.7: в лог попадают креды панели (username/password, hy2-ссылка с
  # auth-паролем, секретные пути подписок) — файл должен быть 600 с первого
  # байта. tee -a права существующего файла не меняет, поэтому touch+chmod
  # ДО exec-перенаправления. umask 077 на весь install НЕ ставится:
  # decoy-файлы и webroot должны остаться читаемыми www-data.
  mkdir -p "$(dirname "$LOG_FILE")"
  if ! touch "$LOG_FILE" || ! chmod 600 "$LOG_FILE"; then
    echo "ОШИБКА: не удалось создать ${LOG_FILE} с правами 600."
    exit 1
  fi
  exec > >(tee -a "$LOG_FILE") 2>&1

  cleanup() {
    if [[ "${INSTALL_SUCCESS:-0}" != "1" ]]; then
      echo "[cleanup] Восстанавливаю x-ui..."
      systemctl start x-ui 2>/dev/null || true
    fi
  }
  # v0.3.7: только EXIT. Раньше cleanup висел и на INT/TERM: обработчик
  # сигнала не завершает скрипт — дальше set -e его ронял, и EXIT-ловушка
  # выполняла cleanup второй раз. С одним EXIT сигнал по-прежнему доходит
  # до cleanup: прерывает текущую команду, set -e завершает скрипт, ловушка
  # срабатывает один раз.
  trap cleanup EXIT

  echo "======================================================"
  echo " lucx-ui + два домена + Reality на 443 (install mode)"
  echo " Версия скрипта: ${VERSION}"
  echo "======================================================"
  read -rp "Домен панели (напр. panel.example.com): " DOMAIN
  echo
  read -rp "Домен-обложка для Reality (напр. reality.example.com): " REALITY_DOMAIN
  DOMAIN="${DOMAIN,,}"
  REALITY_DOMAIN="${REALITY_DOMAIN,,}"
  echo
  read -rp "SubPath панели [по умолчанию /panel/]: " PANEL_PATH
  echo
  PANEL_PATH=${PANEL_PATH:-/panel/}
  [[ "$PANEL_PATH" != */ ]] && PANEL_PATH="${PANEL_PATH}/"
  [[ "$PANEL_PATH" != /* ]] && PANEL_PATH="/${PANEL_PATH}"
  PANEL_BASEPATH_NOSLASH="${PANEL_PATH#/}"
  PANEL_BASEPATH_NOSLASH="${PANEL_BASEPATH_NOSLASH%/}"

  # Валидация
  for d in "$DOMAIN" "$REALITY_DOMAIN"; do
    if [[ ! "$d" =~ ^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?\.[a-zA-Z]{2,}$ ]]; then
      echo "ОШИБКА: '$d' не похоже на валидный домен."
      exit 1
    fi
  done
  if [[ "$DOMAIN" == "$REALITY_DOMAIN" ]]; then
    echo "ОШИБКА: домены должны быть разными."
    exit 1
  fi

  PANEL_PORT=$(( (RANDOM % 40000) + 20000 ))
  PANEL_INTERNAL_PORT=8443
  REALITY_DECOY_INTERNAL_PORT=8444
  REALITY_XRAY_PORT=443
  SUB_PORT=2096
  SUB_SECRET_PATH="/sb-$(openssl rand -hex 4)/"
  AWG_SECRET_PATH="/awg-$(openssl rand -hex 4)/"
  REALITY_REMARK="reality-$(openssl rand -hex 4)"
  REALITY_TAG="inbound-$(openssl rand -hex 4)"
  # v0.3.1: AWG живёт на отдельном UDP-порте (443/udp занимает hy2)
  read -rp "Порт AmneziaWG [Enter = 52911]: " AWG_PORT
  AWG_PORT="${AWG_PORT:-52911}"
  if [[ "$AWG_PORT" == "443" ]]; then
    echo "ОШИБКА: 443/udp занят Hysteria 2. Выбери другой порт для AWG."
    exit 1
  fi
  if ! [[ "$AWG_PORT" =~ ^[0-9]+$ ]] || (( AWG_PORT < 1 || AWG_PORT > 65535 )); then
    echo "ОШИБКА: '${AWG_PORT}' не похоже на валидный порт."
    exit 1
  fi

  # v0.3.9: режим vless на 443. Дефолт — VLESS+TLS: по эмпирике владельца
  # (2026-09-30, живой тест на prod-node-1) Reality на новых ядрах с
  # fp=firefox не работает, а chrome/остальные отпечатки режутся на
  # RU-маршрутах; plain-TLS работает. Reality остаётся вариантом для
  # не-RU клиентов и на случай послаблений.
  read -rp "Протокол vless на 443: [1] VLESS+TLS (RU-совместимо; Enter) / [2] Reality: " PROTO_CHOICE
  VLESS_MODE="tls"
  [[ "${PROTO_CHOICE:-}" == "2" ]] && VLESS_MODE="reality"
  echo "  Режим 443: ${VLESS_MODE}"

  SERVER_IP=$(get_server_ip)
  if [[ -z "$SERVER_IP" ]]; then
    echo "Не удалось автоматически определить публичный IP сервера."
    read -rp "Введи публичный IPv4 сервера вручную: " SERVER_IP
  fi
  if [[ -z "$SERVER_IP" ]]; then
    echo "ОШИБКА: не удалось определить публичный IP."
    exit 1
  fi

  echo
  echo "Домен панели:          $DOMAIN"
  echo "Домен-обложка Reality: $REALITY_DOMAIN"
  echo "SubPath панели:        $PANEL_PATH"
  echo "SubPath подписок:      $SUB_SECRET_PATH"
  echo "Публичный IP:          $SERVER_IP"
  echo "Ядро панели:           lucx-ui (AWG 3.1 нативно)"
  echo
  read -rp "Погнали? [y/N]: " CONFIRM
  [[ "$CONFIRM" =~ ^[Yy]$ ]] || { echo "Отменено."; exit 0; }

  # --- [1/10] Пакеты ---
  echo "=== [1/10] Базовые пакеты ==="
  apt-get update -y
  apt-get install -y --no-install-recommends \
    curl wget sudo tar unzip git nginx libnginx-mod-stream certbot \
    sqlite3 ufw cron socat openssl dnsutils jq
  systemctl enable cron
  systemctl start cron

  # --- [2/10] Проверки окружения ---
  echo "=== [2/10] Проверки окружения ==="
  for d in "$DOMAIN" "$REALITY_DOMAIN"; do
    resolved=$(dig +short A "$d" @1.1.1.1 | head -n1 || true)
    if [[ -z "$resolved" ]]; then
      resolved=$(getent hosts "$d" | awk '{print $1}' | head -n1 || true)
    fi
    if [[ "$resolved" != "$SERVER_IP" ]]; then
      echo "ОШИБКА: $d резолвится на '${resolved:-не найден}', а не на $SERVER_IP"
      exit 1
    fi
    echo "  DNS OK: $d -> $resolved"
  done

  # v0.3.8: AAAA-префлайт. Схема IPv4-only: nginx и stream-роутер биндят
  # только IPv4, а Let's Encrypt при наличии AAAA-записи предпочитает её и
  # не достучится («Timeout during connect»). Ловим ДО установки: сейчас —
  # громкий стоп с внятной причиной, а не загадочное падение certbot на [6/10].
  # К этому моменту dig уже доказанно работает (A-проверка выше прошла).
  for d in "$DOMAIN" "$REALITY_DOMAIN"; do
    aaaa=$(dig +short AAAA "$d" @1.1.1.1 | head -n1 || true)
    if [[ -n "$aaaa" ]]; then
      echo "ОШИБКА: у $d есть AAAA-запись (${aaaa})."
      echo "Схема IPv4-only: nginx и stream-роутер слушают только IPv4 — Let's Encrypt"
      echo "пойдёт по IPv6 и не достучится. Убери AAAA-запись у регистратора и перезапусти установку."
      exit 1
    fi
    echo "  AAAA OK: $d -> нет (схема IPv4-only)"
  done

  if ss -tlnp 2>/dev/null | grep -q ':443 '; then
    echo "ОШИБКА: порт 443 уже занят:"
    ss -tlnp | grep ':443 ' || true
    exit 1
  fi
  for p in 8443 8444 2096; do
    if ss -tlnp 2>/dev/null | grep -q ":$p "; then
      echo "ОШИБКА: порт $p уже занят"
      ss -tlnp | grep ":$p " || true
      exit 1
    fi
  done

  # v0.3.1: UDP-порты будущих протоколов (hy2 займёт 443/udp, AWG — AWG_PORT)
  if ss -ulnp 2>/dev/null | grep -qE '(\*|0\.0\.0\.0):443 '; then
    echo "ОШИБКА: UDP/443 уже занят:"
    ss -ulnp | grep ':443 ' || true
    exit 1
  fi
  if ss -ulnp 2>/dev/null | grep -q ":${AWG_PORT} "; then
    echo "ОШИБКА: UDP/${AWG_PORT} (AWG) уже занят"
    ss -ulnp | grep ":${AWG_PORT} " || true
    exit 1
  fi

  # --- [3/10] ufw ---
  echo "=== [3/10] ufw ==="
  # v0.3.8: SSH-порт берётся с ЗАПУЩЕННОГО sshd, а не вслепую 22/tcp — на
  # сервере с кастомным портом слепой allow 22 не спасал бы от блокировки
  # после "ufw --force enable". Открываются все порты, на которых sshd слушает.
  # ufw allow БЕЗ "|| true": упасть до --force enable безопаснее, чем включить
  # ufw без подтверждённого SSH-правила.
  SSH_PORTS=$(ss -tlnp 2>/dev/null | grep 'sshd' | grep -oP ':\K[0-9]+(?= )' | sort -u || true)
  if [[ -n "$SSH_PORTS" ]]; then
    for p in $SSH_PORTS; do
      ufw allow "${p}/tcp"
      echo "  ufw: sshd слушает ${p}/tcp — открыл ${p}/tcp"
    done
    if [[ ! "$SSH_PORTS" =~ (^|[[:space:]])22([[:space:]]|$) ]]; then
      echo "  ВНИМАНИЕ: SSH на нестандартном порту(ах): $(echo $SSH_PORTS) — 22 НЕ открывал."
    fi
  else
    ufw allow 22/tcp || true
    echo "  ufw: sshd не определён по ss — открыл 22/tcp по умолчанию."
    echo "  ВНИМАНИЕ: ЕСЛИ SSH НА ДРУГОМ ПОРТУ — после enable доступ отрежется. Проверь!"
  fi
  ufw allow 80/tcp
  ufw allow 443/tcp
  ufw allow 443/udp
  ufw allow ${AWG_PORT}/udp
  ufw --force enable

  # --- [4/10] AWG module review ---
  echo "=== [4/10] Проверка install-awg-module.sh ==="
  arch_detect() {
    case "$(uname -m)" in
      x86_64 | amd64) echo 'amd64' ;;
      i*86) echo '386' ;;
      aarch64 | arm64) echo 'arm64' ;;
      armv7*) echo 'armv7' ;;
      armv6*) echo 'armv6' ;;
      *) echo 'amd64' ;;
    esac
  }
  ARCH=$(arch_detect)
  # v0.2.4: матрица сборки lucx-ui v3.8.0-lucx.231+ публикует ТОЛЬКО
  # amd64 и arm64 (armv7/v6/386 больше не собираются — см. release.yml,
  # LUCX-HOOK в matrix.platform). Раньше на таких архитектурах curl
  # молча скачивал 404-страницу GitHub вместо tarball'а, tar падал с
  # "not in gzip format" по HTML. Отсекаем рано и с понятной ошибкой.
  if [[ "$ARCH" != "amd64" && "$ARCH" != "arm64" ]]; then
    echo "ОШИБКА: архитектура '${ARCH}' не поддерживается lucx-ui v3.8.0-lucx.231+."
    echo "Публикуемые тарболлы: x-ui-linux-amd64.tar.gz, x-ui-linux-arm64.tar.gz."
    echo "Для ${ARCH} бери lucx-ui постарше (до v3.8.0-lucx.231) или amd64/arm64 хост."
    exit 1
  fi
  REVIEW_DIR="/root/.lucx-ui-review"
  mkdir -p "$REVIEW_DIR"
  cd "$REVIEW_DIR"

  # Выбор версии lucx-ui:
  #   - если задана переменная LUCX_PIN_VERSION — берём её без вопросов
  #     (удобно для повторных/автоматических установок на уже проверенную версию)
  #   - иначе, если запуск интерактивный (есть терминал) — показываем список
  #     последних 10 стабильных релизов и даём выбрать (Enter = последняя)
  #   - иначе (неинтерактивный запуск, например через cron) — молча берём
  #     последнюю, чтобы скрипт не завис в ожидании ввода
  if [[ -n "${LUCX_PIN_VERSION:-}" ]]; then
    LUCX_TAG="$LUCX_PIN_VERSION"
    echo "Версия зафиксирована через LUCX_PIN_VERSION: ${LUCX_TAG}"
  else
    echo "Спрашиваю у GitHub список последних релизов lucx-ui..."
    RELEASES_JSON=$(curl -Ls "https://api.github.com/repos/${LUCX_REPO}/releases?per_page=10")
    mapfile -t RELEASE_TAGS < <(echo "$RELEASES_JSON" | jq -r '.[] | select(.prerelease == false) | .tag_name')

    if [[ ${#RELEASE_TAGS[@]} -eq 0 ]]; then
      echo "Не удалось получить список релизов lucx-ui. Прерываю."
      exit 1
    fi

    if [[ -t 0 ]]; then
      echo
      echo "Доступные версии lucx-ui (последние ${#RELEASE_TAGS[@]} стабильных):"
      for i in "${!RELEASE_TAGS[@]}"; do
        num=$((i + 1))
        if [[ "$num" == "1" ]]; then
          echo "  ${num}) ${RELEASE_TAGS[$i]}  (последняя)"
        else
          echo "  ${num}) ${RELEASE_TAGS[$i]}"
        fi
      done
      echo
      read -rp "Выбери номер версии для установки [Enter = 1, последняя]: " VERSION_CHOICE
      VERSION_CHOICE="${VERSION_CHOICE:-1}"
      if ! [[ "$VERSION_CHOICE" =~ ^[0-9]+$ ]] || (( VERSION_CHOICE < 1 || VERSION_CHOICE > ${#RELEASE_TAGS[@]} )); then
        echo "Некорректный выбор — беру последнюю версию."
        VERSION_CHOICE=1
      fi
      LUCX_TAG="${RELEASE_TAGS[$((VERSION_CHOICE - 1))]}"
    else
      LUCX_TAG="${RELEASE_TAGS[0]}"
      echo "Неинтерактивный запуск — беру последнюю версию: ${LUCX_TAG}"
    fi
  fi
  echo "Версия: ${LUCX_TAG}, архитектура: ${ARCH}"

  TARBALL_URL="https://github.com/${LUCX_REPO}/releases/download/${LUCX_TAG}/x-ui-linux-${ARCH}.tar.gz"
  curl -fLR -o "x-ui-review.tar.gz" "$TARBALL_URL"
  rm -rf x-ui-review-extracted
  mkdir -p x-ui-review-extracted
  tar xzf x-ui-review.tar.gz -C x-ui-review-extracted

  AWG_MODULE_SCRIPT=$(find x-ui-review-extracted -name 'install-awg-module.sh' | head -n1)
  if [[ -n "$AWG_MODULE_SCRIPT" ]]; then
    echo
    echo "════════════════════ install-awg-module.sh (${LUCX_TAG}) ════════════════════"
    cat "$AWG_MODULE_SCRIPT"
    echo "════════════════════════════════════════════════════════════════════════════"
    echo
    read -rp "Доверяешь этому скрипту? [y/N]: " TRUST_AWG
    if [[ ! "$TRUST_AWG" =~ ^[Yy]$ ]]; then
      echo "Отменено."
      exit 0
    fi
    # v0.3.7: baseline живёт ВНЕ REVIEW_DIR — финальный rm -rf "$REVIEW_DIR"
    # раньше стирал сохранённую копию, и baseline не переживал саму
    # установку, ради которой его сохраняли.
    BASELINE_DIR="/root/.lucx-awg-baseline"
    mkdir -p "$BASELINE_DIR"
    cp "$AWG_MODULE_SCRIPT" "${BASELINE_DIR}/install-awg-module.sh"
    echo "$LUCX_TAG" > "${BASELINE_DIR}/tag.txt"
    echo "Baseline: ${BASELINE_DIR}/install-awg-module.sh (${LUCX_TAG})"
  else
    echo "install-awg-module.sh не найден. Продолжаю."
  fi
  cd /root

  # --- [5/10] lucx-ui ---
  echo "=== [5/10] Установка lucx-ui ==="
  XUI_USERNAME=$(openssl rand -hex 5)
  XUI_PASSWORD=$(openssl rand -hex 8)

  export XUI_NONINTERACTIVE=1
  export XUI_USERNAME
  export XUI_PASSWORD
  export XUI_WEB_BASE_PATH="$PANEL_BASEPATH_NOSLASH"
  export XUI_PANEL_PORT="$PANEL_PORT"
  export XUI_SSL_MODE="none"
  export XUI_DB_TYPE="sqlite"

  LUCX_INSTALL_TMP=$(mktemp)
  curl -fL "https://raw.githubusercontent.com/${LUCX_REPO}/${LUCX_TAG}/install.sh" -o "$LUCX_INSTALL_TMP"
  if [[ ! -s "$LUCX_INSTALL_TMP" ]]; then
    echo "ОШИБКА: не удалось скачать install.sh"
    exit 1
  fi
  # CLAUDE-FIX-v203: git-config с токеном больше не нужен.
  # install-awg-module.sh в v3.7.0-lucx.203 использует curl + tarball.
  # CLAUDE-FIX-v207: LUCX_BRANCH в install.sh захардкожена на "main",
  # из-за чего sidecar'ы (tproxy/mtproxy) тянутся из main вместо
  # выбранного тега — и получают 404.
  # v0.1.5: export не помогает, т.к. install.sh ПЕРЕОПРЕДЕЛЯЕТ
  # переменную внутри себя. Патчим install.sh через sed перед запуском.
  sed -i "s/^LUCX_BRANCH=.*/LUCX_BRANCH=\"${LUCX_TAG}\"/" "$LUCX_INSTALL_TMP"
  export LUCX_BRANCH="${LUCX_TAG}"
  # v0.2.4: install.sh из lucx-ui v3.8.x принимает версию ПОЗИЦИОННЫМ
  # АРГУМЕНТОМ (install_x-ui $1 -> lucx_parse_args). БЕЗ аргумента он
  # резолвит releases/latest и ставит ПОСЛЕДНИЙ релиз — пин LUCX_TAG
  # фактически не работал (sed-патч выше переопределял только URL
  # sidecar'ов). Передаём тег явно.
  bash "$LUCX_INSTALL_TMP" "$LUCX_TAG"

  rm -f "$LUCX_INSTALL_TMP"

  # v0.4.9: проверка факта — БД обязана быть SQLite до наших манипуляций с ней
  local res_db=""
  res_db=$(grep -oP "^XUI_DB_TYPE=\K.*" /etc/x-ui/install-result.env 2>/dev/null | head -1 || true)
  if [[ -n "$res_db" && "$res_db" != "sqlite" ]]; then
    echo "ОШИБКА: панель установилась с БД '$res_db' — скрипт поддерживает только SQLite."
    echo "  Инбаунды схемы ещё не создавались — данные не затронуты."
    echo "  Скрипт передаёт install.sh XUI_DB_TYPE=sqlite без меню; если панель всё равно выбрала другую БД —"
    echo "  апстрим изменил обработку переменной окружения: сообщи об этом, переустанавливать вслепую не нужно."
    exit 1
  fi

  # v0.4.2: гео-страж — lucx_fetch_geofiles может недополучить файлы (404 на
  # geoip_RU.dat замечен дважды), а без geoip_RU.dat xray не стартует
  ensure_geodata

  # CLAUDE-FIX: install.sh запускает x-ui через systemd, но не ждёт
  # создания SQLite-файла. Если в момент проверки [[ -f "$XUIDB" ]]
  # файла ещё нет — весь SQL-фолбэк пропускается и панель остаётся
  # на дефолтных порту/пути.
  echo "  Ожидание создания x-ui.db ..."
  for _ in {1..30}; do
    [[ -f "$XUIDB" ]] && break
    sleep 1
  done
  if [[ ! -f "$XUIDB" ]]; then
    echo "  WARN: x-ui.db не появился за 30 сек — настройка только через CLI"
  fi

  # lucx-ui CLI лежит в /usr/local/x-ui/x-ui, а не в /usr/bin/x-ui
  XUI_CLI="/usr/local/x-ui/x-ui"
  [[ -x "$XUI_CLI" ]] || XUI_CLI="/usr/bin/x-ui"
  [[ -x "$XUI_CLI" ]] || XUI_CLI=$(command -v x-ui 2>/dev/null || true)

  if [[ -x "$XUI_CLI" ]]; then
    echo "  CLI: $XUI_CLI"
    "$XUI_CLI" setting -username "$XUI_USERNAME" -password "$XUI_PASSWORD" \
         -port "$PANEL_PORT" -webBasePath "$PANEL_BASEPATH_NOSLASH" >/dev/null 2>&1 || true
    "$XUI_CLI" setting -listenIP "127.0.0.1" >/dev/null 2>&1 || true
  else
    echo "WARN: x-ui CLI не найден — настройка только через БД"
  fi

  # Fallback: принудительно 127.0.0.1 + порт + basePath в БД
  if [[ -f "$XUIDB" ]]; then
    sqlite3 "$XUIDB" <<SQL
UPDATE settings SET value='127.0.0.1' WHERE key='webListen';
INSERT INTO settings (key,value) SELECT 'webListen','127.0.0.1' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='webListen');
UPDATE settings SET value='${PANEL_PORT}' WHERE key='webPort';
INSERT INTO settings (key,value) SELECT 'webPort','${PANEL_PORT}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='webPort');
UPDATE settings SET value='${PANEL_BASEPATH_NOSLASH}' WHERE key='webBasePath';
INSERT INTO settings (key,value) SELECT 'webBasePath','${PANEL_BASEPATH_NOSLASH}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='webBasePath');
SQL
  fi

  # --- Рестарт и проверка listen-адреса ---
  echo "  Перезапуск x-ui для применения listenIP..."
  systemctl restart x-ui
  sleep 3

  PANEL_LISTEN=$(ss -tlnp 2>/dev/null | awk '/x-ui/ && /:('$PANEL_PORT')/' | grep -oP '127\.0\.0\.1:'$PANEL_PORT | head -n1 || true)
  if [[ -n "$PANEL_LISTEN" ]]; then
    echo "  OK: x-ui слушает панель на ${PANEL_LISTEN} (loopback)"
  else
    OPEN_LISTEN=$(ss -tlnp 2>/dev/null | awk '/x-ui/ && /:('$PANEL_PORT')/' | grep -oP '\*:'$PANEL_PORT | head -n1 || true)
    if [[ -n "$OPEN_LISTEN" ]]; then
      echo "  FAIL: x-ui панель всё ещё слушает на ${OPEN_LISTEN} (0.0.0.0) — прерываю установку"
      exit 1
    else
      echo "  WARN: не удалось определить listen-адрес x-ui для порта ${PANEL_PORT}"
    fi
  fi

  # --- [5a] Настройка подписок (подтверждённые ключи БД из реального дампа) ---
  echo "=== [5a] Настройка подписок (subURI, subPort, subPath, AWG) ==="
  # Ключи ниже сверены напрямую с реальной таблицей settings рабочей установки:
  # sqlite3 x-ui.db "SELECT key,value FROM settings WHERE key LIKE '%sub%'"
  # НЕ угаданы. В lucx-ui используется subClashURI (не subJsonURI).
  # v0.2.4: ПЕРЕПОДТВЕРЖДЕНЫ на живой БД v3.8.5-lucx.235 (prod-node-1,
  # 16 сен 2026): subEnable/subListen/subPort/subPath/subURI/subClashURI/
  # subAwgEnable/subAwgURI все на месте, subClashAutoDetect=true по умолч.
  # Новые ключи 3.8.x (subJsonPath/subClashPath/...) на нашу запись не влияют.
  if [[ -f "$XUIDB" ]]; then
    cp "$XUIDB" "${XUIDB}.backup.$(date +%s)"

    sub_uri="https://${DOMAIN}${SUB_SECRET_PATH}"
    sqlite3 "$XUIDB" <<SQL
UPDATE settings SET value='true' WHERE key='subEnable';
INSERT INTO settings (key,value) SELECT 'subEnable','true' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subEnable');

UPDATE settings SET value='127.0.0.1' WHERE key='subListen';
INSERT INTO settings (key,value) SELECT 'subListen','127.0.0.1' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subListen');

UPDATE settings SET value='${SUB_PORT}' WHERE key='subPort';
INSERT INTO settings (key,value) SELECT 'subPort','${SUB_PORT}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subPort');

UPDATE settings SET value='${SUB_SECRET_PATH}' WHERE key='subPath';
INSERT INTO settings (key,value) SELECT 'subPath','${SUB_SECRET_PATH}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subPath');

UPDATE settings SET value='${sub_uri}' WHERE key='subURI';
INSERT INTO settings (key,value) SELECT 'subURI','${sub_uri}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subURI');

UPDATE settings SET value='${sub_uri}' WHERE key='subClashURI';
INSERT INTO settings (key,value) SELECT 'subClashURI','${sub_uri}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subClashURI');

UPDATE settings SET value='true' WHERE key='subAwgEnable';
INSERT INTO settings (key,value) SELECT 'subAwgEnable','true' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subAwgEnable');

UPDATE settings SET value='https://${DOMAIN}${AWG_SECRET_PATH}' WHERE key='subAwgURI';
INSERT INTO settings (key,value) SELECT 'subAwgURI','https://${DOMAIN}${AWG_SECRET_PATH}' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='subAwgURI');
SQL
    echo "  subEnable    = true"
    echo "  subListen    = 127.0.0.1"
    echo "  subPort      = ${SUB_PORT}"
    echo "  subPath      = ${SUB_SECRET_PATH}"
    echo "  subURI       = ${sub_uri}"
    echo "  subClashURI  = ${sub_uri}  (panel различает Clash по User-Agent, subClashAutoDetect=true по умолч.)"
    echo "  subAwgEnable = true"
  fi

  systemctl restart x-ui
  sleep 2
  systemctl status x-ui --no-pager | head -n 5 || true

  echo
  echo "Креды панели:"
  echo "  Username: ${XUI_USERNAME}"
  echo "  Password: ${XUI_PASSWORD}"
  echo

  # --- [6/10] SSL (webroot, без остановки nginx) ---
  echo "=== [6/10] Сертификаты Let's Encrypt (webroot) ==="
  # webroot вместо standalone: так плановое продление из cron сможет
  # работать, пока nginx крутится на 80/443 и никого с них не сгоняет.
  WEBROOT="/var/www/html"
  mkdir -p "${WEBROOT}/.well-known/acme-challenge"
  chown -R www-data:www-data "$WEBROOT"

  cat > "/etc/nginx/sites-available/80-redirect.conf" <<EOF
server {
    listen 80;
    server_name ${DOMAIN} ${REALITY_DOMAIN};
    server_tokens off;
    location /.well-known/acme-challenge/ { root ${WEBROOT}; }
    location / { return 301 https://\$host\$request_uri; }
}
EOF
  ln -sf "/etc/nginx/sites-available/80-redirect.conf" "/etc/nginx/sites-enabled/80-redirect.conf"
  rm -f /etc/nginx/sites-enabled/default
  nginx -t || { echo "ОШИБКА: nginx config test failed (80-redirect)"; exit 1; }
  systemctl restart nginx
  systemctl enable nginx

  certbot_ok=1
  for d in "$DOMAIN" "$REALITY_DOMAIN"; do
    if ! certbot certonly --webroot -w "$WEBROOT" -d "$d" \
      --cert-name "$d" \
      --non-interactive --agree-tos --register-unsafely-without-email; then
      echo "ОШИБКА: certbot не получил сертификат для $d"
      certbot_ok=0
    fi
  done
  [[ "$certbot_ok" == "1" ]] || exit 1

  # --- [7/10] Decoy-сайты (банк шаблонов, выбор по хешу домена) ---
  TEMPLATE_COUNT=22
  echo "=== [7/10] Decoy-сайты (банк из ${TEMPLATE_COUNT} шаблонов) ==="
  DECOY_ROOT_1="/var/www/decoy-panel"
  DECOY_ROOT_2="/var/www/decoy-reality"
  mkdir -p "$DECOY_ROOT_1" "$DECOY_ROOT_2"

  template_01() {
    # Root & Ridge — coffee roastery
    cat <<'DECOYTPL01'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Root &amp; Ridge — Small-Batch Coffee Roastery</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600&family=Archivo:wght@400;500;600&display=swap');
  :root{
    --bg:#241811; --bg2:#2e1f16; --paper:#f7f0e3; --ink:#2a1c12;
    --mustard:#c68a2e; --clay:#8a5a3a; --line:#4a382a;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{background:var(--bg);color:var(--paper);font-family:'Archivo',sans-serif;line-height:1.65;}
  header{display:flex;justify-content:space-between;align-items:center;padding:26px 6vw;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--bg);z-index:10;}
  .brand{font-family:'Fraunces',serif;font-weight:600;font-size:21px;letter-spacing:.3px;}
  .brand em{font-style:italic;color:var(--mustard);}
  nav{display:flex;gap:30px;}
  nav a{color:#cbb89a;text-decoration:none;font-size:13.5px;letter-spacing:.5px;}
  nav a:hover{color:var(--mustard);}
  .hero{padding:110px 6vw 90px;max-width:1100px;}
  .hero .eyebrow{font-size:13px;letter-spacing:3px;text-transform:uppercase;color:var(--mustard);margin-bottom:22px;}
  .hero h1{font-family:'Fraunces',serif;font-weight:500;font-size:clamp(38px,6.4vw,76px);line-height:1.05;max-width:14ch;margin-bottom:28px;}
  .hero h1 i{font-style:italic;color:var(--mustard);}
  .hero p{max-width:52ch;color:#d8c9b3;font-size:18px;margin-bottom:36px;}
  .btn{display:inline-block;padding:15px 30px;background:var(--mustard);color:#241811;text-decoration:none;font-weight:600;font-size:14px;letter-spacing:.3px;border-radius:2px;}
  .btn.ghost{background:none;border:1px solid var(--line);color:var(--paper);margin-left:14px;}

  .gauge-section{padding:70px 6vw;border-top:1px solid var(--line);background:var(--bg2);}
  .gauge-head{max-width:60ch;margin-bottom:56px;}
  .gauge-head h2{font-family:'Fraunces',serif;font-weight:500;font-size:clamp(26px,3.4vw,38px);margin-bottom:12px;}
  .gauge-head p{color:#cbb89a;font-size:15.5px;}
  .roasts{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);}
  .roast{background:var(--bg2);padding:32px 26px;}
  .roast .bar{height:6px;background:var(--line);border-radius:4px;margin-bottom:18px;overflow:hidden;}
  .roast .bar span{display:block;height:100%;background:var(--mustard);}
  .roast h3{font-family:'Fraunces',serif;font-size:18px;margin-bottom:8px;}
  .roast p{color:#b9a488;font-size:14px;}

  .origins{padding:90px 6vw;}
  .origins-head{max-width:60ch;margin-bottom:56px;}
  .origins-head h2{font-family:'Fraunces',serif;font-weight:500;font-size:clamp(26px,3.4vw,38px);margin-bottom:12px;}
  .origins-head p{color:#cbb89a;font-size:15.5px;}
  .origin-list{display:flex;flex-direction:column;}
  .origin-row{display:grid;grid-template-columns:140px 1fr 120px;gap:24px;align-items:baseline;padding:22px 0;border-bottom:1px solid var(--line);}
  .origin-row .place{font-family:'Fraunces',serif;font-size:19px;}
  .origin-row .note{color:#cbb89a;font-size:14.5px;}
  .origin-row .alt{color:var(--mustard);font-size:13px;letter-spacing:.4px;text-align:right;}

  .visit{padding:90px 6vw;border-top:1px solid var(--line);text-align:center;background:var(--bg2);}
  .visit h2{font-family:'Fraunces',serif;font-weight:500;font-size:clamp(28px,4.4vw,48px);max-width:20ch;margin:0 auto 22px;}
  .visit h2 i{font-style:italic;color:var(--mustard);}
  .visit p{color:#cbb89a;max-width:48ch;margin:0 auto 32px;}

  footer{padding:38px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:#8a765f;font-size:13px;}
  @media (max-width:820px){nav{display:none;} .roasts{grid-template-columns:1fr 1fr;} .origin-row{grid-template-columns:1fr;gap:4px;} .origin-row .alt{text-align:left;}}
</style>
</head>
<body>
<header><div class="brand">Root &amp; <em>Ridge</em></div><nav><a href="#roast">Roast levels</a><a href="#origins">Origins</a><a href="#visit">Visit</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">Small-batch roastery, est. six years ago</div>
  <h1>We roast for the <i>second cup</i>, not the photo of the first.</h1>
  <p>Root &amp; Ridge buys direct from growers we've actually met, roasts in lots under 40kg, and writes the roast date on every bag — because coffee is produce, not a logo.</p>
  <a class="btn" href="#origins">See this month's lots</a><a class="btn ghost" href="#visit">Find the shop</a>
</section>

<section class="gauge-section" id="roast">
  <div class="gauge-head"><h2>Four roast levels, no in-betweens</h2><p>We don't chase a house style across every bean — each lot gets roasted to where its own sugars and acids actually want to land.</p></div>
  <div class="roasts">
    <div class="roast"><div class="bar"><span style="width:30%"></span></div><h3>Light</h3><p>Bright, floral, first crack only. Best for pour-over.</p></div>
    <div class="roast"><div class="bar"><span style="width:52%"></span></div><h3>Light-medium</h3><p>Balanced sweetness, still shows origin clearly.</p></div>
    <div class="roast"><div class="bar"><span style="width:74%"></span></div><h3>Medium</h3><p>Rounder body, less acidity, good all-day drinker.</p></div>
    <div class="roast"><div class="bar"><span style="width:92%"></span></div><h3>Dark</h3><p>Reserved for two espresso blends, nothing else.</p></div>
  </div>
</section>

<section class="origins" id="origins">
  <div class="origins-head"><h2>On the bar this month</h2><p>Small lots rotate as they run out — once a bag is gone we don't reorder the same one twice.</p></div>
  <div class="origin-list">
    <div class="origin-row"><div class="place">Yirgacheffe, Ethiopia</div><div class="note">Washed, 1900m — jasmine, stone fruit, a clean short finish.</div><div class="alt">Light</div></div>
    <div class="origin-row"><div class="place">Huila, Colombia</div><div class="note">Honey-processed — brown sugar, red apple, syrupy body.</div><div class="alt">Light-medium</div></div>
    <div class="origin-row"><div class="place">Mogiana, Brazil</div><div class="note">Natural — hazelnut, cocoa nib, low acidity throughout.</div><div class="alt">Medium</div></div>
    <div class="origin-row"><div class="place">Espresso House Blend</div><div class="note">Brazil + Sumatra — built for milk, not for showing off.</div><div class="alt">Dark</div></div>
  </div>
</section>

<section class="visit" id="visit">
  <h2>Come stand at the <i>bar</i> while we brew it.</h2>
  <p>No loyalty app, no seasonal cup sizes with made-up names. Just tell us what you usually drink and we'll get you closer to something better.</p>
  <a class="btn" href="mailto:hello@rootandridge.coffee">hello@rootandridge.coffee</a>
</section>
</main>
<footer><div>Root &amp; Ridge Coffee Roastery</div><div>Roasted fresh, sold slow</div></footer>
</body>
</html>
DECOYTPL01
  }

  template_02() {
    # pallet.dev — SaaS observability
    cat <<'DECOYTPL02'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pallet — Queue Observability for Backend Teams</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=Inter:wght@400;500;600&display=swap');
  :root{
    --bg:#0e1116; --panel:#161b22; --line:#262c36; --text:#d7dbe3; --dim:#818a9a;
    --accent:#8f8fe3; --accent2:#5fc9c9;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--text);font-family:'Inter',sans-serif;line-height:1.6;}
  header{display:flex;justify-content:space-between;align-items:center;padding:20px 6vw;border-bottom:1px solid var(--line);}
  .brand{font-family:'JetBrains Mono',monospace;font-weight:700;font-size:18px;letter-spacing:-.3px;}
  .brand span{color:var(--accent);}
  nav{display:flex;gap:30px;align-items:center;}
  nav a{color:var(--dim);text-decoration:none;font-size:14px;}
  nav a:hover{color:var(--text);}
  .nav-cta{background:var(--accent);color:#0e1116;padding:9px 16px;border-radius:6px;font-weight:600;font-size:13.5px;}

  .hero{padding:100px 6vw 70px;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;max-width:1300px;margin:0 auto;}
  .hero .eyebrow{font-family:'JetBrains Mono',monospace;color:var(--accent2);font-size:13px;letter-spacing:1px;margin-bottom:20px;}
  .hero h1{font-size:clamp(32px,4vw,52px);font-weight:600;line-height:1.12;margin-bottom:22px;}
  .hero h1 span{color:var(--accent);}
  .hero p{color:var(--dim);font-size:16.5px;max-width:46ch;margin-bottom:32px;}
  .btn{display:inline-block;padding:13px 24px;background:var(--accent);color:#0e1116;text-decoration:none;font-weight:600;font-size:14px;border-radius:6px;}
  .btn.ghost{background:none;border:1px solid var(--line);color:var(--text);margin-left:12px;}

  .term{background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden;font-family:'JetBrains Mono',monospace;font-size:13px;}
  .term-bar{display:flex;gap:7px;padding:12px 16px;border-bottom:1px solid var(--line);}
  .term-bar span{width:11px;height:11px;border-radius:50%;background:#3a4150;}
  .term-body{padding:20px;color:#a9b1c0;}
  .term-body .ok{color:var(--accent2);}
  .term-body .warn{color:#e0b45a;}
  .term-body .dim{color:#565f70;}
  .term-body div{padding:3px 0;}

  section.feat{padding:80px 6vw;border-top:1px solid var(--line);max-width:1300px;margin:0 auto;}
  .feat-head{max-width:60ch;margin-bottom:50px;}
  .feat-head h2{font-size:clamp(24px,3vw,34px);font-weight:600;margin-bottom:12px;}
  .feat-head p{color:var(--dim);font-size:15.5px;}
  .grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden;}
  .card{background:var(--panel);padding:30px 26px;}
  .card .tag{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--accent2);margin-bottom:12px;}
  .card h3{font-size:17px;font-weight:600;margin-bottom:10px;}
  .card p{color:var(--dim);font-size:14.5px;}

  .stats{padding:70px 6vw;border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);max-width:1300px;margin:0 auto;}
  .stat{background:var(--bg);padding:34px 26px;text-align:left;}
  .stat .num{font-family:'JetBrains Mono',monospace;font-size:30px;color:var(--accent);}
  .stat .lbl{color:var(--dim);font-size:13.5px;margin-top:6px;}

  .cta{padding:90px 6vw;border-top:1px solid var(--line);text-align:center;}
  .cta h2{font-size:clamp(26px,4vw,42px);font-weight:600;max-width:20ch;margin:0 auto 18px;}
  .cta p{color:var(--dim);max-width:48ch;margin:0 auto 30px;}

  footer{padding:34px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:13px;max-width:1300px;margin:0 auto;}
  @media (max-width:900px){.hero{grid-template-columns:1fr;} nav{display:none;} .grid3{grid-template-columns:1fr;} .stats{grid-template-columns:1fr 1fr;}}
</style>
</head>
<body>
<header><div class="brand">pallet<span>.</span>dev</div><nav><a href="#features">Features</a><a href="#pricing">Pricing</a><a href="#docs">Docs</a><a class="nav-cta" href="#cta">Get an API key</a></nav></header>
<main>
<section class="hero">
  <div>
    <div class="eyebrow">// queue observability</div>
    <h1>See why a job is <span>stuck</span>, not just that it is.</h1>
    <p>Pallet sits next to your existing queue (SQS, Redis, RabbitMQ) and gives you per-job traces, retry history, and consumer lag — without shipping your payloads anywhere.</p>
    <a class="btn" href="#cta">Start free — 14 days</a><a class="btn ghost" href="#docs">Read the docs</a>
  </div>
  <div class="term">
    <div class="term-bar"><span></span><span></span><span></span></div>
    <div class="term-body">
      <div class="dim">$ pallet trace job_4f21a9</div>
      <div><span class="ok">✓</span> enqueued  &nbsp;12:04:01.221</div>
      <div><span class="ok">✓</span> consumed  &nbsp;12:04:01.804 <span class="dim">(worker-07)</span></div>
      <div><span class="warn">↻</span> retry 1/3 &nbsp;12:04:03.912 <span class="dim">timeout: upstream 502</span></div>
      <div><span class="ok">✓</span> completed &nbsp;12:04:06.331</div>
      <div class="dim">total latency: 5.11s across 2 attempts</div>
    </div>
  </div>
</section>

<section class="feat" id="features">
  <div class="feat-head"><h2>Built for the 2am page, not the demo</h2><p>Three things a queue dashboard should actually tell you, and usually doesn't.</p></div>
  <div class="grid3">
    <div class="card"><div class="tag">01</div><h3>Per-job traces</h3><p>Every enqueue, retry, and dead-letter for a single job, without grepping five services' logs.</p></div>
    <div class="card"><div class="tag">02</div><h3>Consumer lag alerts</h3><p>Know a worker pool fell behind before your queue depth graph even moves.</p></div>
    <div class="card"><div class="tag">03</div><h3>No payload storage</h3><p>We index metadata only — job IDs, timings, error classes. Your data stays yours.</p></div>
  </div>
</section>

<section class="stats">
  <div class="stat"><div class="num">4ms</div><div class="lbl">median trace ingest overhead</div></div>
  <div class="stat"><div class="num">3</div><div class="lbl">supported queue backends today</div></div>
  <div class="stat"><div class="num">0</div><div class="lbl">payload bytes ever stored</div></div>
  <div class="stat"><div class="num">10min</div><div class="lbl">typical setup time</div></div>
</section>

<section class="cta" id="cta">
  <h2>Point it at one queue. See if it earns the second.</h2>
  <p>No sales call required for the first workspace. Bring your own SQS or Redis connection string and you're tracing jobs in minutes.</p>
  <a class="btn" href="mailto:team@pallet.dev">Get an API key</a>
</section>
</main>
<footer><div>pallet.dev</div><div>Built by three people who got tired of grep</div></footer>
</body>
</html>
DECOYTPL02
  }

  template_03() {
    # Low Tide — personal newsletter
    local D1 D2 D3
    D1=$(date -d "-3 days" +"%B %-d")
    D2=$(date -d "-17 days" +"%B %-d")
    D3=$(date -d "-31 days" +"%B %-d")
    cat <<DECOYTPL03
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Low Tide — a newsletter by Marta Ilves</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,wght@0,400;0,600;1,400&family=Inter:wght@400;500&display=swap');
  :root{--bg:#eef1ef;--ink:#22302c;--dim:#5b6b64;--line:#c9d2cc;--mauve:#a06b6b;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:'Source Serif 4',serif;line-height:1.7;}
  header{display:flex;justify-content:space-between;align-items:baseline;padding:34px 8vw 22px;border-bottom:1px solid var(--line);}
  .brand{font-weight:600;font-size:19px;letter-spacing:.2px;}
  .brand em{font-style:italic;color:var(--mauve);}
  nav{display:flex;gap:26px;font-family:'Inter',sans-serif;}
  nav a{color:var(--dim);text-decoration:none;font-size:13px;letter-spacing:.3px;}
  nav a:hover{color:var(--ink);}

  .hero{padding:70px 8vw 60px;max-width:760px;}
  .hero .eyebrow{font-family:'Inter',sans-serif;color:var(--mauve);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;margin-bottom:20px;}
  .hero h1{font-size:clamp(30px,4.6vw,46px);font-weight:600;line-height:1.2;margin-bottom:20px;}
  .hero p{color:var(--dim);font-size:17.5px;max-width:52ch;margin-bottom:30px;}
  .subscribe{display:flex;gap:10px;max-width:420px;font-family:'Inter',sans-serif;}
  .subscribe input{flex:1;padding:12px 14px;border:1px solid var(--line);border-radius:4px;background:#fff;font-size:14px;}
  .subscribe button{padding:12px 20px;background:var(--ink);color:var(--bg);border:none;border-radius:4px;font-size:14px;cursor:pointer;}

  .essays{padding:20px 8vw 90px;max-width:760px;}
  .essays .label{font-family:'Inter',sans-serif;font-size:12.5px;letter-spacing:2px;text-transform:uppercase;color:var(--dim);margin-bottom:30px;padding-top:40px;border-top:1px solid var(--line);}
  .essay{padding:30px 0;border-bottom:1px solid var(--line);}
  .essay .date{font-family:'Inter',sans-serif;font-size:12.5px;color:var(--mauve);letter-spacing:.4px;margin-bottom:10px;}
  .essay h2{font-size:23px;font-weight:600;margin-bottom:10px;}
  .essay h2 a{color:inherit;text-decoration:none;}
  .essay h2 a:hover{color:var(--mauve);}
  .essay p{color:var(--dim);font-size:16px;max-width:60ch;}

  .about{padding:70px 8vw;border-top:1px solid var(--line);max-width:760px;background:#e4e9e5;}
  .about h2{font-family:'Inter',sans-serif;font-size:12.5px;letter-spacing:2px;text-transform:uppercase;color:var(--dim);margin-bottom:20px;}
  .about p{font-size:16.5px;max-width:58ch;color:var(--ink);}
  .about .sign{font-style:italic;color:var(--mauve);margin-top:14px;}

  footer{padding:36px 8vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;font-family:'Inter',sans-serif;color:var(--dim);font-size:12.5px;}
  @media (max-width:700px){nav{display:none;} .subscribe{flex-direction:column;} .about{max-width:100%;}}
</style>
</head>
<body>
<header><div class="brand">Low <em>Tide</em></div><nav><a href="#essays">Essays</a><a href="#about">About</a><a href="#archive">Archive</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">A newsletter, roughly every other Sunday</div>
  <h1>Notes on working slowly, in public.</h1>
  <p>Low Tide is where I write down what I actually noticed that week — not advice, not a framework, just the thing that was still bothering me by Sunday.</p>
  <div class="subscribe"><input type="email" placeholder="you@example.com" /><button>Subscribe</button></div>
</section>

<section class="essays" id="essays">
  <div class="label">Recent essays</div>
  <div class="essay">
    <div class="date">${D1}</div>
    <h2><a href="#">The difference between finished and done</a></h2>
    <p>A cabinet I built badly on purpose, and what it taught me about shipping things I'm still a little embarrassed by.</p>
  </div>
  <div class="essay">
    <div class="date">${D2}</div>
    <h2><a href="#">Why I stopped keeping a reading list</a></h2>
    <p>The list was accurate. It was also making me read like I was clearing a queue instead of reading a book.</p>
  </div>
  <div class="essay">
    <div class="date">${D3}</div>
    <h2><a href="#">A week of answering slower</a></h2>
    <p>I gave myself a full day before replying to anything that wasn't urgent. Almost nothing was urgent.</p>
  </div>
</section>

<section class="about" id="about">
  <h2>About</h2>
  <p>I'm Marta — I split time between a small workshop and a laptop, and this newsletter is the overlap between the two. No sponsors, no upsell, just the Sunday note.</p>
  <p class="sign">— M.</p>
</section>
</main>
<footer><div>Low Tide</div><div>One honest note, every other Sunday</div></footer>
</body>
</html>
DECOYTPL03
  }

  template_04() {
