    TUE_TIME="$(date -d 'next tuesday' +'%a %H:%M') local"
    cat <<DECOYTPL04
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Signal Hill Radio Society</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&family=IBM+Plex+Sans:wght@400;500;600&display=swap');
  :root{--bg:#12211f;--panel:#193430;--amber:#e0a94a;--amber-dim:#8a6d3a;--text:#dfe8e4;--dim:#7d938c;--line:#2a4741;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--text);font-family:'IBM Plex Sans',sans-serif;line-height:1.6;}
  header{display:flex;justify-content:space-between;align-items:center;padding:22px 6vw;border-bottom:1px solid var(--line);}
  .brand{font-family:'Space Mono',monospace;font-weight:700;font-size:17px;color:var(--amber);letter-spacing:.5px;}
  .brand small{color:var(--dim);font-weight:400;display:block;font-size:11px;letter-spacing:1px;margin-top:2px;}
  nav{display:flex;gap:28px;}
  nav a{color:var(--dim);text-decoration:none;font-size:13.5px;}
  nav a:hover{color:var(--amber);}

  .hero{padding:90px 6vw 60px;max-width:1200px;margin:0 auto;display:grid;grid-template-columns:1.1fr .9fr;gap:50px;align-items:center;}
  .hero .eyebrow{font-family:'Space Mono',monospace;color:var(--amber);font-size:12.5px;letter-spacing:2px;margin-bottom:20px;}
  .hero h1{font-size:clamp(30px,4.4vw,50px);font-weight:600;font-family:'IBM Plex Sans',sans-serif;line-height:1.15;margin-bottom:20px;}
  .hero p{color:var(--dim);max-width:48ch;font-size:16px;margin-bottom:30px;}
  .btn{display:inline-block;padding:13px 24px;background:var(--amber);color:#12211f;text-decoration:none;font-weight:600;font-size:13.5px;border-radius:2px;}
  .btn.ghost{background:none;border:1px solid var(--line);color:var(--text);margin-left:10px;}

  .panel{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:26px;font-family:'Space Mono',monospace;font-size:13px;}
  .panel .row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line);}
  .panel .row:last-child{border-bottom:none;}
  .panel .row .lbl{color:var(--dim);}
  .panel .row .val{color:var(--amber);}
  .meter{height:6px;background:var(--line);border-radius:3px;margin-top:8px;overflow:hidden;}
  .meter span{display:block;height:100%;background:var(--amber);}

  section.bands{padding:70px 6vw;border-top:1px solid var(--line);max-width:1200px;margin:0 auto;}
  .bands-head{max-width:60ch;margin-bottom:44px;}
  .bands-head h2{font-size:clamp(24px,3vw,32px);font-weight:600;margin-bottom:10px;}
  .bands-head p{color:var(--dim);font-size:15px;}
  .band-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:6px;overflow:hidden;}
  .band{background:var(--panel);padding:24px 20px;}
  .band .name{font-family:'Space Mono',monospace;color:var(--amber);font-size:14px;margin-bottom:10px;}
  .band .cond{font-size:13.5px;color:var(--dim);}

  .join{padding:80px 6vw;border-top:1px solid var(--line);text-align:center;}
  .join h2{font-size:clamp(24px,3.6vw,38px);font-weight:600;max-width:22ch;margin:0 auto 16px;}
  .join p{color:var(--dim);max-width:46ch;margin:0 auto 28px;}

  footer{padding:32px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:12.5px;max-width:1200px;margin:0 auto;}
  @media (max-width:880px){.hero{grid-template-columns:1fr;} nav{display:none;} .band-grid{grid-template-columns:1fr 1fr;}}
</style>
</head>
<body>
<header><div class="brand">SIGNAL HILL<small>AMATEUR RADIO SOCIETY · EST. 1988</small></div><nav><a href="#conditions">Band conditions</a><a href="#clubhouse">Clubhouse</a><a href="#join">Join</a></nav></header>
<main>
<section class="hero">
  <div>
    <div class="eyebrow">73 DE SIGNAL HILL</div>
    <h1>Still on the air, still meeting Tuesdays.</h1>
    <p>A club station, a rented clubhouse, and about forty licensed members who'd rather talk to a stranger on 20m than scroll another feed.</p>
    <a class="btn" href="#join">Get your license</a><a class="btn ghost" href="#clubhouse">Visit Tuesdays</a>
  </div>
  <div class="panel">
    <div class="row"><div class="lbl">Solar flux index</div><div class="val">142</div></div>
    <div class="row"><div class="lbl">A-index</div><div class="val">6 — quiet</div></div>
    <div class="row"><div class="lbl">20m band</div><div class="val">Good</div></div>
    <div class="meter"><span style="width:78%"></span></div>
    <div class="row" style="margin-top:8px;"><div class="lbl">Last club net</div><div class="val">${TUE_TIME}</div></div>
  </div>
</section>

<section class="bands" id="conditions">
  <div class="bands-head"><h2>Tonight's bands, plainly</h2><p>Updated by whoever's at the clubhouse with the receiver on — not a modeled forecast, just someone listening.</p></div>
  <div class="band-grid">
    <div class="band"><div class="name">80m</div><div class="cond">Noisy after dark, local nets only.</div></div>
    <div class="band"><div class="name">40m</div><div class="cond">Reliable regional contacts all evening.</div></div>
    <div class="band"><div class="name">20m</div><div class="cond">DX opening toward EU until ~19:00.</div></div>
    <div class="band"><div class="name">2m</div><div class="cond">Repeater clear, usual Tuesday chatter.</div></div>
  </div>
</section>

<section class="join" id="join">
  <h2>No code required anymore. Just curiosity.</h2>
  <p>We run a free study group before every license exam session — bring a radio if you have one, borrow one of ours if you don't.</p>
  <a class="btn" href="mailto:secretary@signalhillradio.club">secretary@signalhillradio.club</a>
</section>
</main>
<footer><div>Signal Hill Radio Society</div><div>Clubhouse open Tuesdays, 19:00–22:00</div></footer>
</body>
</html>
DECOYTPL04
  }

  template_05() {
    # Iris Kovac — photography
    cat <<'DECOYTPL05'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Iris Kovac — Photography</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cormorant:ital,wght@0,500;1,500&family=Manrope:wght@400;500;600&display=swap');
  :root{--bg:#0a0a0a;--paper:#f0efeb;--dim:#8f8f8f;--line:#242424;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--paper);font-family:'Manrope',sans-serif;line-height:1.6;}
  header{display:flex;justify-content:space-between;align-items:center;padding:30px 6vw;}
  .brand{font-family:'Cormorant',serif;font-style:italic;font-size:22px;letter-spacing:.5px;}
  nav{display:flex;gap:30px;}
  nav a{color:var(--dim);text-decoration:none;font-size:13px;letter-spacing:1px;text-transform:uppercase;}
  nav a:hover{color:var(--paper);}
  .hero{padding:40px 6vw 60px;max-width:900px;}
  .hero .eyebrow{color:var(--dim);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;margin-bottom:18px;}
  .hero h1{font-family:'Cormorant',serif;font-weight:500;font-size:clamp(32px,5vw,58px);line-height:1.15;max-width:16ch;}
  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;padding:0 6vw;}
  .grid .cell{aspect-ratio:4/5;background:linear-gradient(160deg,#2a2a2a,#151515);position:relative;overflow:hidden;}
  .grid .cell:nth-child(3n+2){aspect-ratio:1/1;}
  .grid .cell .tag{position:absolute;bottom:14px;left:14px;font-family:'Cormorant',serif;font-style:italic;font-size:15px;color:var(--paper);}
  section.about{padding:100px 6vw;max-width:640px;}
  .about .label{color:var(--dim);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;margin-bottom:22px;}
  .about p{font-family:'Cormorant',serif;font-size:24px;line-height:1.5;font-style:italic;}
  section.book{padding:0 6vw 100px;text-align:left;}
  .book h2{font-family:'Cormorant',serif;font-weight:500;font-size:clamp(26px,3.6vw,40px);margin-bottom:22px;}
  .book p{color:var(--dim);max-width:46ch;margin-bottom:28px;}
  .btn{display:inline-block;padding:14px 26px;border:1px solid var(--paper);color:var(--paper);text-decoration:none;font-size:13px;letter-spacing:1px;text-transform:uppercase;}
  footer{padding:34px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:12.5px;}
  @media (max-width:800px){nav{display:none;} .grid{grid-template-columns:1fr 1fr;}}
</style>
</head>
<body>
<header><div class="brand">Iris Kovac</div><nav><a href="#work">Work</a><a href="#about">About</a><a href="#book">Bookings</a></nav></header>
<main>
<section class="hero"><div class="eyebrow">Documentary &amp; portrait photography</div><h1>Mostly weddings. Occasionally strangers who let me follow them for a day.</h1></section>
<section class="grid" id="work">
  <div class="cell"><div class="tag">Reception, June</div></div>
  <div class="cell"><div class="tag">Backstage, a wedding in Split</div></div>
  <div class="cell"><div class="tag">Portrait study</div></div>
  <div class="cell"><div class="tag">First look</div></div>
  <div class="cell"><div class="tag">Market, early light</div></div>
  <div class="cell"><div class="tag">Reception, dance floor</div></div>
</section>
<section class="about" id="about"><div class="label">About</div><p>I shoot the parts nobody stages — the walk between ceremony and reception, the look someone gives when they think the camera's already down.</p></section>
<section class="book" id="book"><h2>Booking one wedding per weekend, on purpose.</h2><p>I only take one date at a time so I can actually edit properly, which means dates go fast in high season. Reach out even if it's a long way off.</p><a class="btn" href="mailto:iris@iriskovac.photo">Check my calendar</a></section>
</main>
<footer><div>Iris Kovac Photography</div><div>Based in Split, working further out</div></footer>
</body>
</html>
DECOYTPL05
  }

