  header{display:flex;justify-content:space-between;align-items:center;padding:26px 6vw;border-bottom:1px solid var(--line);}
  .brand{font-family:'Libre Caslon Display',serif;font-size:21px;}
  nav{display:flex;gap:28px;}
  nav a{color:var(--dim);text-decoration:none;font-size:13.5px;}
