  .hero{padding:80px 6vw 60px;max-width:1000px;}
  .hero .eyebrow{color:var(--navy);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;margin-bottom:20px;}
  .hero h1{font-family:'Libre Caslon Display',serif;font-size:clamp(32px,5vw,58px);line-height:1.15;max-width:14ch;margin-bottom:24px;}
