  .btn{display:inline-block;padding:14px 26px;background:var(--navy);color:#f1ece2;text-decoration:none;font-size:14px;border-radius:2px;}
  .today{padding:60px 6vw;border-top:1px solid var(--line);background:#e8e0cf;}
