  .today-head h2{font-family:'Libre Caslon Display',serif;font-size:clamp(24px,3.2vw,34px);margin-top:8px;}
  .loaf-list{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);}
  .loaf{background:#f1ece2;padding:26px 24px;}
  .loaf .time{font-size:12px;color:var(--navy);letter-spacing:.5px;margin-bottom:8px;}
  .loaf h3{font-family:'Libre Caslon Display',serif;font-size:19px;margin-bottom:8px;}
  .loaf p{color:var(--dim);font-size:14px;}
  .visit{padding:90px 6vw;text-align:center;}
  .visit h2{font-family:'Libre Caslon Display',serif;font-size:clamp(26px,4vw,42px);max-width:20ch;margin:0 auto 20px;}
  .visit p{color:var(--dim);max-width:46ch;margin:0 auto 26px;}
  footer{padding:32px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:13px;}
  @media (max-width:800px){nav{display:none;} .loaf-list{grid-template-columns:1fr;}}
</style>
