<body>
<header><div class="brand">Marsh &amp; Loaf</div><nav><a href="#today">Today's bake</a><a href="#visit">Visit</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">Wood-fired, sourdough only</div>
  <h1>We sell out most days by eleven. That's the plan.</h1>
  <p>Marsh &amp; Loaf bakes one style of bread — long-fermented sourdough — in small enough batches that it's gone before it needs a preservative to survive the afternoon.</p>
  <a class="btn" href="#today">See what's in the oven</a>
</section>
<section class="today" id="today">
  <div class="today-head"><div class="label">Baking this morning</div><h2>Three loaves, first come first served</h2></div>
  <div class="loaf-list">
    <div class="loaf"><div class="time">Ready 7:30am</div><h3>Country sourdough</h3><p>72-hour ferment, dark crust, holds a week wrapped in cloth.</p></div>
    <div class="loaf"><div class="time">Ready 8:00am</div><h3>Rye &amp; caraway</h3><p>Dense, mildly sour, the one regulars ask us to save for them.</p></div>
    <div class="loaf"><div class="time">Ready 9:00am</div><h3>Seeded miche</h3><p>Whole-grain, sunflower and flax, our biggest loaf by far.</p></div>
  </div>
</section>
<section class="visit" id="visit">
  <h2>Come early, or come tomorrow.</h2>
  <p>No online ordering — we bake what the day needs, not what a queue predicts. Cash and card both fine.</p>
  <a class="btn" href="mailto:hello@marshandloaf.bakery">Ask about standing orders</a>
</section>
</main>
<footer><div>Marsh &amp; Loaf</div><div>Open Tue–Sat, 7am until sold out</div></footer>
</body>
</html>
DECOYTPL06
