  template_07() {
    # routewise — OSS docs
    cat <<'DECOYTPL07'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>routewise — a small routing library</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500&display=swap');
  :root{--bg:#fbfbfa;--ink:#1a1a1a;--dim:#666;--line:#e2e2e0;--accent:#1f5c4d;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:'IBM Plex Sans',sans-serif;line-height:1.65;}
  header{display:flex;justify-content:space-between;align-items:center;padding:20px 6vw;border-bottom:1px solid var(--line);}
  .brand{font-family:'IBM Plex Mono',monospace;font-weight:600;font-size:16px;}
  .brand span{color:var(--accent);}
  nav{display:flex;gap:24px;align-items:center;}
  nav a{color:var(--dim);text-decoration:none;font-size:13.5px;}
  .stars{font-family:'IBM Plex Mono',monospace;font-size:12.5px;border:1px solid var(--line);padding:6px 10px;border-radius:5px;color:var(--dim);}
  .hero{padding:70px 6vw 50px;max-width:900px;}
  .hero .eyebrow{font-family:'IBM Plex Mono',monospace;color:var(--accent);font-size:12.5px;margin-bottom:18px;}
  .hero h1{font-size:clamp(28px,4vw,44px);font-weight:500;line-height:1.2;margin-bottom:18px;}
  .hero p{color:var(--dim);max-width:56ch;font-size:16px;margin-bottom:26px;}
  .install{background:#141414;color:#e8e8e8;font-family:'IBM Plex Mono',monospace;font-size:13.5px;padding:16px 20px;border-radius:6px;max-width:480px;}
  .install .cmt{color:#7a7a7a;}
  section.docs{padding:60px 6vw;border-top:1px solid var(--line);max-width:900px;}
  .docs h2{font-size:20px;font-weight:600;margin-bottom:20px;}
  .code{background:#141414;color:#e8e8e8;font-family:'IBM Plex Mono',monospace;font-size:13px;padding:22px;border-radius:6px;overflow-x:auto;line-height:1.7;}
  .code .kw{color:#c586c0;} .code .fn{color:#dcdcaa;} .code .str{color:#ce9178;} .code .cmt{color:#6a9955;}
  section.why{padding:60px 6vw;border-top:1px solid var(--line);max-width:900px;}
  .why-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:24px;}
  .why h3{font-size:15px;font-weight:600;margin-bottom:8px;}
  .why p{color:var(--dim);font-size:14.5px;}
  footer{padding:30px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:12.5px;}
  @media (max-width:700px){.why-grid{grid-template-columns:1fr;}}
</style>
</head>
<body>
<header><div class="brand">route<span>wise</span></div><nav><a href="#docs">Docs</a><a href="#why">Why</a><a href="https://github.com" class="stars">★ 1.2k</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">MIT licensed · zero dependencies</div>
  <h1>A router that doesn't need a config file to explain itself.</h1>
  <p>routewise is a 4KB routing library for small services — pattern matching, typed params, no middleware chain you need a diagram to understand.</p>
  <div class="install"><span class="cmt"># install</span><br>npm install routewise</div>
</section>
<section class="docs" id="docs">
  <h2>Quick start</h2>
  <div class="code">
<span class="kw">import</span> { router } <span class="kw">from</span> <span class="str">'routewise'</span>;<br><br>
<span class="kw">const</span> app = router();<br>
app.get(<span class="str">'/users/:id'</span>, (req) => {<br>
&nbsp;&nbsp;<span class="kw">return</span> { id: req.params.id };<br>
});<br><br>
<span class="cmt">// params are typed from the pattern string itself</span><br>
app.listen(3000);
  </div>
</section>
<section class="why" id="why">
  <h2>Why another router</h2>
  <div class="why-grid">
    <div class="why"><h3>No implicit middleware order</h3><p>Every handler declares exactly what runs before it. Nothing is inherited by accident.</p></div>
    <div class="why"><h3>Params typed from the pattern</h3><p><code>:id</code> in the route string gives you a typed <code>req.params.id</code> — no separate schema.</p></div>
    <div class="why"><h3>4KB, no dependencies</h3><p>Vendor it directly if you want. We won't be offended.</p></div>
    <div class="why"><h3>One file you can actually read</h3><p>The whole matcher is under 300 lines. Reading the source is a legitimate way to learn it.</p></div>
  </div>
</section>
</main>
<footer><div>routewise</div><div>Maintained by volunteers, issues welcome</div></footer>
</body>
</html>
DECOYTPL07
  }

  template_08() {
    # Fieldwork — conference
    local CONF_YEAR CONF_DATE
    CONF_YEAR=$(date +%Y)
    CONF_DATE=$(date -d '+42 days' +'%b %-d, %Y')
    cat <<DECOYTPL08
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fieldwork ${CONF_YEAR} — a small conference on applied ecology</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@500;700;800&family=Inter:wght@400;500;600&display=swap');
  :root{--bg:#efe9df;--ink:#20241f;--dim:#5c6157;--line:#cfc8b8;--moss:#4b6b45;--rust:#a8532f;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:'Inter',sans-serif;line-height:1.6;}
  header{display:flex;justify-content:space-between;align-items:center;padding:24px 6vw;border-bottom:2px solid var(--ink);}
  .brand{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;font-size:20px;}
  nav{display:flex;gap:26px;}
  nav a{color:var(--ink);text-decoration:none;font-size:13.5px;font-weight:500;}
  .hero{padding:80px 6vw 60px;max-width:1000px;}
  .hero .eyebrow{font-family:'Bricolage Grotesque',sans-serif;font-weight:700;color:var(--rust);font-size:13px;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:20px;}
  .hero h1{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;font-size:clamp(38px,7vw,84px);line-height:.98;margin-bottom:24px;}
  .hero p{color:var(--dim);max-width:52ch;font-size:17px;margin-bottom:30px;}
  .meta-row{display:flex;gap:30px;flex-wrap:wrap;margin-bottom:34px;font-family:'Bricolage Grotesque',sans-serif;font-weight:700;font-size:14px;}
  .meta-row div span{display:block;font-family:'Inter',sans-serif;font-weight:400;color:var(--dim);font-size:12px;margin-top:4px;}
  .btn{display:inline-block;padding:15px 28px;background:var(--ink);color:var(--bg);text-decoration:none;font-weight:600;font-size:14px;}
  .schedule{padding:70px 6vw;border-top:2px solid var(--ink);max-width:1000px;}
  .schedule h2{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;font-size:clamp(24px,3.4vw,36px);margin-bottom:36px;}
  .slot{display:grid;grid-template-columns:110px 1fr 140px;gap:20px;padding:20px 0;border-bottom:1px solid var(--line);align-items:baseline;}
  .slot .time{font-family:'Bricolage Grotesque',sans-serif;font-weight:700;color:var(--rust);}
  .slot h3{font-size:16px;font-weight:600;}
  .slot p{color:var(--dim);font-size:13.5px;margin-top:4px;}
  .slot .track{font-size:12.5px;color:var(--moss);font-weight:600;text-align:right;}
  .cta{padding:90px 6vw;border-top:2px solid var(--ink);text-align:center;}
  .cta h2{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;font-size:clamp(28px,5vw,52px);max-width:18ch;margin:0 auto 22px;}
  .cta p{color:var(--dim);max-width:46ch;margin:0 auto 28px;}
  footer{padding:30px 6vw;border-top:2px solid var(--ink);display:flex;justify-content:space-between;font-size:13px;color:var(--dim);}
  @media (max-width:800px){nav{display:none;} .slot{grid-template-columns:70px 1fr;} .slot .track{display:none;}}
</style>
</head>
<body>
<header><div class="brand">FIELDWORK</div><nav><a href="#schedule">Schedule</a><a href="#register">Register</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">A one-day, single-track gathering</div>
  <h1>Fieldwork ${CONF_YEAR}</h1>
  <p>Forty people who monitor real ecosystems for a living, comparing notes on what actually works when the sensor gets eaten by a goat.</p>
  <div class="meta-row">
    <div>${CONF_DATE}<span>One day only</span></div>
    <div>Ljubljana<span>Botanical institute hall</span></div>
    <div>60 seats<span>No livestream</span></div>
  </div>
  <a class="btn" href="#register">Request an invite</a>
</section>
<section class="schedule" id="schedule">
  <h2>Schedule</h2>
  <div class="slot"><div class="time">09:30</div><div><h3>Opening: what we got wrong last year</h3><p>A short, unflattering recap from the organizers.</p></div><div class="track">Plenary</div></div>
  <div class="slot"><div class="time">10:15</div><div><h3>Sensor drift in the field, not the lab</h3><p>Why calibration curves from indoor tests rarely survive week three outdoors.</p></div><div class="track">Talk</div></div>
  <div class="slot"><div class="time">11:30</div><div><h3>When the dataset has a hole and you can't go back</h3><p>Case studies in interpolation, and when to just admit the gap.</p></div><div class="track">Talk</div></div>
  <div class="slot"><div class="time">14:00</div><div><h3>Working session: shared equipment registry</h3><p>An attempt to stop three labs from independently reinventing the same logger.</p></div><div class="track">Workshop</div></div>
  <div class="slot"><div class="time">16:00</div><div><h3>Closing panel: what to try next season</h3><p>Open floor, no slides allowed.</p></div><div class="track">Plenary</div></div>
</section>
<section class="cta" id="register">
  <h2>We keep it to sixty people.</h2>
  <p>No sponsor booths, no recorded talks. Tell us in a couple of sentences what you actually monitor and we'll get back to you.</p>
  <a class="btn" href="mailto:hello@fieldworkconf.org">Request an invite</a>
</section>
</main>
<footer><div>Fieldwork ${CONF_YEAR}</div><div>Organized by working field ecologists, not a conference company</div></footer>
</body>
</html>
DECOYTPL08
  }

  template_09() {
    # Greywacke — interior design studio
    cat <<'DECOYTPL09'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Greywacke — Interior Design Studio</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Newsreader:ital,wght@0,400;0,500;1,400&family=Work+Sans:wght@400;500;600&display=swap');
  :root{--bg:#e9e6e0;--ink:#2b2a26;--dim:#6d685e;--line:#d2cdc2;--stone:#8a8478;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:'Work Sans',sans-serif;line-height:1.6;}
  header{display:flex;justify-content:space-between;align-items:center;padding:30px 6vw;}
  .brand{font-family:'Newsreader',serif;font-size:20px;letter-spacing:.5px;}
  nav{display:flex;gap:28px;}
  nav a{color:var(--dim);text-decoration:none;font-size:13px;letter-spacing:.5px;text-transform:uppercase;}
  nav a:hover{color:var(--ink);}
  .hero{padding:20px 6vw 0;max-width:1200px;display:grid;grid-template-columns:1.1fr .9fr;gap:60px;align-items:end;}
  .hero .eyebrow{color:var(--stone);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;margin-bottom:22px;}
  .hero h1{font-family:'Newsreader',serif;font-weight:500;font-size:clamp(34px,5.2vw,64px);line-height:1.08;margin-bottom:24px;}
  .hero p{color:var(--dim);max-width:44ch;font-size:16.5px;}
  .hero-img{aspect-ratio:4/5;background:linear-gradient(150deg,#b7b0a0,#8a8478);}
  .strip{padding:80px 6vw;display:grid;grid-template-columns:repeat(3,1fr);gap:2px;max-width:1200px;margin:0 auto;}
  .strip .cell{aspect-ratio:1/1;background:linear-gradient(160deg,#c9c3b5,#a29c8c);position:relative;}
  .strip .cell .cap{position:absolute;bottom:14px;left:14px;font-family:'Newsreader',serif;font-style:italic;font-size:14px;}
  .principles{padding:60px 6vw 100px;max-width:1200px;margin:0 auto;display:grid;grid-template-columns:1fr 1.4fr;gap:60px;}
  .principles .label{color:var(--stone);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;margin-bottom:20px;}
  .principles h2{font-family:'Newsreader',serif;font-weight:500;font-size:clamp(24px,3vw,34px);max-width:14ch;}
  .plist{display:flex;flex-direction:column;gap:24px;}
  .plist .item{border-top:1px solid var(--line);padding-top:20px;}
  .plist h3{font-size:15px;font-weight:600;margin-bottom:6px;}
  .plist p{color:var(--dim);font-size:14.5px;}
  .contact{padding:70px 6vw;border-top:1px solid var(--line);text-align:center;}
  .contact h2{font-family:'Newsreader',serif;font-weight:500;font-size:clamp(26px,3.6vw,40px);max-width:20ch;margin:0 auto 20px;}
  .contact p{color:var(--dim);max-width:44ch;margin:0 auto 26px;}
  .btn{display:inline-block;padding:14px 28px;border:1px solid var(--ink);color:var(--ink);text-decoration:none;font-size:13px;letter-spacing:.5px;text-transform:uppercase;}
  footer{padding:32px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:12.5px;}
  @media (max-width:900px){.hero{grid-template-columns:1fr;} nav{display:none;} .strip{grid-template-columns:1fr 1fr;} .principles{grid-template-columns:1fr;}}
</style>
</head>
<body>
<header><div class="brand">Greywacke</div><nav><a href="#work">Work</a><a href="#studio">Studio</a><a href="#contact">Contact</a></nav></header>
<main>
<section class="hero">
  <div>
    <div class="eyebrow">Residential interiors, mostly renovations</div>
    <h1>We design around the house you already have.</h1>
    <p>Greywacke works almost entirely on renovations — old bones, awkward layouts, rooms that were clearly an afterthought in 1974. We like that problem.</p>
  </div>
  <div class="hero-img"></div>
</section>
<section class="strip" id="work">
  <div class="cell"><div class="cap">A kitchen, unstacked</div></div>
  <div class="cell"><div class="cap">Reading nook, north light</div></div>
  <div class="cell"><div class="cap">Stair landing, before/after</div></div>
</section>
<section class="principles" id="studio">
  <div><div class="label">How we work</div><h2>Three things we won't do, and why.</h2></div>
  <div class="plist">
    <div class="item"><h3>No moodboard before a site visit</h3><p>We measure the actual light before we pick a palette for it.</p></div>
    <div class="item"><h3>No full-gut renovations by default</h3><p>Most houses have one or two rooms worth fixing properly, not six worth doing cheaply.</p></div>
    <div class="item"><h3>No sourcing we haven't seen in person</h3><p>If we spec it, someone from the studio has stood in front of it.</p></div>
  </div>
</section>
<section class="contact" id="contact">
  <h2>Bring us the room that annoys you most.</h2>
  <p>We take on a small number of projects at a time — usually four running at once, no more.</p>
  <a class="btn" href="mailto:studio@greywacke.design">Start a project</a>
</section>
</main>
<footer><div>Greywacke Studio</div><div>Renovation-focused, four projects at a time</div></footer>
</body>
</html>
DECOYTPL09
  }

  template_10() {
    # Elm Street — community garden
    local EST_YEAR
    EST_YEAR=$(( $(date +%Y) - 12 ))
    cat <<DECOYTPL10
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Elm Street Community Garden</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Caveat:wght@600&family=Nunito+Sans:wght@400;500;600;700&display=swap');
  :root{--bg:#f4f1e6;--ink:#2c3524;--dim:#5d6650;--line:#d6d2bd;--green:#5c7a3f;--tomato:#c1512f;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:'Nunito Sans',sans-serif;line-height:1.65;}
  header{display:flex;justify-content:space-between;align-items:center;padding:26px 6vw;border-bottom:2px dashed var(--line);}
  .brand{font-family:'Caveat',cursive;font-size:30px;color:var(--green);font-weight:600;}
  nav{display:flex;gap:26px;}
  nav a{color:var(--dim);text-decoration:none;font-size:14px;font-weight:600;}
  nav a:hover{color:var(--green);}
  .hero{padding:60px 6vw 50px;max-width:900px;}
  .hero .eyebrow{font-family:'Caveat',cursive;font-size:20px;color:var(--tomato);margin-bottom:14px;}
  .hero h1{font-size:clamp(28px,4.6vw,46px);font-weight:700;line-height:1.2;margin-bottom:20px;max-width:16ch;}
  .hero p{color:var(--dim);max-width:52ch;font-size:16.5px;margin-bottom:26px;}
  .btn{display:inline-block;padding:13px 24px;background:var(--green);color:#f4f1e6;text-decoration:none;font-weight:700;font-size:14px;border-radius:20px;}
  .plots{padding:50px 6vw;border-top:2px dashed var(--line);}
  .plots-head{margin-bottom:34px;}
  .plots-head .label{font-family:'Caveat',cursive;font-size:20px;color:var(--tomato);}
  .plots-head h2{font-size:clamp(22px,3vw,30px);font-weight:700;margin-top:4px;}
  .plot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;}
  .plot{background:#fff;border:2px solid var(--line);border-radius:10px;padding:20px;text-align:center;}
  .plot .status{font-family:'Caveat',cursive;font-size:18px;}
  .plot.open .status{color:var(--green);}
  .plot.full .status{color:var(--dim);}
  .plot h3{font-size:14px;font-weight:700;margin-top:8px;}
  .season{padding:60px 6vw;border-top:2px dashed var(--line);text-align:center;background:#eae5d3;}
  .season h2{font-size:clamp(24px,3.6vw,36px);font-weight:700;max-width:20ch;margin:0 auto 18px;}
  .season p{color:var(--dim);max-width:48ch;margin:0 auto 26px;}
  footer{padding:30px 6vw;border-top:2px dashed var(--line);display:flex;justify-content:space-between;color:var(--dim);font-size:13px;}
  @media (max-width:800px){nav{display:none;} .plot-grid{grid-template-columns:1fr 1fr;}}
</style>
</head>
<body>
<header><div class="brand">Elm Street Garden</div><nav><a href="#plots">Plots</a><a href="#volunteer">Volunteer</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">est. ${EST_YEAR}, all-volunteer run</div>
  <h1>Forty plots, one waiting list, zero pesticides.</h1>
  <p>Elm Street Garden has been a vacant lot, then a garden, for eleven years now — run entirely by the people who tend it, no city funding, no sponsor sign.</p>
  <a class="btn" href="#plots">Check plot availability</a>
</section>
<section class="plots" id="plots">
  <div class="plots-head"><div class="label">this season</div><h2>Plot availability</h2></div>
  <div class="plot-grid">
    <div class="plot full"><div class="status">Full</div><h3>Row A (1–10)</h3></div>
    <div class="plot open"><div class="status">2 open</div><h3>Row B (11–20)</h3></div>
    <div class="plot full"><div class="status">Full</div><h3>Row C (21–30)</h3></div>
    <div class="plot open"><div class="status">1 open</div><h3>Row D (31–40)</h3></div>
  </div>
</section>
<section class="season" id="volunteer">
  <h2>The waiting list moves faster if you volunteer.</h2>
  <p>We run a shared compost system, a tool shed, and a Saturday work morning — showing up counts, even before you have your own plot.</p>
  <a class="btn" href="mailto:hello@elmstreetgarden.org">Join the waiting list</a>
</section>
</main>
<footer><div>Elm Street Community Garden</div><div>Open dawn to dusk, gate code shared with plot holders</div></footer>
</body>
</html>
DECOYTPL10
  }

  template_11() {
    # SureLite Wing — game squad
    cat <<'DECOYTPL11'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SureLite Wing — Elite Dangerous Community</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Rajdhani:wght@400;500;600&display=swap');
  :root{--void:#060708;--panel:#0c1013;--line:#1c2429;--amber:#ff9d2e;--amber-dim:#8a5a1f;--cyan:#4fd8e0;--text:#c9d3d6;--text-dim:#5c6b70;}
  *{margin:0;padding:0;box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{background:var(--void);color:var(--text);font-family:'Rajdhani',sans-serif;font-size:17px;line-height:1.6;overflow-x:hidden;}
  .stars{position:fixed;inset:0;z-index:0;pointer-events:none;background-image:radial-gradient(1px 1px at 20% 30%,#fff,transparent),radial-gradient(1px 1px at 70% 60%,#fff,transparent),radial-gradient(1px 1px at 40% 80%,#ffffffaa,transparent),radial-gradient(2px 2px at 85% 15%,#ffffffcc,transparent),radial-gradient(1px 1px at 55% 45%,#fff,transparent),radial-gradient(1px 1px at 10% 65%,#ffffff99,transparent),radial-gradient(2px 2px at 90% 85%,#fff,transparent),radial-gradient(1px 1px at 30% 10%,#ffffff88,transparent);background-repeat:repeat;background-size:600px 600px;opacity:.6;}
  .scanline{position:fixed;inset:0;z-index:1;pointer-events:none;background:repeating-linear-gradient(to bottom,rgba(255,157,46,0.015) 0px,rgba(255,157,46,0.015) 1px,transparent 1px,transparent 3px);}
  header{position:sticky;top:0;z-index:10;background:rgba(6,7,8,.85);backdrop-filter:blur(6px);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:18px 6vw;}
  .brand{font-family:'Orbitron',sans-serif;font-weight:700;font-size:20px;letter-spacing:2px;color:var(--amber);display:flex;align-items:center;gap:10px;}
  .brand::before{content:"";width:10px;height:10px;background:var(--amber);clip-path:polygon(50% 0%,0% 100%,100% 100%);display:inline-block;}
  nav{display:flex;gap:34px;}
  nav a{color:var(--text-dim);text-decoration:none;font-size:14px;letter-spacing:1.5px;text-transform:uppercase;transition:color .2s;position:relative;}
  nav a:hover{color:var(--amber);}
  main{position:relative;z-index:2;}
  .hero{min-height:88vh;display:flex;flex-direction:column;justify-content:center;padding:0 6vw;position:relative;}
  .eyebrow{font-family:'Orbitron',sans-serif;color:var(--cyan);font-size:13px;letter-spacing:5px;text-transform:uppercase;margin-bottom:22px;opacity:.85;}
  .hero h1{font-family:'Orbitron',sans-serif;font-weight:900;font-size:clamp(42px,8vw,108px);line-height:.98;letter-spacing:1px;color:#eef2f3;max-width:16ch;}
  .hero h1 span{color:var(--amber);text-shadow:0 0 24px rgba(255,157,46,.35);}
  .hero p{margin-top:26px;max-width:52ch;font-size:19px;color:var(--text-dim);}
  .cta-row{margin-top:44px;display:flex;gap:18px;flex-wrap:wrap;}
  .btn{font-family:'Orbitron',sans-serif;font-size:13px;letter-spacing:2px;text-transform:uppercase;padding:16px 30px;text-decoration:none;border:1px solid var(--amber);color:var(--amber);position:relative;transition:.2s;clip-path:polygon(12px 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%,0 12px);}
  .btn:hover{background:var(--amber);color:var(--void);}
  .btn.ghost{border-color:var(--line);color:var(--text-dim);}
  section{padding:120px 6vw;}
  .section-head{margin-bottom:64px;max-width:60ch;}
  .section-head h2{font-family:'Orbitron',sans-serif;font-weight:700;font-size:clamp(28px,4vw,44px);color:#eef2f3;}
  .grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);}
  .card{background:var(--void);padding:36px 30px;}
  .card h3{font-family:'Orbitron',sans-serif;font-size:19px;color:#eef2f3;margin-bottom:12px;}
  .card p{color:var(--text-dim);font-size:15px;}
  .log{border:1px solid var(--line);background:var(--panel);}
  .log-row{display:grid;grid-template-columns:140px 1fr 160px;gap:20px;padding:22px 28px;border-bottom:1px solid var(--line);}
  .log-row .stamp{font-family:'Orbitron',sans-serif;font-size:12px;color:var(--cyan);}
  .join{text-align:center;border-top:1px solid var(--line);}
  .join h2{font-family:'Orbitron',sans-serif;font-size:clamp(30px,5vw,54px);color:#eef2f3;max-width:22ch;margin:0 auto 20px;}
  .join h2 span{color:var(--amber);}
  footer{border-top:1px solid var(--line);padding:40px 6vw;display:flex;justify-content:space-between;color:var(--text-dim);font-size:13px;}
  @media (max-width:820px){nav{display:none;}.grid3{grid-template-columns:1fr;}.log-row{grid-template-columns:1fr;gap:6px;}}
</style>
</head>
<body>
<div class="stars"></div><div class="scanline"></div>
<header><div class="brand">SureLite Wing</div><nav><a href="#ops">Operations</a><a href="#log">Dispatch Log</a><a href="#join">Recruitment</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">Independent Pilots Federation squadron</div>
  <h1>Charted space<br>needs <span>more wings.</span></h1>
  <p>SureLite Wing is a small player squadron flying in Elite Dangerous — exploration, bounty hunting, and the occasional questionable trade route through the Bubble and beyond.</p>
  <div class="cta-row"><a class="btn" href="#join">Request wing invite</a><a class="btn ghost" href="#log">Read the dispatch log</a></div>
</section>
<section id="ops">
  <div class="section-head"><div class="eyebrow">What we fly for</div><h2>Three loose reasons to jump with us</h2></div>
  <div class="grid3">
    <div class="card"><h3>Exploration Wings</h3><p>Semi-regular deep space passages toward Colonia and back.</p></div>
    <div class="card"><h3>Bounty & Escort</h3><p>Low-key security runs around Robigo and the surrounding res sites.</p></div>
    <div class="card"><h3>Community Goals</h3><p>We show up for the CGs that pay, and skip the ones that don't.</p></div>
  </div>
</section>
<section id="log">
  <div class="section-head"><div class="eyebrow">Dispatch log</div><h2>Recent wing chatter</h2></div>
  <div class="log">
    <div class="log-row"><div class="stamp">3306-08-09</div><div class="msg">Convoy of four made it to Colonia without a single interdiction.</div></div>
    <div class="log-row"><div class="stamp">3306-07-22</div><div class="msg">Robigo run got interesting — three CMDRs jumped in uninvited near the nav beacon.</div></div>
    <div class="log-row"><div class="stamp">3306-06-14</div><div class="msg">Mining expo CG closed out tier 3. Split went out to everyone who logged a delivery.</div></div>
  </div>
</section>
<section id="join" class="join">
  <div class="eyebrow">Recruitment</div>
  <h2>Flying solo gets <span>old fast.</span></h2>
  <p>No minimum rank, no combat rating requirement. If your ship holds air, you're already qualified.</p>
  <a class="btn" href="mailto:wing@surelite.store">wing@surelite.store</a>
</section>
</main>
<footer><div class="brand">SureLite Wing</div><div>Independent player squadron · not affiliated with Frontier Developments</div></footer>
</body>
</html>
DECOYTPL11
  }

  template_12() {
    # Northfold — web studio
    cat <<'DECOYTPL12'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Northfold — Web &amp; Product Studio</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Fraunces:wght@500;600&display=swap');
  :root{--bg:#faf8f5;--ink:#1c1a17;--muted:#6b655c;--line:#e6e0d6;--accent:#2f5d4f;}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:'Inter',sans-serif;line-height:1.6;}
  header{display:flex;justify-content:space-between;align-items:center;padding:28px 6vw;border-bottom:1px solid var(--line);}
  .brand{font-family:'Fraunces',serif;font-weight:600;font-size:22px;}
  nav{display:flex;gap:32px;}
  nav a{color:var(--muted);text-decoration:none;font-size:14px;}
  nav a:hover{color:var(--ink);}
  .hero{padding:100px 6vw 80px;max-width:900px;}
  .hero .eyebrow{color:var(--accent);font-size:13px;letter-spacing:2px;text-transform:uppercase;margin-bottom:18px;}
  .hero h1{font-family:'Fraunces',serif;font-weight:500;font-size:clamp(34px,6vw,64px);line-height:1.1;margin-bottom:24px;}
  .hero p{max-width:56ch;color:var(--muted);font-size:18px;margin-bottom:36px;}
  .btn{display:inline-block;padding:14px 28px;background:var(--accent);color:#fff;text-decoration:none;border-radius:4px;font-size:14px;}
  .btn.ghost{background:none;border:1px solid var(--line);color:var(--ink);margin-left:12px;}
  section{padding:70px 6vw;border-top:1px solid var(--line);}
  .section-head h2{font-family:'Fraunces',serif;font-weight:500;font-size:clamp(24px,3vw,36px);margin-bottom:14px;}
  .section-head p{color:var(--muted);max-width:60ch;margin-bottom:50px;}
  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:36px;}
  .work{border:1px solid var(--line);border-radius:8px;padding:28px;background:#fff;}
  .work .tag{font-size:12px;color:var(--accent);text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;}
  .work h3{font-family:'Fraunces',serif;font-size:19px;margin-bottom:10px;}
  .work p{color:var(--muted);font-size:14.5px;}
  .quote{max-width:700px;margin:0 auto;text-align:center;}
  .quote p{font-family:'Fraunces',serif;font-size:clamp(20px,3vw,28px);color:var(--ink);margin-bottom:20px;}
  .quote span{color:var(--muted);font-size:14px;}
  footer{padding:40px 6vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:var(--muted);font-size:13px;}
  @media (max-width:820px){nav{display:none;}.grid{grid-template-columns:1fr;}}
</style>
</head>
<body>
<header><div class="brand">Northfold</div><nav><a href="#work">Work</a><a href="#about">About</a><a href="#contact">Contact</a></nav></header>
<main>
<section class="hero">
  <div class="eyebrow">Web &amp; product studio</div>
  <h1>We build the quiet parts of good software.</h1>
  <p>Northfold is a small studio working with founders on the parts of a product that don't show up in the demo — onboarding, billing, admin tooling, the boring stuff that has to work.</p>
  <a class="btn" href="#contact">Get in touch</a><a class="btn ghost" href="#work">See recent work</a>
</section>
<section id="work">
  <div class="section-head"><h2>Recent engagements</h2><p>A handful of the things we've shipped over the past year, mostly for small teams who needed one extra pair of hands.</p></div>
  <div class="grid">
    <div class="work"><div class="tag">Fintech</div><h3>Reconciliation dashboard</h3><p>Internal tool for matching payouts against provider statements, built in six weeks.</p></div>
    <div class="work"><div class="tag">Logistics</div><h3>Driver scheduling rebuild</h3><p>Replaced a spreadsheet-based rota system with something the ops team could actually trust.</p></div>
    <div class="work"><div class="tag">SaaS</div><h3>Usage-based billing</h3><p>Metered billing layer on top of an existing subscription product, with proration handled properly.</p></div>
  </div>
</section>
<section id="about">
  <div class="quote">
    <p>&ldquo;They didn't try to rebuild everything. They just fixed the part that was actually broken.&rdquo;</p>
    <span>— a client, paraphrased slightly</span>
  </div>
</section>
<section id="contact">
  <div class="section-head"><h2>Start a conversation</h2><p>No discovery calls, no decks. Send a couple of sentences about what's not working and we'll reply within a day or two.</p></div>
  <a class="btn" href="mailto:hello@northfold.studio">hello@northfold.studio</a>
</section>
</main>
<footer><div>Northfold Studio</div><div>Remote-first, small by design</div></footer>
</body>
</html>
DECOYTPL12
  }

  # --- Общий рендер для login-decoy (жанр: панели самопальных тулз) ---
  # Форма ничего никуда не отправляет: onsubmit="return false" глушит
  # реальную отправку, JS-обработчик локально показывает "Invalid
  # credentials". Ни одного сетевого запроса, ни одного нового backend-пути.
  render_login_page() {
    local font_import="$1" font_heading="$2" font_body="$3"
    local bg="$4" card="$5" ink="$6" muted="$7" accent="$8"
    local brand="$9" subtitle="${10}"
    local f1_label="${11}" f2_label="${12}" cta="${13}" footnote="${14}"

    cat <<HTMLEOF
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${brand} — sign in</title>
<style>
  @import url('${font_import}');
  :root{--bg:${bg};--card:${card};--ink:${ink};--muted:${muted};--accent:${accent};}
  *{margin:0;padding:0;box-sizing:border-box;}
  body{background:var(--bg);color:var(--ink);font-family:${font_body};min-height:100vh;display:flex;align-items:center;justify-content:center;padding:2rem;}
  .wrap{width:100%;max-width:380px;}
  .brand{font-family:${font_heading};font-size:20px;text-align:center;margin-bottom:8px;color:var(--ink);}
  .sub{text-align:center;color:var(--muted);font-size:13px;margin-bottom:32px;}
  .card{background:var(--card);border:1px solid color-mix(in srgb, var(--muted) 25%, transparent);border-radius:8px;padding:32px 28px;}
  label{display:block;font-size:12.5px;color:var(--muted);margin-bottom:6px;letter-spacing:.2px;}
  input{width:100%;padding:11px 12px;margin-bottom:18px;background:color-mix(in srgb, var(--ink) 4%, transparent);border:1px solid color-mix(in srgb, var(--muted) 30%, transparent);border-radius:5px;color:var(--ink);font-size:14px;font-family:${font_body};}
  input:focus{outline:none;border-color:var(--accent);}
  button{width:100%;padding:12px;background:var(--accent);color:var(--bg);border:none;border-radius:5px;font-size:14px;font-weight:600;cursor:pointer;font-family:${font_body};}
  .err{display:none;color:var(--accent);font-size:12.5px;margin:-8px 0 16px;}
  .foot{text-align:center;color:var(--muted);font-size:11.5px;margin-top:24px;}
</style>
</head>
<body>
<div class="wrap">
  <div class="brand">${brand}</div>
  <div class="sub">${subtitle}</div>
  <div class="card">
    <form id="lf" onsubmit="return false;">
      <label>${f1_label}</label>
      <input type="text" autocomplete="username">
      <label>${f2_label}</label>
      <input type="password" autocomplete="current-password">
      <div class="err" id="err">Invalid credentials.</div>
      <button type="submit">${cta}</button>
    </form>
  </div>
  <div class="foot">${footnote}</div>
</div>
<script>
document.getElementById('lf').addEventListener('submit', function(){
  document.getElementById('err').style.display = 'block';
});
</script>
</body>
</html>
HTMLEOF
  }

