  run_err404() {
    local n
    n=$(printf "%02d" "$1")
    "err404_${n}"
  }

  run_template() {
    local n
    n=$(printf "%02d" "$1")
    "template_${n}"
  }

  # Индекс шаблона считается от домена (не от $RANDOM), чтобы при
  # повторной установке на тот же домен сайт не менялся каждый раз,
  # а на 50 разных серверах шаблоны почти наверняка не совпадали.
  hash1=$(printf '%s' "$DOMAIN" | cksum | cut -d' ' -f1)
  idx1=$(( hash1 % TEMPLATE_COUNT ))
  hash2=$(printf '%s' "$REALITY_DOMAIN" | cksum | cut -d' ' -f1)
  idx2=$(( hash2 % TEMPLATE_COUNT ))
  [[ "$idx2" == "$idx1" ]] && idx2=$(( (idx2 + 1) % TEMPLATE_COUNT ))

  run_template "$((idx1 + 1))" > "${DECOY_ROOT_1}/index.html"
  run_template "$((idx2 + 1))" > "${DECOY_ROOT_2}/index.html"
  echo "  Decoy №1 (${DOMAIN}):          шаблон #$((idx1 + 1))/${TEMPLATE_COUNT}"
  echo "  Decoy №2 (${REALITY_DOMAIN}):   шаблон #$((idx2 + 1))/${TEMPLATE_COUNT}"

  chown -R www-data:www-data "$DECOY_ROOT_1" "$DECOY_ROOT_2"

  # --- Decoy extras: 404, robots.txt, sitemap.xml ---
  # Decoy №1 (panel domain)
  cat > "${DECOY_ROOT_1}/robots.txt" <<ROBOTS
User-agent: *
Allow: /
Sitemap: https://${DOMAIN}/sitemap.xml
ROBOTS
  cat > "${DECOY_ROOT_1}/sitemap.xml" <<SITEMAP
<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url><loc>https://${DOMAIN}/</loc><changefreq>weekly</changefreq><priority>1.0</priority></url>
</urlset>
SITEMAP
  run_err404 "$((idx1 + 1))" > "${DECOY_ROOT_1}/404.html"

  # Decoy №2 (reality domain)
  cat > "${DECOY_ROOT_2}/robots.txt" <<ROBOTS
User-agent: *
Allow: /
Sitemap: https://${REALITY_DOMAIN}/sitemap.xml
ROBOTS
  cat > "${DECOY_ROOT_2}/sitemap.xml" <<SITEMAP
<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url><loc>https://${REALITY_DOMAIN}/</loc><changefreq>weekly</changefreq><priority>1.0</priority></url>
</urlset>
SITEMAP
  run_err404 "$((idx2 + 1))" > "${DECOY_ROOT_2}/404.html"

  # --- [7.5/10] nginx connection limits ---
  echo "=== [7.5/10] nginx: лимиты соединений и файловых дескрипторов ==="
  # Дефолтные 768 worker_connections недостаточны при ~400+ активных
  # проксируемых сессиях (каждая занимает 2 слота). Выставляем 4096
  # с запасом ~5× от текущей пиковой нагрузки.
  NGINX_CONF="/etc/nginx/nginx.conf"

  # worker_connections 4096
  if grep -qE '^\s*worker_connections\s+' "$NGINX_CONF"; then
    sed -i 's/^\s*worker_connections\s*.*/        worker_connections 4096;/' "$NGINX_CONF"
  else
    # Вставляем в блок events { ... }
    sed -i '/events {/a\        worker_connections 4096;' "$NGINX_CONF"
  fi
  echo "  worker_connections -> 4096"

  # worker_rlimit_nofile 65535
  if grep -qE '^\s*worker_rlimit_nofile\s+' "$NGINX_CONF"; then
    sed -i 's/^\s*worker_rlimit_nofile\s*.*/worker_rlimit_nofile 65535;/' "$NGINX_CONF"
  else
    # Вставляем сразу после worker_processes
    sed -i '/worker_processes/a\worker_rlimit_nofile 65535;' "$NGINX_CONF"
  fi
  echo "  worker_rlimit_nofile -> 65535"

  # systemd LimitNOFILE через override
  mkdir -p /etc/systemd/system/nginx.service.d
  cat > /etc/systemd/system/nginx.service.d/override.conf <<'SYSTEMDEOF'
[Service]
LimitNOFILE=65535
SYSTEMDEOF
  systemctl daemon-reload
  echo "  systemd LimitNOFILE -> 65535 (override.conf)"

  # Валидируем конфиг сразу после правок — если sed что-то сломал,
  # ошибка всплывёт здесь с точной привязкой к шагу, а не позже
  # в общем nginx -t после всех остальных блоков.
  if nginx -t 2>&1 | grep -q "successful"; then
    echo "  nginx -t: OK"
  else
    echo "  ОШИБКА: nginx -t не прошёл после изменения лимитов."
    nginx -t || true
    exit 1
  fi

  # --- [8/10] nginx http (с location для подписок) ---
  echo "=== [8/10] nginx http-блоки (с подписками) ==="
  # 80-redirect.conf уже создан и включён на шаге [6/10] (нужен был
  # заранее для webroot-выдачи сертификатов) — здесь только SSL-vhost'ы.

  cat > "/etc/nginx/sites-available/${DOMAIN}.conf" <<EOF
server {
    listen 127.0.0.1:${PANEL_INTERNAL_PORT} ssl proxy_protocol;
    # proxy_protocol на listen сам по себе только парсит заголовок,
    # но не подставляет его в \$remote_addr — без этих двух строк IP
    # клиентов панели/подписок так и останутся 127.0.0.1. Проверено
    # вживую на всех трёх продакшн-серверах 27-28 авг 2026.
    set_real_ip_from 127.0.0.1;
    real_ip_header proxy_protocol;
    server_tokens off;
    add_header Strict-Transport-Security "max-age=31536000" always;
    ssl_certificate     /etc/letsencrypt/live/${DOMAIN}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/${DOMAIN}/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    root ${DECOY_ROOT_1};
    index index.html;
    error_page 404 /404.html;

    location ${PANEL_PATH} {
        proxy_pass http://127.0.0.1:${PANEL_PORT};
        proxy_redirect off;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    # Подписки vless + Clash (panel сама различает по User-Agent,
    # subClashAutoDetect=true по умолчанию — один location для обоих)
    location ${SUB_SECRET_PATH} {
        proxy_pass http://127.0.0.1:${SUB_PORT};
        proxy_redirect off;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    # AmneziaWG-подписка — рандомизированный префикс
    location ${AWG_SECRET_PATH} {
        proxy_pass http://127.0.0.1:${SUB_PORT};
        proxy_redirect off;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    location / {
        try_files \$uri \$uri/ =404;
    }
}
EOF

  cat > "/etc/nginx/sites-available/${REALITY_DOMAIN}.conf" <<EOF
server {
    listen 127.0.0.1:${REALITY_DECOY_INTERNAL_PORT} ssl;
    server_tokens off;
    add_header Strict-Transport-Security "max-age=31536000" always;
    ssl_certificate     /etc/letsencrypt/live/${REALITY_DOMAIN}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/${REALITY_DOMAIN}/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    root ${DECOY_ROOT_2};
    index index.html;
    error_page 404 /404.html;
    location / { try_files \$uri \$uri/ =404; }
}
EOF

  # v0.4.0: plain-HTTP фасад decoy №2 (:8080, loopback) — цель fallback'а TLS-режима
  ensure_decoy2_http_vhost || exit 1

  ln -sf "/etc/nginx/sites-available/80-redirect.conf" "/etc/nginx/sites-enabled/80-redirect.conf"
  ln -sf "/etc/nginx/sites-available/${DOMAIN}.conf" "/etc/nginx/sites-enabled/${DOMAIN}.conf"
  ln -sf "/etc/nginx/sites-available/${REALITY_DOMAIN}.conf" "/etc/nginx/sites-enabled/${REALITY_DOMAIN}.conf"
  rm -f /etc/nginx/sites-enabled/default

  # --- [9/10] nginx stream ---
  echo "=== [9/10] nginx stream SNI-роутер ==="
  STREAM_CONF="/etc/nginx/stream-sni-router.conf"
  cat > "$STREAM_CONF" <<EOF
stream {
    map \$ssl_preread_server_name \$backend_pool {
        ${DOMAIN}          panel_backend;
        ${REALITY_DOMAIN}  reality_backend;
        default            reality_backend;
    }
    upstream panel_backend { server 127.0.0.1:${PANEL_INTERNAL_PORT}; }
    upstream reality_backend { server 127.0.0.1:${REALITY_XRAY_PORT}; }
    server {
        # v0.3.5: вернули явный IP (wildcard-форма из v0.3.3-v0.3.4
        # оказалась регрессом — см. changelog). Смена IP у провайдера
        # теперь штатно решается режимом rebind-ip, а не wildcard.
        listen ${SERVER_IP}:443;
        proxy_pass \$backend_pool;
        ssl_preread on;
        proxy_protocol on;
    }
}
EOF
  if ! grep -q 'include /etc/nginx/stream-sni-router.conf;' /etc/nginx/nginx.conf; then
    if grep -q '^stream {' /etc/nginx/nginx.conf; then
      sed -i '/^stream {/a\    include '${STREAM_CONF}';' /etc/nginx/nginx.conf
    else
      sed -i "\$a include ${STREAM_CONF};" /etc/nginx/nginx.conf
    fi
  fi
  nginx -t || { echo "ОШИБКА: nginx config test failed"; exit 1; }
  systemctl restart nginx
  systemctl enable nginx

  # --- [10/10] vless inbound (режим: ${VLESS_MODE} с v0.3.9) ---
  echo "=== [10/10] vless inbound, режим ${VLESS_MODE} (SQLite) ==="
  XRAY_BIN="/usr/local/x-ui/bin/xray-linux-${ARCH}"
  if [[ ! -f "$XRAY_BIN" ]]; then
    XRAY_BIN=$(find /usr/local/x-ui -maxdepth 3 -name "xray-linux-*" -type f | head -n1 || true)
  fi

  if [[ -z "$XRAY_BIN" || ! -f "$XRAY_BIN" || ! -f "$XUIDB" ]]; then
    echo "Не нашёл xray или x-ui.db — создай vless-инбаунд вручную через панель."
    REALITY_OK=0
  else
    if sqlite3 "$XUIDB" "SELECT 1 FROM inbounds WHERE protocol='vless' AND port='${REALITY_XRAY_PORT}' AND listen='127.0.0.1' LIMIT 1;" 2>/dev/null | grep -q 1; then
      echo "vless-инбаунд на 127.0.0.1:${REALITY_XRAY_PORT} уже существует — переиспользую (дубликат не создаю)."
      REALITY_OK=1
    else
      systemctl stop x-ui
      sleep 1
      cp "$XUIDB" "${XUIDB}.backup.$(date +%s)"

      CLIENT_UUID=$(cat /proc/sys/kernel/random/uuid)
      NOW_MS=$(( $(date +%s) * 1000 ))

      if [[ "$VLESS_MODE" == "reality" ]]; then
        KEYS_OUT=$("$XRAY_BIN" x25519 2>/dev/null || true)
        if command -v jq >/dev/null 2>&1; then
          REALITY_PRIVATE=$(echo "$KEYS_OUT" | jq -r '.privateKey // empty' 2>/dev/null || true)
          REALITY_PUBLIC=$(echo "$KEYS_OUT" | jq -r '.publicKey // empty' 2>/dev/null || true)
        fi
        if [[ -z "$REALITY_PRIVATE" || -z "$REALITY_PUBLIC" ]]; then
          REALITY_PRIVATE=$(echo "$KEYS_OUT" | grep -oP '(?<=Private key: ).*' || echo "$KEYS_OUT" | grep -i 'Private' | awk '{print $NF}')
          REALITY_PUBLIC=$(echo "$KEYS_OUT" | grep -oP '(?<=Public key: ).*' || echo "$KEYS_OUT" | grep -i 'Public' | awk '{print $NF}')
        fi
        if [[ -z "$REALITY_PRIVATE" || -z "$REALITY_PUBLIC" ]]; then
          echo "ОШИБКА: не удалось сгенерировать Reality-ключи."
          systemctl start x-ui
          exit 1
        fi
        SHORT_ID_1=$(openssl rand -hex 8)
        SHORT_ID_2=$(openssl rand -hex 8)
        # Vision + проба-фасад через dest (классическая схема до v0.3.9)
        SETTINGS_JSON='{"clients":[{"id":"'"${CLIENT_UUID}"'","flow":"xtls-rprx-vision","email":"client1","limitIp":0,"totalGB":0,"expiryTime":0,"enable":true,"tgId":0,"subId":"primary","reset":0,"created_at":'"${NOW_MS}"',"updated_at":'"${NOW_MS}"'}],"decryption":"none","fallbacks":[]}'
        STREAM_JSON='{"network":"tcp","security":"reality","realitySettings":{"show":false,"dest":"127.0.0.1:'"${REALITY_DECOY_INTERNAL_PORT}"'","xver":0,"serverNames":["'"${REALITY_DOMAIN}"'"],"privateKey":"'"${REALITY_PRIVATE}"'","minClient":"","maxClient":"","maxTimediff":0,"shortIds":["'"${SHORT_ID_1}"'","'"${SHORT_ID_2}"'"],"settings":{"publicKey":"'"${REALITY_PUBLIC}"'","fingerprint":"chrome","serverName":"","spiderX":"/"}},"tcpSettings":{"acceptProxyProtocol":true,"header":{"type":"none"}}}'
      else
        # v0.3.9 TLS-режим: конфигурация, проверенная живьём на
        # prod-node-1 (2026-09-30). xray терминирует TLS сам, серт с
        # диска; fallback -> :80 даёт пробам 301-фасад; flow="" — рабочая
        # связка RU-клиентов (fp=firefox, raw). v0.5.1: flow=xtls-rprx-vision по умолчанию.
        if [[ ! -f "/etc/letsencrypt/live/${REALITY_DOMAIN}/fullchain.pem" || ! -f "/etc/letsencrypt/live/${REALITY_DOMAIN}/privkey.pem" ]]; then
          echo "ОШИБКА: серт ${REALITY_DOMAIN} не найден в /etc/letsencrypt/live/ — TLS-режим невозможен."
          systemctl start x-ui
          exit 1
        fi
        SETTINGS_JSON='{"clients":[{"id":"'"${CLIENT_UUID}"'","flow":"xtls-rprx-vision","email":"client1","limitIp":0,"totalGB":0,"expiryTime":0,"enable":true,"tgId":0,"subId":"primary","reset":0,"created_at":'"${NOW_MS}"',"updated_at":'"${NOW_MS}"'}],"decryption":"none","fallbacks":[{"dest":"127.0.0.1:8080","xver":0}]}'
        STREAM_JSON='{"network":"tcp","security":"tls","tlsSettings":{"serverName":"'"${REALITY_DOMAIN}"'","minVersion":"1.2","maxVersion":"1.3","cipherSuites":"","rejectUnknownSni":false,"disableSystemRoot":false,"enableSessionResumption":false,"certificates":[{"ocspStapling":0,"oneTimeLoading":false,"usage":"encipherment","buildChain":false,"certificateFile":"/etc/letsencrypt/live/'"${REALITY_DOMAIN}"'/fullchain.pem","keyFile":"/etc/letsencrypt/live/'"${REALITY_DOMAIN}"'/privkey.pem"}],"alpn":["http/1.1"],"echServerKeys":"","settings":{"echConfigList":"","pinnedPeerCertSha256":[],"verifyPeerCertByName":""}},"tcpSettings":{"acceptProxyProtocol":true,"header":{"type":"none"}}}'
      fi

      # note: не отдельным `if [[ $? -ne 0 ]]` после — под `set -e` такая
      # проверка недостижима (скрипт уже упал бы строкой раньше). Ловим
      # ошибку явно через `||`. v0.3.9: JSON обоих режимов собран выше в
      # SETTINGS_JSON/STREAM_JSON (внутри — только двойные кавычки, для
      # SQL-строки в одинарных это безопасно).
      sqlite3 "$XUIDB" "INSERT INTO inbounds (\"user_id\",\"up\",\"down\",\"total\",\"remark\",\"enable\",\"expiry_time\",\"listen\",\"port\",\"protocol\",\"settings\",\"stream_settings\",\"tag\",\"sniffing\") VALUES ('1','0','0','0','${REALITY_REMARK}','1','0','127.0.0.1','${REALITY_XRAY_PORT}','vless','${SETTINGS_JSON}','${STREAM_JSON}','${REALITY_TAG}','{\"enabled\":false,\"destOverride\":[\"http\",\"tls\",\"quic\",\"fakedns\"],\"metadataOnly\":false,\"routeOnly\":false}');" || {
        echo "ОШИБКА: SQLite INSERT не удался. Бэкап: ${XUIDB}.backup.*"
        systemctl start x-ui
        exit 1
      }

      # Создаём запись в client_traffics с email из JSON, иначе "Сбросить трафик" падает с nil pointer
      sqlite3 "$XUIDB" "INSERT INTO client_traffics (inbound_id, email, up, down, total, expiry_time, reset, enable) SELECT id, json_extract(settings, '$.clients[0].email'), 0, 0, 0, 0, 0, 1 FROM inbounds WHERE remark='${REALITY_REMARK}' ON CONFLICT DO NOTHING;"

      systemctl start x-ui
      sleep 2
      if ! systemctl is-active --quiet x-ui; then
        echo "ОШИБКА: x-ui не запустился. Смотри: journalctl -u x-ui -n 50"
        exit 1
      fi
      # v0.3.7: is-active недостаточен — краш-луп xray юнит не роняет (урок
      # v0.3.5: install «успешен», Reality мёртв, ловит только healthcheck
      # [2]). Проверяем фактический листенер 127.0.0.1:443 и владельца xray;
      # ретраи на медленный старт ядра.
      REALITY_TCP_PID=""
      for _ in 1 2 3 4 5; do
        REALITY_TCP_PID=$(ss -tlnp 2>/dev/null | grep -E '127\.0\.0\.1:443\b' | grep -oP 'pid=\K[0-9]+' | head -n1 || true)
        if [[ -n "$REALITY_TCP_PID" ]] && tr '\0' ' ' < "/proc/${REALITY_TCP_PID}/cmdline" 2>/dev/null | grep -qi xray; then
          break
        fi
        REALITY_TCP_PID=""
        sleep 2
      done
      if [[ -z "$REALITY_TCP_PID" ]]; then
        echo "ОШИБКА: xray не подтверждён на 127.0.0.1:443 после старта — Reality мёртв (краш-луп xray?). Смотри: journalctl -u x-ui -n 50"
        exit 1
      fi
      REALITY_OK=1
    fi
  fi

  # --- [10a] Hysteria 2 inbound на UDP/443 (SQLite) ---
  echo "=== [10a] Hysteria 2 inbound на UDP/443 (SQLite) ==="
  create_hy2_inbound || exit 1

  # --- [10b] Опция: Telegram-бот управления (v0.4.8; дефолт НЕТ) ---
  echo
  echo "=== [10b] Telegram-бот управления панелью (опция) ==="
  local BOT_WANT=""
  read -rp "Поставить Telegram-бота управления? [y/N]: " BOT_WANT || BOT_WANT=""
  if [[ "$BOT_WANT" =~ ^[Yy] ]]; then
    cmd_add_bot || echo "Бот не поставился — установка панели не пострадала; поставь позже: sudo bash $0 add-bot"
  else
    echo "Пропущено (поставить позже: sudo bash $0 add-bot)"
  fi

  # --- Финал ---
  echo
  echo "================= ГОТОВО ================="
  echo "Панель:              https://${DOMAIN}${PANEL_PATH}"
  echo "Логин/пароль:        ${XUI_USERNAME} / ${XUI_PASSWORD}"
  echo "Подписки:            https://${DOMAIN}${SUB_SECRET_PATH}"
  echo "AWG подписки:        https://${DOMAIN}${AWG_SECRET_PATH}"
  echo "Decoy №1:            https://${DOMAIN}/"
  if [[ "${VLESS_MODE}" == "tls" ]]; then
    echo "Decoy №2:            https://${REALITY_DOMAIN}/ отдаёт decoy-сайт (fallback -> 127.0.0.1:8080)"
  else
    echo "Decoy №2:            https://${REALITY_DOMAIN}/"
  fi
  echo "443 порт:            nginx SNI-роутер -> панель ИЛИ vless (${VLESS_MODE})"
  echo
  if [[ "${REALITY_OK:-0}" == "1" ]]; then
    if [[ "${VLESS_MODE}" == "reality" ]]; then
      echo "Reality inbound:     готов (remark: ${REALITY_REMARK})"
      echo "  Client UUID:       ${CLIENT_UUID:-(см. панель)}"
      echo "  Short IDs:          ${SHORT_ID_1:-(см. панель)}, ${SHORT_ID_2:-(см. панель)}"
      echo "  Public key:         ${REALITY_PUBLIC:-(см. панель)}"
      echo "  ServerName:         ${REALITY_DOMAIN}"
    else
      echo "VLESS+TLS inbound:   готов (remark: ${REALITY_REMARK}, fallback -> 127.0.0.1:8080)"
      echo "  Client UUID:       ${CLIENT_UUID:-(см. панель)}"
      echo "  ServerName/SNI:     ${REALITY_DOMAIN}"
      echo "  Ссылка для клиента (raw + fp=firefox + Vision):"
      echo "  vless://${CLIENT_UUID:-(UUID)}@${REALITY_DOMAIN}:443?type=tcp&security=tls&sni=${REALITY_DOMAIN}&fp=firefox&flow=xtls-rprx-vision#${REALITY_REMARK}"
      echo "  (v0.5.1: Vision включён по умолчанию — убирает отпечаток вложенного TLS."
      echo "   Клиент должен поддерживать flow xtls-rprx-vision; старый клиент без flow подключиться не сможет.)"
    fi
  else
    echo "vless inbound:       НЕ создан — создай вручную через панель."
  fi
  if [[ "${HY2_OK:-0}" == "1" && -n "${HY2_AUTH:-}" ]]; then
    echo "Hysteria 2:          UDP/443 (remark: Hy2-443, masquerade -> ${REALITY_DOMAIN})"
    echo "  Client email:      ${HY2_EMAIL}"
    echo "  Auth password:     ${HY2_AUTH}"
    echo "  Ссылка для клиента:"
    echo "  hysteria2://${HY2_AUTH}@${REALITY_DOMAIN}:443/?sni=${REALITY_DOMAIN}&insecure=0#Hy2-443"
  else
    echo "Hysteria 2:          НЕ создан — создай вручную (см. лог выше)."
  fi
  echo

  # v0.3.7: файл создаётся с 600 сразу (touch под локальным umask 077),
  # чтобы не было окна мир-читаемости между "cat >" и chmod 600 ниже.
  # v0.3.8: rm -f перед touch — touch не меняет права СУЩЕСТВУЮЩЕГО файла
  # (реинсталл поверх оставлял бы окно 0644 до chmod ниже); пересоздание под
  # umask 077 гарантирует 600 с первого байта.
  ( umask 077 && rm -f "$CREDS_FILE" && touch "$CREDS_FILE" )
  cat > "$CREDS_FILE" <<EOF
# lucx-ui installation credentials
# Generated: $(date -Iseconds)
Script Version: ${VERSION}
URL: https://${DOMAIN}${PANEL_PATH}
User: ${XUI_USERNAME}
Pass: ${XUI_PASSWORD}
Reality Domain: ${REALITY_DOMAIN}
Reality Remark: ${REALITY_REMARK}
Reality Tag: ${REALITY_TAG}
VLESS Mode: ${VLESS_MODE}
Sub Path: ${SUB_SECRET_PATH}
AWG Path: ${AWG_SECRET_PATH}
Sub Port: ${SUB_PORT}
AWG Port: ${AWG_PORT}
EOF
  if [[ -n "${CLIENT_UUID:-}" ]]; then
    echo "Reality UUID: ${CLIENT_UUID}" >> "$CREDS_FILE"
    if [[ "${VLESS_MODE}" == "reality" ]]; then
      echo "Public Key: ${REALITY_PUBLIC}" >> "$CREDS_FILE"
      echo "Short IDs: ${SHORT_ID_1}, ${SHORT_ID_2}" >> "$CREDS_FILE"
    else
      echo "VLESS Link: vless://${CLIENT_UUID}@${REALITY_DOMAIN}:443?type=tcp&security=tls&sni=${REALITY_DOMAIN}&fp=firefox&flow=xtls-rprx-vision#${REALITY_REMARK}" >> "$CREDS_FILE"
    fi
  fi
  if [[ -n "${HY2_AUTH:-}" ]]; then
    echo "Hy2 Tag: ${HY2_TAG}" >> "$CREDS_FILE"
    echo "Hy2 Client Email: ${HY2_EMAIL}" >> "$CREDS_FILE"
    echo "Hy2 Auth: ${HY2_AUTH}" >> "$CREDS_FILE"
    echo "Hy2 Link: hysteria2://${HY2_AUTH}@${REALITY_DOMAIN}:443/?sni=${REALITY_DOMAIN}&insecure=0#Hy2-443" >> "$CREDS_FILE"
  fi
  chmod 600 "$CREDS_FILE"
  echo "Креды сохранены в: ${CREDS_FILE}"
  echo

  echo "ЧТО НУЖНО СДЕЛАТЬ РУКАМИ В ПАНЕЛИ (1 раз):"
  echo "  1. Открой https://${DOMAIN}${PANEL_PATH}"
  echo "  2. Войди в Inbounds -> '${REALITY_REMARK}' -> вкладка 'Основное'"
  echo "  3. Найди 'Стратегия адреса для ссылок' -> выбери 'Пользовательская'"
  echo "  4. Впиши адрес: ${REALITY_DOMAIN}"
  echo "  5. Сохрани (Save)"
  echo "  6. AmneziaWG: страница AmneziaWG -> Enable -> порт ${AWG_PORT} (udp) -> Save"
  echo "     (443/udp занят Hysteria 2, AWG живёт на своём порте)"
  echo "  7. Если планируешь Telegram WEB proxy (tproxy):"
  echo "     в форме инбаунда включи 'externalTLS', иначе Caddy/mtproxy"
  echo "     попытаются занять порт 443 и конфликтуют с nginx."
  echo "  8. НЕ создавай инбаунд 'Cover site' (новое в lucx-ui .215+):"
  echo "     он жёстко занимает :80 и :443 на хосте — конфликт с nginx"
  echo "     (webroot certbot на 80, SNI-роутер на 443). Сам разработчик"
  echo "     помечает его как несовместимый с REALITY/AWG — твоим стеком."
  echo "  9. НЕ нажимай 'Apply' на странице Masking / 'SNI gateway'"
  echo "     (новое в lucx-ui v3.8.5-lucx.245+): она поднимает СВОЙ"
  echo "     bundled SNI-шлюз (nginx в .245, Caddy L4 в .246+) на"
  echo "     публичном :443 и перехватывает роутинг, ломая нашу схему"
  echo "     (decoy-сайты, location подписок, certbot webroot)."
  echo "     Этот сервер уже имеет SNI-роутер от скрипта — gateway"
  echo "     не нужен."
  echo
  echo " ПОЧЕМУ ШАГ 3-4 ВАЖЕН:"
  echo "   Это отдельная настройка от подписок (влияет на прямую vless-ссылку"
  echo "   конкретного клиента). Точное имя колонки в БД не подтверждено,"
  echo "   поэтому я не трогаю её через SQL — только через UI."
  echo "   Подписки (subURI/subClashURI/subAwgURI) уже настроены автоматически."
  echo
  echo " ПРИ СМЕНЕ IP У ПРОВАЙДЕРА (блокировка и т.п.):"
  echo "   1. Обнови A-записи обоих доменов на новый IP"
  echo "   2. sudo bash $0 rebind-ip — поправит nginx stream-роутер"
  echo "   Больше на сервере ничего трогать не нужно."
  echo "============================================"

  INSTALL_SUCCESS=1

  # v0.3.1: deploy-hook перезапускает и x-ui: xray читает сертификаты
  # при старте, без рестарта hy2 отдал бы протухший серт через ~90 дней.
  # v0.3.7: '|| true' после grep -v — он ПОСЛЕДНИЙ элемент внутреннего
  # пайпа, его провал на пустом crontab НЕ подавляется (детали в changelog
  # v0.3.7 п.1): без этого install на свежем сервере падал с exit 1 на этой
  # строке ПОСЛЕ всего финального вывода, а строка renew в cron не попадала
  # (и при повторном запуске стиралась).
  ( crontab -l 2>/dev/null | grep -v 'certbot renew' || true ; \
    echo "0 0 * * * certbot renew --quiet --deploy-hook 'systemctl reload nginx && systemctl restart x-ui'" ) | crontab -


  rm -rf "$REVIEW_DIR"
  echo "[cleanup] Временные файлы удалены."
  # v0.4.1: маркер версии управления — пишется только при полном успехе install
  echo "$VERSION" > /root/.lucx-script-version
}

# ================== РЕЖИМ: HEALTHCHECK ==================

cmd_healthcheck() {
  if [[ $EUID -ne 0 ]]; then
    echo "Запусти от root: sudo bash $0 healthcheck"
    exit 1
  fi

  pass=0
  fail=0

  read_domains
  if [[ -z "${DOMAIN:-}" || -z "${REALITY_DOMAIN:-}" ]]; then
    echo "ОШИБКА: не удалось определить домены."
    exit 1
  fi

  # Читаем динамические параметры установки (для healthcheck на уже развёрнутых серверах)
  REALITY_REMARK_HC=""
  AWG_PATH_HC=""
  if [[ -f "$CREDS_FILE" ]]; then
    REALITY_REMARK_HC=$(grep -m1 '^Reality Remark:' "$CREDS_FILE" | sed 's/Reality Remark: //' || true)
    AWG_PATH_HC=$(grep -m1 '^AWG Path:' "$CREDS_FILE" | sed 's/AWG Path: //' || true)
  fi
  REALITY_REMARK_HC="${REALITY_REMARK_HC:-reality-auto}"

  # v0.3.9: режим vless на 443 — из БД (security инбаунда 127.0.0.1:443).
  # Управляет трактовкой decoy №2 ([6]) и подписью режима ([7]).
  VLESS_SEC=""
  if [[ -f "$XUIDB" ]]; then
    VLESS_SEC=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'\$.security') FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1' LIMIT 1;" 2>/dev/null || true)
    case "$VLESS_SEC" in
      tls|reality) : ;;
      *) VLESS_SEC="" ;;
    esac
  fi

  SERVER_IP=$(get_server_ip)
  # v0.4.1: маркер версии управления (пишут install/add-vls/add-reality)
  SCRIPT_MARKER="/root/.lucx-script-version"
  MARKER_INSTALLED=$(head -c 64 "$SCRIPT_MARKER" 2>/dev/null | tr -d '[:space:]' || true)
  echo "Версия скрипта: ${VERSION}"
  echo "Версия управления (маркер = версия скрипта при install/add-vls/add-reality): ${MARKER_INSTALLED:-<нет — установка до v0.4.1>}"
  # v0.4.7: INFO о новой версии скрипта (тихо без сети; не влияет на итог hc).
  # ВАЖНО: `|| true` обязателен — под set -e -o pipefail отсутствие сети/404
  # приватного репо убивало весь healthcheck (поймано в тесте на полигоне)
  # v0.4.7-fix (ревью Клоуда): единый источник с upgrade — raw main, а не releases/latest
  hc_latest_ver=$(timeout 8 curl -fsSL "https://raw.githubusercontent.com/Shepard86rus/3x-ui-dual-domain/main/3x-ui-dual-domain.sh" 2>/dev/null | grep -m1 '^VERSION=' | cut -d'"' -f2 || true)
  if [[ -n "$hc_latest_ver" && "$hc_latest_ver" != "$VERSION" ]] && [[ "$(printf '%s\n%s\n' "$VERSION" "$hc_latest_ver" | sort -V | head -n1)" == "$VERSION" ]]; then
    echo "INFO: доступна новая версия скрипта v${hc_latest_ver} (установлена v${VERSION}) — обновление: bash $0 upgrade"
  fi
  echo "Публичный IP сервера: ${SERVER_IP:-не определён}"
  echo

  echo "=== [1] Сервисы ==="
  systemctl is-active --quiet x-ui && check "x-ui запущен" ok || check "x-ui НЕ запущен" fail
  systemctl is-active --quiet nginx && check "nginx запущен" ok || check "nginx НЕ запущен" fail

  if systemctl is-active --quiet x-ui; then
    # v0.2.7: фильтруем известный benign-паттерн lucx-ui — гонку при
    # загрузке «ensure xray routing ... tun2». Панель прописывает маршрут
    # в table 1002 ДО старта xray-ядра, а tun2 создаёт именно xray, поэтому
    # на КАЖДОМ ребуте в логе одноразовая WARNING "Device for nexthop is
    # not up" (подтверждено на prod-node-1 18 сен 2026: x-ui 3.8.5-lucx.244,
    # порядок в логе детерминирован, маршрут восстанавливается ensure-циклом
    # панели — `ip route show table 1002` после загрузки заполнена).
    # Функционал не теряется, self-heal есть, ругаться на каждый boot нечего.
    # Настоящий фикс — на стороне lucx (ensure после старта core).
    recent_errors=$(journalctl -u x-ui --no-pager -n 5 2>/dev/null \
      | grep -iE 'error|fatal|panic' \
      | grep -viF 'ensure xray routing' \
      | grep -viF 'Device for nexthop is not up' \
      | grep -viF 'sysctl -qw net.ipv4.conf.tun2.rp_filter' \
      | grep -viF 'cannot stat /proc/sys/net/ipv4/conf/tun2' \
      | wc -l || true)
    # v0.2.9: считаем известные строки отдельно, чтобы сообщение не врало
    # про "отфильтрована" когда гонки в этот раз не было.
    tun2_race=$(journalctl -u x-ui --no-pager -n 5 2>/dev/null \
      | grep -iE 'error|fatal|panic' \
      | grep -iF 'tun2' \
      | wc -l || true)
    if [[ "$recent_errors" -gt 0 ]]; then
      check "x-ui логи: есть ошибки (journalctl -u x-ui -n 5)" warn
    else
      if [[ "$tun2_race" -gt 0 ]]; then
        check "x-ui логи: ошибок нет, отфильтрована гонка tun2 (${tun2_race} строк)" ok
      else
        check "x-ui логи: ошибок не обнаружено" ok
      fi
    fi
  fi

  if command -v fail2ban-client >/dev/null 2>&1; then
    systemctl is-active --quiet fail2ban && check "fail2ban запущен" ok || check "fail2ban не запущен" warn
  fi
  echo

  echo "=== [2] Порты ==="
  # Проверяем не только "порт занят", а "порт занят ТЕМ, кем должен":
  # PID из ss -> /proc/PID/cmdline (полный путь к бинарнику, не usечённое
  # /proc/PID/comm, которое обрезает имена длиннее 15 символов и могло бы
  # дать ложный OK/FAIL на угаданном имени процесса).
  get_listener_pid() {
    # $1 = grep -E паттерн адреса (например "127\.0\.0\.1:443\b")
    # || true ОБЯЗАТЕЛЕН: если порт никто не слушает (реальная авария —
    # именно тогда healthcheck нужнее всего), grep -oP ничего не находит,
    # pipefail гасит пайп и set -e убивает скрипт до вывода FAIL.
    # Найдено ревью №3: та же болезнь, что и у UDP443_PID.
    ss -tlnp 2>/dev/null | grep -E "$1" | grep -oP 'pid=\K[0-9]+' | head -n1 || true
  }
  listener_cmdline_has() {
    # $1 = pid, $2 = искомая подстрока в /proc/PID/cmdline
    [[ -n "$1" && -r "/proc/$1/cmdline" ]] || return 1
    tr '\0' ' ' < "/proc/$1/cmdline" 2>/dev/null | grep -qi "$2"
  }

  if [[ -n "${SERVER_IP:-}" ]]; then
    # v0.3.3: с этой версии install генерирует "listen 443;" (wildcard),
    # а не "listen ${SERVER_IP}:443;" (см. changelog v0.3.3) — сервера,
    # установленные ДО этой версии, по-прежнему слушают явный IP. Паттерн
    # ловит оба случая, тем же приёмом, что уже применялся для порта 80
    # (см. PUBLIC80_PID ниже).
    NGINX443_PID=$(get_listener_pid "(${SERVER_IP}|0\.0\.0\.0):443\b")
    # v0.2.5 / v0.3.0: lucx-ui v3.8.5-lucx.245+ умеет «SNI gateway /
    # Masking» со СВОИМ bundled sidecar'ом. В .245 это nginx
    # (bin/nginx-linux-*), в .246+ — Caddy L4 (bin/caddy-layer4-linux-*).
    # Имя процесса у bundled-nginx тоже «nginx» — по имени не отличить
    # от системного. Отличаем по ПУТИ бинарника в /proc/PID/cmdline.
    # Если Masking применили — sidecar перехватил публичный 443, наша
    # схема (decoy, подписки, webroot) больше не обслуживается: WARN.
    if [[ -n "$NGINX443_PID" ]] && listener_cmdline_has "$NGINX443_PID" "/usr/local/x-ui/bin/nginx"; then
      check "На 443 слушает BUNDLED-nginx lucx-ui (Masking/SNI gateway применён) — конфликт со схемой скрипта" warn
    elif [[ -n "$NGINX443_PID" ]] && listener_cmdline_has "$NGINX443_PID" "caddy-layer4"; then
      check "На 443 слушает BUNDLED-Caddy-L4 lucx-ui (Masking/SNI gateway применён, .246+) — конфликт со схемой скрипта" warn
    elif [[ -n "$NGINX443_PID" ]] && listener_cmdline_has "$NGINX443_PID" "nginx"; then
      check "nginx слушает 443 (подтверждено, pid ${NGINX443_PID})" ok
    elif [[ -n "$NGINX443_PID" ]]; then
      NGINX443_CMD=$(tr '\0' ' ' < "/proc/${NGINX443_PID}/cmdline" 2>/dev/null | head -c 80)
      check "На 443 слушает НЕ nginx (pid ${NGINX443_PID}: ${NGINX443_CMD})" fail
    else
      # v0.3.3: раньше здесь была отдельная ветка "ss ... 0.0.0.0:443 .*
      # nginx -> fail (конфликт с xray)" — она компенсировала то, что
      # NGINX443_PID выше искал ТОЛЬКО явный ${SERVER_IP}:443 и потому не
      # находил nginx на wildcard-бинде вообще. Теперь паттерн сам покрывает
      # wildcard, так что nginx-на-wildcard находится и подтверждается ВЫШЕ
      # (предыдущий elif) как ok — эта ветка была бы недостижима, убрана.
      check "nginx не найден на порту 443" fail
    fi
  else
    check "Пропущено: IP не определён" warn
  fi

  REALITY443_PID=$(get_listener_pid "127\.0\.0\.1:443\b")
  if [[ -n "$REALITY443_PID" ]] && listener_cmdline_has "$REALITY443_PID" "xray"; then
    check "Процесс слушает 127.0.0.1:443 (подтверждено xray, pid ${REALITY443_PID})" ok
  elif [[ -n "$REALITY443_PID" ]]; then
    REALITY443_CMD=$(tr '\0' ' ' < "/proc/${REALITY443_PID}/cmdline" 2>/dev/null | head -c 80)
    check "На 127.0.0.1:443 слушает НЕ xray (pid ${REALITY443_PID}: ${REALITY443_CMD})" fail
  else
    check "Никто не слушает 127.0.0.1:443 — Reality не поднят" fail
  fi

  # v0.3.1: порт AWG читается из БД (awg-инбаунд лежит в той же таблице
  # inbounds), вместо хардкода 443 — AWG переехал на отдельный порт (hy2
  # занял 443/udp).
  AWG_PORT_HC=$(sqlite3 "$XUIDB" "SELECT port FROM inbounds WHERE protocol='awg' AND enable=1 LIMIT 1;" 2>/dev/null || true)
  if [[ -n "$AWG_PORT_HC" ]] && command -v awg >/dev/null 2>&1 && \
     awg show 2>/dev/null | grep -qE "^  listening port: ${AWG_PORT_HC}$"; then
    check "AWG слушает UDP/${AWG_PORT_HC}" ok
  elif [[ -z "$AWG_PORT_HC" ]]; then
    check "AWG-инбаунд в БД не найден (включается вручную в панели — шаг 6 install)" warn
  else
    check "AWG не слушает UDP/${AWG_PORT_HC:-?} (инбаунд в БД есть, интерфейс молчит)" warn
  fi

  # v0.3.1: UDP/443 — владелец верифицируется по PID/cmdline (как TCP).
  # hy2 живёт внутри xray; standalone-hysteria или чужой процесс = FAIL.
  HY2_IN_DB=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE protocol='hysteria' AND port=443 AND enable=1;" 2>/dev/null || echo 0)
  # || true ОБЯЗАТЕЛЕН: на серверах до v0.3.1 UDP/443 держит AWG ядром —
  # в ss нет pid=, grep -oP ничего не находит и pipefail убивает скрипт
  # под set -e (поймано на первом прод-прогоне, prod-node-2).
  UDP443_PID=$(ss -ulnp 2>/dev/null | grep -E '(\*|0\.0\.0\.0):443\b' | grep -oP 'pid=\K[0-9]+' | head -n1 || true)
  if [[ "$HY2_IN_DB" -gt 0 ]]; then
    if [[ -n "$UDP443_PID" ]] && listener_cmdline_has "$UDP443_PID" "xray"; then
      check "UDP/443 слушает xray (hy2, pid ${UDP443_PID})" ok
    elif [[ -n "$UDP443_PID" ]]; then
      U443_CMD=$(tr '\0' ' ' < "/proc/${UDP443_PID}/cmdline" 2>/dev/null | head -c 80 || true)
      check "На UDP/443 слушает НЕ xray (pid ${UDP443_PID}: ${U443_CMD}) — hy2 не работает" fail
    else
      check "UDP/443 никто не слушает, хотя hy2-инбаунд есть в БД" fail
    fi
  else
    if [[ -n "$UDP443_PID" ]]; then
      if listener_cmdline_has "$UDP443_PID" "hysteria"; then
        check "На UDP/443 — standalone hysteria, а не xray-hy2 схемы скрипта" warn
      else
        U443_CMD=$(tr '\0' ' ' < "/proc/${UDP443_PID}/cmdline" 2>/dev/null | head -c 80 || true)
        check "На UDP/443 слушает неожиданный процесс (pid ${UDP443_PID}: ${U443_CMD}), hy2 не настроен" fail
      fi
    else
      check "UDP/443 свободен, hy2 не настроен (ожидаемо для серверов до v0.3.1)" ok
    fi
  fi

  # Публичный :80 — независимо от SQL-проверки Cover site в [7] (та смотрит
  # только в таблицу inbounds и не увидит sidecar/процесс вне неё). Тут
  # проверяем по факту занятого порта и владельца, а не по записи в БД.
  PUBLIC80_PID=""
  if [[ -n "${SERVER_IP:-}" ]]; then
    PUBLIC80_PID=$(get_listener_pid "(${SERVER_IP}|0\.0\.0\.0):80\b")
  else
    PUBLIC80_PID=$(get_listener_pid "0\.0\.0\.0:80\b")
  fi
  if [[ -n "$PUBLIC80_PID" ]] && listener_cmdline_has "$PUBLIC80_PID" "nginx"; then
    check "Публичный :80 подтверждён как nginx (pid ${PUBLIC80_PID})" ok
  elif [[ -n "$PUBLIC80_PID" ]]; then
    PUBLIC80_CMD=$(tr '\0' ' ' < "/proc/${PUBLIC80_PID}/cmdline" 2>/dev/null | head -c 80)
    check "На публичном :80 слушает НЕ nginx (pid ${PUBLIC80_PID}: ${PUBLIC80_CMD}) — возможно Cover site" fail
  else
    check "Публичный :80 не прослушивается ни одним процессом" warn
  fi

  # Порт панели читаем из БД (рандомный 20k-60k, не 8xxx)
  PANEL_PORT_HC=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='webPort' LIMIT 1;" 2>/dev/null || true)
  if [[ -n "$PANEL_PORT_HC" ]] && ss -tlnp 2>/dev/null | grep -qE "127\.0\.0\.1:${PANEL_PORT_HC}\b"; then
    check "Панель слушает на loopback (порт ${PANEL_PORT_HC})" ok
  else
    check "Панель НЕ слушает на loopback" warn
  fi
  echo

  echo "=== [3] ufw ==="
  if command -v ufw >/dev/null 2>&1; then
    # v0.3.7: добавлены 80/tcp (webroot certbot) и порт AWG; паттерны
    # заякорены на начало строки — без якоря «443/tcp» матчил и «8443/tcp»
    # (детектор матчил не только то, что проверял).
    ufw status 2>/dev/null | grep -qE "^443/tcp.*ALLOW" && check "ufw: 443/tcp разрешён" ok || check "ufw: 443/tcp НЕ разрешён" fail
    ufw status 2>/dev/null | grep -qE "^443/udp.*ALLOW" && check "ufw: 443/udp разрешён" ok || check "ufw: 443/udp НЕ разрешён" fail
    ufw status 2>/dev/null | grep -qE "^80/tcp.*ALLOW" && check "ufw: 80/tcp разрешён (webroot certbot)" ok || check "ufw: 80/tcp НЕ разрешён — продление сертов через webroot упадёт" fail
    if [[ -n "$AWG_PORT_HC" ]]; then
      ufw status 2>/dev/null | grep -qE "^${AWG_PORT_HC}/udp.*ALLOW" && check "ufw: ${AWG_PORT_HC}/udp разрешён (AWG)" ok || check "ufw: ${AWG_PORT_HC}/udp (AWG) НЕ разрешён" fail
    fi
  else
    check "ufw не установлен" warn
  fi
  echo

  echo "=== [4] nginx конфигурация ==="
  if nginx -t >/dev/null 2>&1; then
    check "nginx -t проходит без ошибок" ok
  else
    check "nginx -t выдаёт ошибку" fail
    nginx -t 2>&1 | sed 's/^/       /'
  fi

  STREAM_CONF="/etc/nginx/stream-sni-router.conf"
  if [[ -f "$STREAM_CONF" ]]; then
    if grep -qE "server 127\.0\.0\.1:[0-9]+;" "$STREAM_CONF"; then
      # || true по нулевому исключению: внешний grep -qE теоретически
      # гарантирует совпадение, но "теоретически" — не защита (см. историю
      # pipefail-багов этого релиза). Пустой порт корректно ловится ниже.
      reality_port=$(awk '/upstream reality_backend/,/}/' "$STREAM_CONF" | grep -oP "server 127\.0\.0\.1:\K[0-9]+" | head -n1 || true)
      if [[ "$reality_port" == "443" ]]; then
        check "stream: reality_backend -> 127.0.0.1:443" ok
      else
        check "stream: reality_backend -> 127.0.0.1:${reality_port} (не 443!)" warn
      fi
    else
      check "stream: reality_backend НЕ на loopback" fail
    fi
    # v0.3.3: install теперь генерирует "listen 443;" (wildcard) вместо
    # "listen ${SERVER_IP}:443;" — переживает смену IP у провайдера без
    # правки конфига (см. changelog v0.3.3). Сервера, установленные ДО
    # этой версии, всё ещё на старой явной форме — она пока штатна, но
    # требует ручной правки при смене IP; если же строка не совпадает НИ
    # с wildcard, НИ с текущим определённым IP — вероятно IP сменился у
    # провайдера, а конфиг не обновили (сценарий из ветки "заблокировали
    # IP, сервер жив").
    if grep -qE "^\s*listen 443;" "$STREAM_CONF"; then
      check "stream: wildcard-форма 'listen 443;' (v0.3.3–v0.3.4, ОТОЗВАНА в v0.3.5 — регресс, см. changelog) — Reality может быть мёртв; исправь: bash $0 rebind-ip" warn
    elif [[ -z "${SERVER_IP:-}" ]]; then
      check "stream: публичный IP не определён — legacy-форму сверить нельзя, пропускаю" warn
    elif grep -qE "^\s*listen ${SERVER_IP}:443;" "$STREAM_CONF"; then
      check "stream: слушает явный IP ${SERVER_IP} (штатная форма v0.3.5+, при смене IP: bash $0 rebind-ip)" ok
    else
      check "stream: listen-директива не совпадает ни с wildcard, ни с текущим публичным IP — похоже, IP сменился у провайдера, а конфиг не обновлён" warn
    fi
  else
    check "stream-sni-router.conf не найден" fail
  fi

  # Проверка stream -> nginx: proxy_protocol должен быть включён с обеих
  # сторон, иначе конфиг выглядит нормально, но реальный IP клиентов
  # панели/подписок тихо остаётся 127.0.0.1 (найдено и починено вживую
  # 27-28 авг 2026 на всех трёх продакшн-серверах).
  if grep -qF "proxy_protocol on;" "$STREAM_CONF" 2>/dev/null; then
    check "stream: proxy_protocol на backend'ы включён" ok
  else
    check "stream: proxy_protocol НЕ включён (IP клиентов будут 127.0.0.1)" fail
  fi

  PANEL_CONF="/etc/nginx/sites-available/${DOMAIN}.conf"

  if [[ -f "$PANEL_CONF" ]] && grep -qF "listen 127.0.0.1:8443 ssl proxy_protocol;" "$PANEL_CONF" 2>/dev/null; then
    if grep -qF "set_real_ip_from 127.0.0.1;" "$PANEL_CONF" && grep -qF "real_ip_header proxy_protocol;" "$PANEL_CONF"; then
      check "nginx: set_real_ip_from/real_ip_header на панели настроены" ok
    else
      check "nginx: proxy_protocol на listen ЕСТЬ, но set_real_ip_from/real_ip_header НЕТ — IP клиентов панели будут 127.0.0.1" fail
    fi
  fi

  # Проверка location для подписок
  if [[ -f "$PANEL_CONF" ]]; then
    sub_path=$(grep -m1 '^Sub Path:' "$CREDS_FILE" 2>/dev/null | sed 's/Sub Path: //' || echo '')
    if [[ -n "$sub_path" ]] && grep -qF "location ${sub_path}" "$PANEL_CONF"; then
      check "nginx: location для подписок (${sub_path}) найден" ok
    else
      check "nginx: location для подписок НЕ найден" fail
    fi
    if [[ -n "$AWG_PATH_HC" ]] && grep -qF "location ${AWG_PATH_HC}" "$PANEL_CONF"; then
      check "nginx: location AWG (${AWG_PATH_HC}) найден" ok
    else
      check "nginx: location AWG (${AWG_PATH_HC:-<неизвестно>}) НЕ найден" fail
    fi
  else
    check "nginx: конфиг панели не найден" fail
  fi
  echo

  # --- Проверка лимитов nginx (регресс v0.1.7) ---
  if [[ -f /etc/nginx/nginx.conf ]]; then
    wc=$(grep -E '^\s*worker_connections\s+' /etc/nginx/nginx.conf | grep -oP '\d+' | head -n1 || true)
    if [[ -n "$wc" && "$wc" -ge 4096 ]]; then
      check "nginx: worker_connections=${wc} (>= 4096)" ok
    else
      check "nginx: worker_connections=${wc:-<не найден>} (< 4096) — риск 'worker_connections are not enough'" fail
    fi

    if grep -qE '^\s*worker_rlimit_nofile\s+65535' /etc/nginx/nginx.conf; then
      check "nginx: worker_rlimit_nofile=65535" ok
    else
      check "nginx: worker_rlimit_nofile НЕ 65535" fail
    fi
  fi

  # Сначала измеряем РЕАЛЬНЫЙ лимит открытых файлов у работающего
  # nginx-мастера — это источник истины. Наличие override.conf важно
  # только как способ ДОБИТЬСЯ этого лимита, а не само по себе: если
  # эффективный лимит и так >= 65535 (например, за счёт system-wide
  # DefaultLimitNOFILE), override.conf не обязателен.
  NGINX_MASTER_PID=$(cat /run/nginx.pid 2>/dev/null || pgrep -o nginx || true)
  actual_nofile=""
  if [[ -n "$NGINX_MASTER_PID" && -f "/proc/${NGINX_MASTER_PID}/limits" ]]; then
    actual_nofile=$(awk '/Max open files/{print $5}' "/proc/${NGINX_MASTER_PID}/limits")
  fi

  if [[ -f /etc/systemd/system/nginx.service.d/override.conf ]] && grep -qE 'LimitNOFILE=65535' /etc/systemd/system/nginx.service.d/override.conf; then
    check "systemd: LimitNOFILE=65535 (override)" ok
  elif [[ -n "$actual_nofile" && "$actual_nofile" -ge 65535 ]]; then
    check "systemd: override.conf для nginx не найден, но реальный лимит уже ${actual_nofile} (>=65535) — не обязателен" warn
  else
    check "systemd: override.conf для nginx НЕ найден, а реальный лимит ${actual_nofile:-<неизвестно>} недостаточен" fail
  fi

  # Проверяем реальный лимит открытых файлов у работающего nginx-мастера.
  # Файл-чеки выше проверяют намерения; /proc/PID/limits — реальность.
  # "-ge" вместо "==": если эффективный лимит выше 65535 (например,
  # унаследован от system-wide DefaultLimitNOFILE), это не проблема.
  if [[ -n "$actual_nofile" ]]; then
    if [[ "$actual_nofile" -ge 65535 ]]; then
      check "nginx процесс: Max open files = ${actual_nofile} (>=65535)" ok
    else
      check "nginx процесс: Max open files = ${actual_nofile} (< 65535) — требуется restart" fail
    fi
  else
    check "nginx процесс: PID не найден, невозможно проверить /proc/PID/limits" warn
  fi

  echo "=== [5] Сертификаты ==="
  for d in "$DOMAIN" "$REALITY_DOMAIN"; do
    cert_path="/etc/letsencrypt/live/${d}/fullchain.pem"
    if [[ -f "$cert_path" ]]; then
      if openssl x509 -checkend 0 -noout -in "$cert_path" >/dev/null 2>&1; then
        exp=$(openssl x509 -enddate -noout -in "$cert_path" | cut -d= -f2)
        check "Сертификат ${d} валиден (до: ${exp})" ok
      else
        check "Сертификат ${d} ПРОСРОЧЕН" fail
      fi
    else
      check "Сертификат для ${d} НЕ найден" fail
    fi
  done

  # v0.3.7: на серверах, установленных до этого релиза, строка certbot renew
  # могла НЕ попасть в crontab (crontab-баг, changelog v0.3.7 п.1) — серты
  # тогда истекут через ~90 дней после установки, молча.
  if crontab -l 2>/dev/null | grep -q 'certbot renew'; then
    check "cron: строка certbot renew присутствует" ok
  else
    check "cron: строки certbot renew НЕТ — серты не будут продлеваться. Добавь в crontab: 0 0 * * * certbot renew --quiet --deploy-hook 'systemctl reload nginx && systemctl restart x-ui'" fail
  fi

  # v0.3.8: сверка «диск vs отдаётся» — единственный детектор сценария
  # «дистрибутивный таймер продлил серт на диске, а nginx/xray держат старый
  # в памяти» (продление без deploy-hook): проверка [6] ходит с curl -k и
  # протухший отдающийся серт не видит. Зонд через реальный путь (--resolve
  # на публичный IP -> stream SNI-роутер -> vhost / xray-fallback decoy);
  # приём обкатан вручную на всех семи серверах флота 2026-09-29. Пустой
  # ответ (сетевой флейк, см. legacy-wan-ip) — WARN, не FAIL.
  if [[ -n "${SERVER_IP:-}" ]]; then
    for d in "$DOMAIN" "$REALITY_DOMAIN"; do
      disk_exp=$(openssl x509 -enddate -noout -in "/etc/letsencrypt/live/${d}/fullchain.pem" 2>/dev/null | cut -d= -f2)
      live_exp=$(curl -kvsI --max-time 8 "https://${d}" --resolve "${d}:443:${SERVER_IP}" -o /dev/null 2>&1 | grep -oP 'expire date:\s*\K.*' | head -n1 || true)
      if [[ -z "$disk_exp" ]]; then
        check "Сверка серта ${d}: серта нет на диске — пропуск (поймано выше)" warn
      elif [[ -z "$live_exp" ]]; then
        check "Сверка серта ${d}: не удалось прочитать отдающийся серт (443 недоступен или сетевой флейк)" warn
      elif [[ "$live_exp" == "$disk_exp" ]]; then
        check "Серт ${d}: диск = отдаётся (до: ${disk_exp})" ok
      else
        check "Серт ${d}: nginx/xray отдают СТАРЫЙ (${live_exp}), на диске (${disk_exp}) — продление без reload. Фикс: systemctl reload nginx && systemctl restart x-ui" fail
      fi
    done
  else
    check "Сверка сертов: публичный IP не определён — пропускаю" warn
  fi

  # v0.3.8: AAAA-мониторинг — тот же принцип, что префлайт [2/10], но
  # действующий всю жизнь сервера: появившаяся после установки AAAA-запись
  # уводит Let's Encrypt в IPv6 (nginx слушает только v4) и тихо ломает
  # продление. Здесь это FAIL с адресом проблемы.
  for d in "$DOMAIN" "$REALITY_DOMAIN"; do
    aaaa_hc=$(dig +short AAAA "$d" @1.1.1.1 | head -n1 || true)
    if [[ -n "$aaaa_hc" ]]; then
      check "У ${d} есть AAAA-запись (${aaaa_hc}) — LE пойдёт по IPv6, продление сертов упадёт. Убери AAAA у регистратора" fail
    else
      check "AAAA-записей у ${d} нет (схема IPv4-only)" ok
    fi
  done
  echo

  echo "=== [6] Decoy-сайты и панель ==="
  if [[ -n "${SERVER_IP:-}" ]]; then
    code1=$(curl -sk --max-time 8 -o /dev/null -w "%{http_code}" "https://${DOMAIN}" --resolve "${DOMAIN}:443:${SERVER_IP}" 2>/dev/null || echo "000")
    [[ "$code1" == "200" ]] && check "Decoy №1 (${DOMAIN}) HTTP 200" ok || check "Decoy №1 код ${code1}" fail

    code2=$(curl -sk --max-time 8 -o /dev/null -w "%{http_code}" "https://${REALITY_DOMAIN}" --resolve "${REALITY_DOMAIN}:443:${SERVER_IP}" 2>/dev/null || echo "000")
    if [[ "$code2" == "200" ]]; then
      check "Decoy №2 (${REALITY_DOMAIN}) HTTP 200" ok
    elif [[ "$code2" == "301" && "${VLESS_SEC:-}" == "tls" ]]; then
      check "Decoy №2 (${REALITY_DOMAIN}) HTTP 301 — ЦИКЛ редиректов (fallback ещё на :80, баг v0.3.9; браузер сайт не откроет). Фикс: sudo bash $0 add-vls — перенесёт фасад на :8080" fail
    elif [[ "$code2" == "000" && "${VLESS_SEC:-}" == "tls" ]]; then
      check "Decoy №2 (${REALITY_DOMAIN}) недоступен — в TLS-режиме без fallback пробы обрываются. Лечение: sudo bash $0 add-vls" fail
    else
      check "Decoy №2 код ${code2}" fail
    fi

    panel_path=$(grep -m1 '^URL:' "$CREDS_FILE" 2>/dev/null | sed -E 's|^URL: ||; s|https://[^/]+||' || echo "/panel/")
    panel_code=$(curl -sk --max-time 8 -o /dev/null -w "%{http_code}" "https://${DOMAIN}${panel_path}" --resolve "${DOMAIN}:443:${SERVER_IP}" 2>/dev/null || echo "000")
    if [[ "$panel_code" == "200" ]]; then
      check "Панель доступна через nginx" ok
    else
      check "Панель вернула код ${panel_code}" warn
    fi
  else
    check "Пропущено: IP не определён" warn
  fi
  echo

  echo "=== [7] Reality inbound в базе ==="
  if [[ -f "$XUIDB" ]]; then
    backup_count=$(ls -1 "${XUIDB}.backup."* 2>/dev/null | wc -l)
    [[ "$backup_count" -gt 0 ]] && check "Бэкап(ы) БД: ${backup_count} шт." ok || check "Бэкапов БД не найдено" warn

    cnt=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE protocol='vless';" 2>/dev/null || echo 0)
    if [[ "$cnt" -gt 0 ]]; then
      check "В базе $cnt vless/reality inbound(ов)" ok
      # v0.2.6: раньше проверялся ТОЛЬКО ПОСЛЕДНИЙ vless-инбаунд
      # (ORDER BY id DESC LIMIT 1) с требованием порт==443. При любом
      # дополнительном экспериментальном инбаунде (ловилось вживую на
      # prod-node-1 18 сен 2026: xhttp-тест на 127.0.0.1:8445) это давало
      # ложный FAIL «Порт инбаунда (8445) НЕ 443», хотя Reality на 443
      # был на месте. Теперь: требуем НАЛИЧИЕ ХОТЯ БЫ ОДНОГО vless-инбаунда
      # на 127.0.0.1:443 (это наш Reality), остальные перечисляем
      # информационно и не падаем на них.
      reality443=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE protocol='vless' AND port=443 AND listen='127.0.0.1';" 2>/dev/null || echo 0)
      if [[ "$reality443" -gt 0 ]]; then
        check "Reality-инбаунд на 127.0.0.1:443 присутствует" ok
      else
        check "НЕТ vless-инбаунда на 127.0.0.1:443 — Reality не на месте" fail
      fi
      # v0.3.9: подпись режима 443
      if [[ -n "$VLESS_SEC" ]]; then
        check "Режим 443: ${VLESS_SEC}" ok
      else
        check "Режим 443: не определён (security инбаунда не tls/reality)" warn
      fi
      # Все vless-инбаунды — информационная строка для диагностики
      sqlite3 "$XUIDB" "SELECT '       -> remark='''||remark||''', listen='''||COALESCE(listen,'')||''', port='||port FROM inbounds WHERE protocol='vless' ORDER BY id;" 2>/dev/null || true
      # Доп. vless-инбаунды НЕ на 443 — не FAIL, а WARN: осознанные
      # эксперименты пользователя валидны. Но если такой инбаунд слушает
      # НЕ loopback — это открытый порт мимо nginx SNI-роутера, и тут
      # уже FAIL.
      extra=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE protocol='vless' AND port!=443;" 2>/dev/null || echo 0)
      if [[ "$extra" -gt 0 ]]; then
        extra_list=$(sqlite3 "$XUIDB" "SELECT remark||':'||COALESCE(listen,'<все>')||':'||port FROM inbounds WHERE protocol='vless' AND port!=443;" 2>/dev/null | paste -sd', ' - || true)
        extra_open=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE protocol='vless' AND port!=443 AND (listen IS NULL OR listen='' OR listen NOT LIKE '127.%');" 2>/dev/null || echo 0)
        if [[ "$extra_open" -gt 0 ]]; then
          check "Доп. vless-инбаунды НЕ на loopback (${extra_list}) — риск открытого порта мимо nginx" fail
        else
          check "Доп. vless-инбаунд(ы) на loopback (${extra_list}) — эксперимент, схеме не мешает" warn
        fi
      fi
    else
      check "vless/reality inbound не найден" fail
    fi

    # Cover site (lucx-ui v3.7.0-lucx.215+) жёстко занимает :80 и :443 на
    # хосте — конфликт с nginx (webroot certbot на 80, SNI-роутер на 443) —
    # и явно несовместим с REALITY/AWG (наш стек). Точное значение поля
    # protocol для Cover site в схеме БД не подтверждено, поэтому не гадаю
    # по имени — проверяю напрямую по занятым портам, независимо от того,
    # как называется protocol у инбаунда.
    port80_cnt=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE port=80;" 2>/dev/null || echo 0)
    if [[ "$port80_cnt" -gt 0 ]]; then
      check "В базе инбаунд(ы) на порту 80 (${port80_cnt} шт.) — конфликт с certbot webroot, вероятно Cover site" fail
    else
      check "Инбаундов на порту 80 нет" ok
    fi

    # AWG (protocol='awg') работает по UDP — nginx ssl_preread/stream
    # проксирует только TCP, поэтому AWG физически не может идти через
    # SNI-роутер и легитимно слушает публичный интерфейс без привязки к
    # loopback. В схеме v0.3.1+ AWG живёт на отдельном UDP-порте (52911),
    # НО whitelist сохранён и для легаси-серверов до v0.3.1, где AWG ещё
    # на 443/udp. Подтверждено дампом с prod-node-3 (protocol='awg', listen='').
    # Исключаем его и vless (тот и так ожидается на loopback) из проверки,
    # чтобы ловить только неожиданные протоколы на публичном 443.
    non_loopback_443=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE port=443 AND protocol NOT IN ('vless','awg','hysteria') AND (listen IS NULL OR listen='' OR listen!='127.0.0.1');" 2>/dev/null || echo 0)
    if [[ "$non_loopback_443" -gt 0 ]]; then
      offenders=$(sqlite3 "$XUIDB" "SELECT remark||' ('||protocol||')' FROM inbounds WHERE port=443 AND protocol NOT IN ('vless','awg','hysteria') AND (listen IS NULL OR listen='' OR listen!='127.0.0.1');" 2>/dev/null || true)
      check "Инбаунд(ы) на порту 443 НЕ на loopback, протокол не vless/awg/hysteria (${non_loopback_443} шт.) — конфликт с nginx SNI-роутером, вероятно Cover site" fail
      [[ -n "$offenders" ]] && echo "       -> ${offenders}"
    else
      check "Все инбаунды на 443 (кроме awg/hysteria по UDP) сидят на loopback" ok
    fi

    # --- Hysteria 2 диагностика (v0.3.1) ---
    hy2_cnt=$(sqlite3 "$XUIDB" "SELECT COUNT(*) FROM inbounds WHERE protocol='hysteria';" 2>/dev/null || echo 0)
    if [[ "$hy2_cnt" -gt 0 ]]; then
      hy2_port=$(sqlite3 "$XUIDB" "SELECT port FROM inbounds WHERE protocol='hysteria' AND enable=1 LIMIT 1;" 2>/dev/null || true)
      if [[ "$hy2_port" == "443" ]]; then
        check "Hy2-инбаунд на UDP/443 присутствует" ok
      else
        check "Hy2-инбаунд на UDP/${hy2_port:-?} (канон схемы — 443)" warn
      fi
      hy2_ver=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'$.hysteriaSettings.version') FROM inbounds WHERE protocol='hysteria' LIMIT 1;" 2>/dev/null || true)
      if [[ "$hy2_ver" == "2" ]]; then
        check "Hy2: версия 2" ok
      else
        check "Hy2: версия '${hy2_ver:-?}' вместо 2 (hy1 устарел и слабее по маскировке)" fail
      fi
      hy2_ms_type=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'$.hysteriaSettings.masquerade.type') FROM inbounds WHERE protocol='hysteria' LIMIT 1;" 2>/dev/null || true)
      hy2_ms_url=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'$.hysteriaSettings.masquerade.url') FROM inbounds WHERE protocol='hysteria' LIMIT 1;" 2>/dev/null || true)
      if [[ "$hy2_ms_type" == "proxy" && "$hy2_ms_url" == *"${REALITY_DOMAIN}"* ]]; then
        check "Hy2: masquerade -> ${hy2_ms_url} (decoy-фасад для QUIC-сканеров)" ok
      else
        check "Hy2: masquerade не на decoy (type='${hy2_ms_type:-?}', url='${hy2_ms_url:-?}')" warn
      fi
      hy2_salamander=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'$.hysteriaSettings.mask.type') FROM inbounds WHERE protocol='hysteria' LIMIT 1;" 2>/dev/null || true)
      if [[ "$hy2_salamander" == "salamander" ]]; then
        check "Hy2: Salamander ON — INFO: сигнатуры нет, но SNI не виден и masquerade-проба недостижима" warn
      else
        check "Hy2: obfs OFF — INFO: чистый QUIC/HTTP/3 к ${REALITY_DOMAIN} (дефолт v0.3.1)" warn
      fi
      hy2_clients=$(sqlite3 "$XUIDB" "SELECT json_array_length(json_extract(settings,'$.clients')) FROM inbounds WHERE protocol='hysteria' LIMIT 1;" 2>/dev/null || echo 0)
      if [[ "$hy2_clients" -gt 0 ]]; then
        check "Hy2: клиент(ы) настроены (${hy2_clients} шт.)" ok
      else
        check "Hy2: клиентов нет — подключаться некому" fail
      fi
      hy2_sni=$(sqlite3 "$XUIDB" "SELECT json_extract(stream_settings,'$.tlsSettings.serverName') FROM inbounds WHERE protocol='hysteria' LIMIT 1;" 2>/dev/null || true)
      if [[ "$hy2_sni" == "$REALITY_DOMAIN" ]]; then
        check "Hy2: SNI/сертификат = ${REALITY_DOMAIN} (согласовано с decoy)" ok
      else
        check "Hy2: tlsSettings.serverName '${hy2_sni:-?}' != '${REALITY_DOMAIN}' — рассинхрон с decoy" fail
      fi
    else
      check "Hy2-инбаунд в БД не найден (схема v0.3.1 не применена)" warn
    fi
  else
    check "x-ui.db не найден" fail
  fi
  echo

  echo "=== [8] Настройки подписок ==="
  if [[ -f "$XUIDB" ]]; then
    sub_uri=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='subURI' LIMIT 1;" 2>/dev/null || true)
    sub_port=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='subPort' LIMIT 1;" 2>/dev/null || true)
    sub_awg=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='subAwgEnable' LIMIT 1;" 2>/dev/null || true)
    sub_clash=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='subClashURI' LIMIT 1;" 2>/dev/null || true)
    if [[ -n "$sub_uri" && "$sub_uri" != *"127.0.0.1"* ]]; then
      check "subURI = ${sub_uri}" ok
    else
      check "subURI не настроен или содержит 127.0.0.1 (${sub_uri:-<пусто>})" fail
    fi
    if [[ "$sub_port" == "2096" ]]; then
      check "subPort = ${sub_port}" ok
    else
      check "subPort НЕ 2096 (${sub_port:-<пусто>})" fail
    fi
    if [[ "$sub_awg" == "true" ]]; then
      check "subAwgEnable = true" ok
    else
      check "subAwgEnable НЕ true (${sub_awg:-<пусто>}) — AWG-подписки отключены" warn
    fi
    if [[ -n "$sub_clash" && "$sub_clash" != *"127.0.0.1"* ]]; then
      check "subClashURI настроен" ok
    else
      check "subClashURI не настроен (${sub_clash:-<пусто>})" warn
    fi

    # v0.3.1: живой запрос подписки — hy2-нода реально отдаётся клиентам.
    # Схема подписок lucx-ui 3.8.x: subPath в БД — ПРЕФИКС, полный URL
    # клиента = префикс + subId клиента (/sb-xxxx/<subId>). Голый префикс
    # отдаёт 404 — ловится вживую на стенде 18 сен 2026 (ложный WARN).
    if [[ "${hy2_cnt:-0}" -gt 0 && -n "$sub_uri" && "$sub_uri" != *"127.0.0.1"* ]]; then
      hy2_subid=$(sqlite3 "$XUIDB" "SELECT json_extract(settings,'$.clients[0].subId') FROM inbounds WHERE protocol='hysteria' AND enable=1 LIMIT 1;" 2>/dev/null || true)
      if [[ -n "$hy2_subid" ]]; then
        sub_decoded=$(curl -sk --max-time 10 "${sub_uri}${hy2_subid}" 2>/dev/null | base64 -d 2>/dev/null || true)
        if echo "$sub_decoded" | grep -q 'hysteria2://'; then
          check "Подписка отдаёт hy2-ноду (subId ${hy2_subid})" ok
        else
          check "Подписка НЕ отдаёт hy2-ноду (клиент выключен или генератор hy2 не поддерживается)" warn
        fi
      else
        check "Hy2: subId клиента пуст — подписка невозможна" warn
      fi
    fi
  else
    check "База данных не найден — пропускаю проверку подписок" warn
  fi
  echo

  echo "=== [9] AWG модуль ядра ==="
  lsmod 2>/dev/null | grep -q amneziawg && check "Модуль amneziawg загружен" ok || check "Модуль amneziawg НЕ загружен" warn
  command -v awg >/dev/null 2>&1 && check "awg установлен" ok || check "awg НЕ установлен" fail
  [[ -f /etc/modules-load.d/amneziawg.conf ]] && check "amneziawg.conf в modules-load.d" ok || check "amneziawg.conf НЕ найден" warn
  echo

  echo "=== [10] Файлы установки ==="
  [[ -f "$CREDS_FILE" ]] && check "Файл кредов ${CREDS_FILE}" ok || check "Файл кредов не найден" warn
  if [[ -f "$LOG_FILE" ]]; then
    check "Лог установки ${LOG_FILE}" ok
    # v0.3.7: лог содержит креды панели; на серверах, установленных до
    # v0.3.7, он остался мир-читаемым (0644) — теперь это FAIL с фиксом.
    log_mode=$(stat -c '%a' "$LOG_FILE" 2>/dev/null || true)
    if [[ -n "$log_mode" ]] && (( (8#$log_mode & 8#044) != 0 )); then
      check "Лог установки ${LOG_FILE} читается группой/другими (${log_mode}), а в нём креды панели. Фикс: chmod 600 ${LOG_FILE}" fail
    fi
  else
    check "Лог установки не найден" warn
  fi
  # v0.4.1: сверка маркера версии управления со скриптом
  marker=$(head -c 64 "$SCRIPT_MARKER" 2>/dev/null | tr -d '[:space:]' || true)
  if [[ -z "$marker" ]]; then
    if [[ -f "$CREDS_FILE" ]]; then
      check "Маркер версии отсутствует (установка до v0.4.1). Запиши фактическую: echo \"0.3.9\" > /root/.lucx-script-version" warn
    fi
  elif [[ "$marker" == "$VERSION" ]]; then
    check "Версия управления (при установке): ${marker} — совпадает со скриптом" ok
  elif [[ "$(printf '%s\n%s\n' "$marker" "$VERSION" | sort -V | head -n1)" == "$VERSION" ]]; then
    check "Версия управления: ${marker} НОВЕЕ скрипта на диске (${VERSION}) — скрипт откатывали? Проверь" warn
  else
    check "Версия управления (при установке): ${marker}; скрипт на диске новее (${VERSION}) — штатно (маркер обновляют только add-vls/add-reality, это не показатель устаревания ноды)" ok
  fi
  echo

  # ================== [11] Скан открытых (публичных) портов (v0.4.4) ==================
  # Инвентаризация ВСЕХ слушающих сокетов. Повод: кейс клиента — xhttp-инбаунд
  # на публичном порту мимо nginx; старый healthcheck проверял «порт занят ТЕМ,
  # кем должен», но не замечал посторонних слушателей. Правило: публичным (не
  # loopback) слушателем имеет право быть только белый список схемы — TCP 22/SSH, 80, 443,
  # UDP 443 (hy2) + AWG-порт из БД. Порты, открытые наружу ОСОЗНАННО (OpenFlux
  # direct и т.п.), вносятся в файлы-исключения ниже: по одному порту на строку,
  # строки с # — комментарии.
  echo "=== [11] Скан открытых портов ==="
  HC11_EXC_TCP="/root/.lucx-public-tcp-ports.txt"
  HC11_EXC_UDP="/root/.lucx-public-udp-ports.txt"
  # v0.4.6: SSH-порт(ы) в белый список — с факта, не хардкодом: install [3/10]
  # открывает в ufw именно те порты, на которых слушает sshd; healthcheck —
  # отдельный прогон, SSH_PORTS из install тут не существует. Детекция та же,
  # что в install; фоллбэк "22" — как в install при невидимом sshd.
  HC11_SSH_PORTS=$(ss -tlnp 2>/dev/null | grep 'sshd' | grep -oP ':\K[0-9]+(?= )' | sort -u || true)
  HC11_ALLOW_TCP=" 80 443 "
  if [[ -n "$HC11_SSH_PORTS" ]]; then
    for HC11_P in $HC11_SSH_PORTS; do HC11_ALLOW_TCP+="${HC11_P} "; done
  else
    HC11_ALLOW_TCP+="22 "
  fi
  HC11_ALLOW_UDP=" 443 "
  if [[ -n "${AWG_PORT_HC:-}" ]]; then HC11_ALLOW_UDP+="${AWG_PORT_HC} "; fi
  if [[ -f "$HC11_EXC_TCP" ]]; then
    while IFS= read -r HC11_LINE || [[ -n "$HC11_LINE" ]]; do
      HC11_LINE="${HC11_LINE%%#*}"
      HC11_LINE="$(tr -d '[:space:]' <<<"$HC11_LINE")"
      if [[ -n "$HC11_LINE" ]]; then HC11_ALLOW_TCP+="${HC11_LINE} "; fi
    done < "$HC11_EXC_TCP"
  fi
  if [[ -f "$HC11_EXC_UDP" ]]; then
    while IFS= read -r HC11_LINE || [[ -n "$HC11_LINE" ]]; do
      HC11_LINE="${HC11_LINE%%#*}"
      HC11_LINE="$(tr -d '[:space:]' <<<"$HC11_LINE")"
      if [[ -n "$HC11_LINE" ]]; then HC11_ALLOW_UDP+="${HC11_LINE} "; fi
    done < "$HC11_EXC_UDP"
  fi
  HC11_UFW_ALLOWS() {
    # $1 = порт, $2 = протокол; строка ufw: "<port>/<proto>  ALLOW  Anywhere"
    ufw status 2>/dev/null | grep -qE "^${1}/${2}[[:space:]]+ALLOW"
  }
  HC11_LEAKS=0
  declare -A HC11_SEEN=()
  while read -r HC11_STATE _ _ HC11_LOCAL _ HC11_REST; do
    [[ "$HC11_STATE" == "LISTEN" ]] || continue
    HC11_PORT="${HC11_LOCAL##*:}"
    [[ "$HC11_PORT" =~ ^[0-9]+$ ]] || continue
    case "$HC11_LOCAL" in
      127.*|"[::1]"*|"[::ffff:127.0.0.1]"*) continue ;;
    esac
    if [[ -n "${HC11_SEEN[TCP:${HC11_PORT}]:-}" ]]; then continue; fi
    HC11_SEEN["TCP:${HC11_PORT}"]=1
    HC11_PID=$(grep -oP 'pid=\K[0-9]+' <<<"${HC11_REST}" | head -n1 || true)
    HC11_NAME="-"
    if [[ -n "$HC11_PID" && -r "/proc/${HC11_PID}/cmdline" ]]; then
      HC11_NAME=$(tr '\0' ' ' < "/proc/${HC11_PID}/cmdline" 2>/dev/null | awk '{print $1}')
      HC11_NAME="${HC11_NAME##*/}"
      if [[ -z "$HC11_NAME" ]]; then HC11_NAME="-"; fi
    fi
    if [[ "$HC11_ALLOW_TCP" == *" ${HC11_PORT} "* ]]; then
      check "Публичный TCP/${HC11_PORT} (${HC11_NAME}) — в белом списке схемы" ok
    elif HC11_UFW_ALLOWS "$HC11_PORT" tcp; then
      check "Публичный TCP/${HC11_PORT} (${HC11_NAME}) — слушает и разрешён ufw, но НЕ из схемы; сканер видит. Если нужен осознанно: echo ${HC11_PORT} >> ${HC11_EXC_TCP}" fail
      HC11_LEAKS=$((HC11_LEAKS+1))
    else
      check "TCP/${HC11_PORT} (${HC11_NAME}) слушает, но закрыт ufw — снаружи не виден" warn
    fi
  done < <(ss -tlnp 2>/dev/null || true)
  while read -r HC11_STATE _ _ HC11_LOCAL _ HC11_REST; do
    [[ "$HC11_STATE" == "UNCONN" ]] || continue
    HC11_PORT="${HC11_LOCAL##*:}"
    [[ "$HC11_PORT" =~ ^[0-9]+$ ]] || continue
    case "$HC11_LOCAL" in
      127.*|"[::1]"*|"[::ffff:127.0.0.1]"*) continue ;;
    esac
    if [[ -n "${HC11_SEEN[UDP:${HC11_PORT}]:-}" ]]; then continue; fi
    HC11_SEEN["UDP:${HC11_PORT}"]=1
    HC11_PID=$(grep -oP 'pid=\K[0-9]+' <<<"${HC11_REST}" | head -n1 || true)
    HC11_NAME="-"
    if [[ -n "$HC11_PID" && -r "/proc/${HC11_PID}/cmdline" ]]; then
      HC11_NAME=$(tr '\0' ' ' < "/proc/${HC11_PID}/cmdline" 2>/dev/null | awk '{print $1}')
      HC11_NAME="${HC11_NAME##*/}"
      if [[ -z "$HC11_NAME" ]]; then HC11_NAME="-"; fi
    fi
    if [[ "$HC11_ALLOW_UDP" == *" ${HC11_PORT} "* ]]; then
      check "Публичный UDP/${HC11_PORT} (${HC11_NAME}) — в белом списке схемы" ok
    elif HC11_UFW_ALLOWS "$HC11_PORT" udp; then
      check "Публичный UDP/${HC11_PORT} (${HC11_NAME}) — слушает и разрешён ufw, но НЕ из схемы; сканер видит. Если нужен осознанно: echo ${HC11_PORT} >> ${HC11_EXC_UDP}" fail
      HC11_LEAKS=$((HC11_LEAKS+1))
    else
      check "UDP/${HC11_PORT} (${HC11_NAME}) слушает, но закрыт ufw — снаружи не виден" warn
    fi
  done < <(ss -ulnp 2>/dev/null || true)
  if [[ "$HC11_LEAKS" -eq 0 ]]; then
    check "Скан открытых портов: публичные слушатели только из белого списка (TCP:${HC11_ALLOW_TCP} UDP:${HC11_ALLOW_UDP})" ok
  fi
  unset HC11_SEEN

  # ================== [12] Telegram-бот управления (v0.4.8, опция) ==================
  echo "=== [12] Telegram-бот управления ==="
  if [[ ! -f "$TGBOT_DIR/.version" ]]; then
    echo "    не установлен (опция install / команда add-bot) — пропуск"
  else
    local st12 en12 tok12 cid12 v12
    st12=$(systemctl is-active tgbot 2>/dev/null || true)
    en12=$(systemctl is-enabled tgbot 2>/dev/null || true)
    if [[ "$st12" == "active" ]]; then
      check "бот: сервис active" ok
    else
      check "бот: сервис НЕ активен (${st12:-unknown}) — смотри journalctl -u tgbot" fail
    fi
    if [[ "$en12" == "enabled" ]]; then
      check "бот: автозапуск enabled" ok
    else
      check "бот: автозапуск не включён (systemctl enable tgbot)" fail
    fi
    tok12=$(grep "^TOKEN=" "$TGBOT_ENV" 2>/dev/null | head -1 | sed "s/^TOKEN='//; s/'\$//" || true)
    cid12=$(grep "^CHAT_ID=" "$TGBOT_ENV" 2>/dev/null | head -1 | sed "s/^CHAT_ID='//; s/'\$//" || true)
    if [ -n "$tok12" ]; then
      check "бот: токен вписан" ok
    else
      check "бот: токен НЕ вписан (бот молчит) — впиши TOKEN= в $TGBOT_ENV" fail
    fi
    if [ -n "$cid12" ]; then
      check "бот: whitelist настроен (CHAT_ID)" ok
    else
      check "бот: режим обучения (CHAT_ID пуст — команды не работают), /start пришлёт chat_id" warn
    fi
    local apit12 pp12 pb12 code12
    apit12=$(grep "^PANEL_API_TOKEN=" "$TGBOT_ENV" 2>/dev/null | head -1 | sed "s/^PANEL_API_TOKEN='//; s/'\$//" || true)
    if [ -z "$apit12" ]; then
      check "бот: управление клиентами выключено (PANEL_API_TOKEN пуст) — по желанию: sudo bash $0 add-bot" warn
    else
      pp12=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='webPort' LIMIT 1;" 2>/dev/null || true)
      pb12=$(sqlite3 "$XUIDB" "SELECT value FROM settings WHERE key='webBasePath' LIMIT 1;" 2>/dev/null || true)
      pb12="${pb12#/}"; pb12="${pb12%/}"; [ -n "$pb12" ] && pb12="/$pb12"
      code12=$(printf 'header = "Authorization: Bearer %s"\n' "$apit12" | curl -s -o /dev/null -w '%{http_code}' --max-time 10 -K - "http://127.0.0.1:${pp12}${pb12}/panel/api/clients/list" 2>/dev/null || true)
      if [[ "$code12" == "200" ]]; then
        check "бот: API-токен панели принят (список клиентов, HTTP 200)" ok
      else
        check "бот: API-токен панели не принят (HTTP ${code12:-нет ответа}) — создай токен scope admin и впиши PANEL_API_TOKEN=" fail
      fi
    fi
    v12=$(cat "$TGBOT_DIR/.version" 2>/dev/null || true)
    if [[ "$v12" == "$TGBOT_BODY_VERSION" ]]; then
      check "бот: тело v$v12 актуально" ok
    else
      check "бот: тело v${v12:-?} не совпадает со скриптом v$TGBOT_BODY_VERSION — обнови: sudo bash $0 add-bot (env сохранится)" warn
    fi
  fi

  # ================== [13] БД и песочница (v0.4.9) ==================
  echo "=== [13] БД и песочница ==="
  local res_db13 awg13 loc13
  res_db13=$(grep -oP "^XUI_DB_TYPE=\K.*" /etc/x-ui/install-result.env 2>/dev/null | head -1 || true)
  if [[ -z "$res_db13" ]]; then
    if [[ -f /etc/x-ui/x-ui.db ]]; then
      check "БД панели: SQLite (x-ui.db на месте; install-result.env отсутствует — старая установка)" ok
    else
      check "БД панели: не найдено ни install-result.env, ни x-ui.db" fail
    fi
  elif [[ "$res_db13" == "sqlite" ]]; then
    check "БД панели: SQLite" ok
  else
    check "БД панели: $res_db13 — скрипт поддерживает только SQLite (бэкапы/hy2-инбаунд лягут)" fail
  fi
  # v0.5.0: подвисания диска ВМ (дают «database is locked» в панели).
  # PSI full avg300 — доля времени, когда ВСЕ задачи ждали диск; WARN, не FAIL.
  if [[ -r /proc/pressure/io ]]; then
    local psi13
    psi13=$(awk '/^full/{for(i=1;i<=NF;i++) if($i ~ /^avg300=/){sub("avg300=","",$i); print $i}}' /proc/pressure/io 2>/dev/null | head -1)
    if [[ -n "$psi13" ]] && awk -v v="$psi13" -v t="$PSI_WARN_PCT" 'BEGIN{exit !(v+0>=t+0)}'; then
      check "диск: io-давление (PSI full avg300) = ${psi13}% (порог ${PSI_WARN_PCT}%) — диск ВМ подвисает; возможны «database is locked» в панели" warn
    else
      check "диск: io-давление в норме (PSI full avg300 = ${psi13:-n/a}%)" ok
    fi
  fi
  if [[ ! -f /etc/systemd/system/x-ui.service.d/10-xui-sandbox.conf ]]; then
    echo "    systemd-песочницы нет (панель < lucx.291) — ничего не требуется"
  else
    awg13=$(sqlite3 -readonly /etc/x-ui/x-ui.db "SELECT COUNT(*) FROM inbounds WHERE protocol='awg';" 2>/dev/null || echo 0)
    # v0.5.0: смотрим ФАКТ (что реально разрешено юниту), а не наличие нашего drop-in:
    # с lucx.292 /etc/amnezia в ReadWritePaths самого юнита x-ui
    loc13=""
    systemctl show x-ui -p ReadWritePaths 2>/dev/null | grep -q "/etc/amnezia" && loc13=1
    if [[ -z "$loc13" ]]; then
      grep -rqs "/etc/amnezia" /etc/systemd/system/x-ui.service /etc/systemd/system/x-ui.service.d/ 2>/dev/null && loc13=1
    fi
    if [[ "${awg13:-0}" -eq 0 ]]; then
      check "песочница: AWG-инбаундов нет — доступ к /etc/amnezia не требуется" ok
    elif [[ -n "$loc13" ]]; then
      check "песочница: юнит x-ui может писать в /etc/amnezia — AWG переживёт обновление/рестарт" ok
    else
      check "песочница: юниту x-ui запрещено писать в /etc/amnezia (панель lucx.291) — AWG ляжет при рестарте; обнови панель до lucx.292+ (x-ui update)" fail
    fi
  fi

  echo
  # ================== [14] SSH-атаки и ресурсы (v0.5.1, только справочно) ==================
  echo "=== [14] SSH-атаки и ресурсы (справочно, на итог не влияет) ==="
  if command -v journalctl >/dev/null 2>&1; then
    local ssh_1h ssh_24h ssh_ips f2b_banned f2b_total f2b_txt
    ssh_1h=$(journalctl _COMM=sshd --since "1 hour ago" --no-pager 2>/dev/null | grep -cE 'Failed password|Invalid user|authentication failure' || true)
    ssh_24h=$(journalctl _COMM=sshd --since "24 hours ago" --no-pager 2>/dev/null | grep -cE 'Failed password|Invalid user|authentication failure' || true)
    ssh_ips=$(journalctl _COMM=sshd --since "24 hours ago" --no-pager 2>/dev/null | grep -E 'Failed password|Invalid user' | grep -oE 'from [0-9a-fA-F.:]+' | sort -u | wc -l || true)
    f2b_txt="fail2ban: не активен"
    if systemctl is-active --quiet fail2ban 2>/dev/null; then
      f2b_banned=$(fail2ban-client status sshd 2>/dev/null | grep -oE 'Currently banned:[[:space:]]*[0-9]+' | grep -oE '[0-9]+$' || true)
      f2b_total=$(fail2ban-client status sshd 2>/dev/null | grep -oE 'Total banned:[[:space:]]*[0-9]+' | grep -oE '[0-9]+$' || true)
      f2b_txt="fail2ban: в бане ${f2b_banned:-?}, всего ${f2b_total:-?}"
    fi
    echo "    [INFO] SSH: попыток входа за 1ч: ${ssh_1h:-0}, за 24ч: ${ssh_24h:-0} (уникальных адресов за 24ч: ${ssh_ips:-0}); ${f2b_txt}"
  else
    echo "    [INFO] SSH: journalctl недоступен — счётчик пропущен"
  fi
  local mem_kb14 swap_kb14
  mem_kb14=$(awk '/^MemTotal:/{print $2}' /proc/meminfo 2>/dev/null || echo 0)
  swap_kb14=$(awk '/^SwapTotal:/{print $2}' /proc/meminfo 2>/dev/null || echo 0)
  if [[ "${mem_kb14:-0}" -le 1300000 && "${swap_kb14:-0}" -eq 0 ]]; then
    echo "    [INFO] ОЗУ ≈ 1 ГБ и swap нет — запас на пики мал. Опционально: sudo bash $0 add-swap (не включай на ВМ с WARN про io-давление выше)"
  fi

  echo
  echo "============================================"
  echo "Итого: ${pass} проверок ОК, ${fail} провалено"
  if [[ "$fail" -eq 0 ]]; then
    echo "Всё выглядит хорошо."
    echo "============================================"
    return 0
  else
    echo "Есть проблемы — смотри FAIL выше."
    echo "============================================"
    return 1
  fi
}

# ================== РЕЖИМ: REBIND-IP (смена публичного IP у провайдера) ==================
# v0.3.5: штатное решение сценария "заблокировали IP / сменили IP у
# провайдера" вместо отозванного wildcard-бинда из v0.3.3. Определяет
# текущий публичный IP, сверяет DNS (warn + подтверждение, если A-запись
# ещё не переключена), правит listen-строку в stream-конфиге (обе формы:
# legacy explicit и отозванный wildcard), бэкапит конфиг, валидирует,
# перезапускает nginx и проверяет факт бинда через ss. Идемпотентен.
cmd_rebind_ip() {
  if [[ $EUID -ne 0 ]]; then
    echo "Запусти от root: sudo bash $0 rebind-ip"
    exit 1
  fi
  read_domains
  if [[ -z "${DOMAIN:-}" ]]; then
    echo "ОШИБКА: домен панели не определён из ${CREDS_FILE}."
    exit 1
  fi

  SERVER_IP=$(get_server_ip)
  if [[ -z "$SERVER_IP" ]]; then
    read -rp "Введи публичный IPv4 сервера вручную: " SERVER_IP
  fi
  if [[ -z "$SERVER_IP" ]]; then
    echo "ОШИБКА: не удалось определить публичный IP."
    exit 1
  fi

  STREAM_CONF="/etc/nginx/stream-sni-router.conf"
  if [[ ! -f "$STREAM_CONF" ]]; then
    echo "ОШИБКА: ${STREAM_CONF} не найден — схема не развёрнута."
    exit 1
  fi

  echo "Текущий публичный IP: ${SERVER_IP}"
  for d in "$DOMAIN" "${REALITY_DOMAIN:-$DOMAIN}"; do
    cur=$(dig +short A "$d" @1.1.1.1 | head -n1 || true)
    if [[ "$cur" != "$SERVER_IP" ]]; then
      echo "WARN: $d резолвится в '${cur:-не найден}', а не в ${SERVER_IP}."
      echo "      Сначала обнови A-запись у регистратора, иначе трафик сюда не придёт."
    else
      echo "  DNS OK: $d -> $cur"
    fi
  done

  if grep -qE "listen ${SERVER_IP}:443;" "$STREAM_CONF"; then
    echo "listen-строка уже указывает на ${SERVER_IP} — ничего не меняю."
    exit 0
  fi

  cp "$STREAM_CONF" "${STREAM_CONF}.backup.$(date +%s)"
  # В server{} ровно одна listen-строка — меняем любую форму (explicit IP или wildcard)
  sed -i -E "s/^\s*listen\s+[^;]*443;/        listen ${SERVER_IP}:443;/" "$STREAM_CONF"
  if ! grep -qE "listen ${SERVER_IP}:443;" "$STREAM_CONF"; then
    echo "ОШИБКА: sed не применился — смотри ${STREAM_CONF} (бэкап: ${STREAM_CONF}.backup.*)"
    exit 1
  fi
  echo "listen-строка обновлена -> ${SERVER_IP}:443"

  nginx -t || { echo "ОШИБКА: nginx -t не прошёл. Откат: cp ${STREAM_CONF}.backup.* ${STREAM_CONF}"; exit 1; }
  systemctl restart nginx
  sleep 1
  if ! ss -tlnp 2>/dev/null | grep -qE "${SERVER_IP//./\.}:443\b.*nginx"; then
    echo "ОШИБКА: nginx не подтверждён на ${SERVER_IP}:443 после restart:"
    ss -tlnp | grep ':443 ' || true
    exit 1
  fi
  echo "OK: nginx подтверждён на ${SERVER_IP}:443."
  echo ""
  echo "========== ПАНЕЛЬ: можно / нельзя =========="
  echo "  МОЖНО:   клиентов (добавить/удалить/переименовать), подписки, Инси,"
  echo "           порт/путь панели, x-ui update (патчи своей линии)"
  echo "  НЕЛЬЗЯ:  сохранять боевые инбаунды через ФОРМУ (теряются proxy protocol"
  echo "           и клиенты — правка только через «Расширенный шаблон»/JSON);"
  echo "           переключать TLS<->Reality руками (только: bash $0 add-vls |"
  echo "           add-reality); включать Masking на 443; вешать инбаунды на 8443"
  echo "           (занят панелью); «Исходящие»/«Маршрутизация» без кнопки"
  echo "           «Сохранить» слева вверху (правки теряются)."
  echo "  Подробности — в README (раздел «После установки»)."
  echo "============================================"
  echo "Проверка связки: bash $0 healthcheck (блок [2] и Decoy №2 должны быть зелёными)."
}

# ================== UPGRADE (v0.4.7): патч скрипта без переустановки ==================

cmd_upgrade() {
  local raw_url="https://raw.githubusercontent.com/Shepard86rus/3x-ui-dual-domain/main/3x-ui-dual-domain.sh"
  local tmp self_dir
  # v0.4.7-fix (ревью Клоуда): tmp в каталоге скрипта (та же ФС) — mv = rename(2),
  # а не copy+unlink с обрезкой inode под работающим bash
  self_dir=$(dirname -- "$0")
  [[ -d "$self_dir" && -w "$self_dir" ]] || self_dir="/tmp"
  tmp=$(mktemp "$self_dir/lucx-upgrade.XXXXXX") || { echo "ОШИБКА: не создать временный файл"; return 1; }
  echo "Скачиваю новейшую версию скрипта с GitHub..."
  if ! curl -fsSL --max-time 120 "$raw_url" -o "$tmp"; then
    rm -f "$tmp"; echo "ОШИБКА: скачивание не удалось ($raw_url)"; return 1
  fi
  if ! bash -n "$tmp"; then
    rm -f "$tmp"; echo "ОШИБКА: новый файл не проходит bash -n — откат"; return 1
  fi
  local new_ver
  new_ver=$(grep -m1 '^VERSION=' "$tmp" | cut -d'"' -f2)
  if [[ -z "$new_ver" ]]; then
    rm -f "$tmp"; echo "ОШИБКА: в новом файле не найден VERSION — откат"; return 1
  fi
  if [[ "$new_ver" == "$VERSION" ]]; then
    rm -f "$tmp"; echo "Скрипт уже актуален: v$VERSION. Обновлять нечего."; return 0
  fi
  # v0.4.7-fix (ревью Клоуда): направление сравнения — локальная новее удалённой
  # означает даунгрейд, его не делаем (паттерн маркера v0.4.1: sort -V)
  if [[ "$(printf '%s\n%s\n' "$VERSION" "$new_ver" | sort -V | head -n1)" != "$VERSION" ]]; then
    rm -f "$tmp"; echo "ОТКАЗ: локальная версия v$VERSION НОВЕЕ удалённой v$new_ver — даунгрейд не выполняю"; return 1
  fi
  local self="$0"
  case "$self" in
    /dev/fd/*|/dev/stdin|"")
      rm -f "$tmp"; echo "ОШИБКА: скрипт запущен не из файла — скачай его и запускай как файл"; return 1 ;;
  esac
  if [[ ! -f "$self" ]]; then
    rm -f "$tmp"; echo "ОШИБКА: не определил свой путь ($0) — скопируй файл вручную"; return 1
  fi
  # атомарная замена: running bash держит fd на СТАРЫЙ inode, mv подменяет
  # запись в каталоге — текущее исполнение продолжается без сюрпризов
  cp -p "$self" "${self}.upgrade-old" || { rm -f "$tmp"; echo "ОШИБКА: не создать бэкап"; return 1; }
  mv -f "$tmp" "$self" || { rm -f "$tmp"; echo "ОШИБКА: замена не удалась"; return 1; }
  chmod --reference="${self}.upgrade-old" "$self" 2>/dev/null || chmod +x "$self"
  echo "Обновлено: v$VERSION -> v$new_ver (бэкап предыдущей: ${self}.upgrade-old)"
  echo "Запускаю healthcheck новой версией..."
  exec bash "$self" healthcheck
}

# ================== TELEGRAM-БОТ УПРАВЛЕНИЯ (v0.4.8, опция) ==================
# Один бот = одна нода. Карточки-кнопки в Telegram, whitelist по CHAT_ID,
# фиксированный словарь команд, локальное исполнение. Ноль новых открытых
# портов — бот сам ходит в api.telegram.org (long polling). Тело бота живёт
# в /opt/tgbot/tgbot.sh и правится только новой версией этого скрипта
# (add-bot перезаписывает тело, env не трогает).
TGBOT_DIR="/opt/tgbot"
TGBOT_ENV="/etc/tgbot/env"
TGBOT_BODY_VERSION="0.5.1"

tgbot_write_body() { # тело бота (правки — только через новую версию скрипта)
  mkdir -p "$TGBOT_DIR"
  cat > "$TGBOT_DIR/tgbot.sh" <<'TGBOT_EOF'
#!/usr/bin/env bash
# TG-бот управления нодой 3x-ui (ставится скриптом 3x-ui-dual-domain: install/add-bot)
# Карточки-кнопки, whitelist по CHAT_ID, фиксированный словарь команд, локальное исполнение.
# Конфиг: /etc/tgbot/env (600): TOKEN=, CHAT_ID= (пусто = режим обучения), NODE_NAME=, SCRIPT_PATH=
# Клиенты (v0.5.1, опц.): PANEL_API_TOKEN= (пусто = функция выключена), CLIENT_INBOUNDS=1,2 (пусто = vless+hysteria из БД), CLIENT_TZ=
set -u
ENV_FILE="/etc/tgbot/env"
[ -f "$ENV_FILE" ] && . "$ENV_FILE"
NODE_NAME="${NODE_NAME:-$(hostname)}"
API="https://api.telegram.org/bot${TOKEN:-}"
OFFSET=0
ASK_CMD=''; ASK_TS=0
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

esc() { sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' <<<"$1"; }

api_post() { local m="$1"; shift; curl -s --max-time 30 -X POST "$API/$m" "$@"; }
send_txt() { api_post sendMessage -d chat_id="$1" --data-urlencode "text=$2" >/dev/null; }
send_card() { api_post sendMessage -d chat_id="$1" --data-urlencode "text=$2" -d parse_mode="HTML" --data-urlencode "reply_markup=$3" >/dev/null; }
answer() {
  if [ -n "${2:-}" ]; then
    api_post answerCallbackQuery -d callback_query_id="$1" --data-urlencode "text=$2" >/dev/null
  else
    api_post answerCallbackQuery -d callback_query_id="$1" >/dev/null
  fi
}
home_text() { printf '🖥 <b>%s</b> — пульт ноды:' "$(esc "$NODE_NAME")"; }
show_home() { send_card "$1" "$(home_text)" "$(kb_home)"; }
edit_card() { # $1 chat, $2 message_id, $3 html, $4 markup; карточку старше 48ч не отредактировать — шлём новую
  local r
  r=$(api_post editMessageText -d chat_id="$1" -d message_id="$2" --data-urlencode "text=$3" -d parse_mode="HTML" --data-urlencode "reply_markup=$4")
  case "$r" in *'"ok":false'*) show_home "$1" ;; esac
}

kb_home() {
  local base row
  base=$(jq -nc '{inline_keyboard:[
    [{text:"📊 Статус",callback_data:"cmd:status"},{text:"🔢 Версии",callback_data:"cmd:versions"}],
    [{text:"💾 Диск",callback_data:"cmd:disk"},{text:"📜 Лог x-ui",callback_data:"cmd:log"}],
    [{text:"🩺 Healthcheck",callback_data:"cmd:hc"},{text:"🔐 Бэкап БД",callback_data:"cmd:backup"}],
    [{text:"♻ Рестарт панели",callback_data:"ask:restart_panel"},{text:"♻ Рестарт xray",callback_data:"ask:restart_xray"}],
    [{text:"⬆ Скрипт (upgrade)",callback_data:"ask:upgrade"},{text:"⬆ Панель (update)",callback_data:"ask:update_panel"}]
  ]}')
  if cl_enabled; then
    row='[{"text":"➕ Клиент","callback_data":"cl:add"},{"text":"🗑 Удалить клиента","callback_data":"cl:del"},{"text":"📋 Список","callback_data":"cl:list"}]'
    jq -c --argjson r "$row" '.inline_keyboard += [$r]' <<<"$base"
  else
    printf '%s\n' "$base"
  fi
}
kb_confirm() { # $1 cmd
  jq -nc --arg c "$1" '{inline_keyboard:[
    [{text:"✅ Да, выполняй",callback_data:("yes:"+$c)},{text:"❌ Отмена",callback_data:"home"}]
  ]}'
}

# ---------- клиенты (v0.5.1): создать / удалить / список через API панели ----------
CLIENT_TZ="${CLIENT_TZ:-Asia/Yekaterinburg}"
CL_STATE=''; CL_NAME=''; CL_LIMIT=0; CL_EXP=0; CL_TS=0; CL_DEL=''

cl_enabled() { [ -n "${PANEL_API_TOKEN:-}" ] && printf '%s' "$PANEL_API_TOKEN" | grep -qE '^[A-Za-z0-9._~+/=-]{8,200}$'; }
xdb() { sqlite3 -readonly /etc/x-ui/x-ui.db "$1" 2>/dev/null; } # только фиксированные запросы
cl_base() {
  if [ -n "${PANEL_API_BASE:-}" ]; then printf '%s' "$PANEL_API_BASE"; return 0; fi
  local p b
  p=$(xdb "SELECT value FROM settings WHERE key='webPort' LIMIT 1;")
  b=$(xdb "SELECT value FROM settings WHERE key='webBasePath' LIMIT 1;")
  b=${b#/}; b=${b%/}
  case "$p" in ''|*[!0-9]*) return 1 ;; esac
  if [ -n "$b" ]; then printf 'http://127.0.0.1:%s/%s' "$p" "$b"; else printf 'http://127.0.0.1:%s' "$p"; fi
}
cl_api() { # $1 GET|POST, $2 путь /panel/api/clients/..., $3 json-тело (опц.). Токен — через stdin curl, не в аргументах
  local base
  base=$(cl_base) || { echo '{"success":false,"msg":"порт панели не найден"}'; return 0; }
  local args=(-s --max-time 25 -X "$1" -K - -H 'Accept: application/json')
  if [ -n "${3:-}" ]; then args+=(-H 'Content-Type: application/json' --data-binary "$3"); fi
  printf 'header = "Authorization: Bearer %s"\n' "$PANEL_API_TOKEN" | curl "${args[@]}" "$base$2" || echo '{"success":false,"msg":"панель не ответила"}'
}
cl_inbounds() { # id инбаундов через пробел: CLIENT_INBOUNDS или vless+hysteria из БД
  local raw
  if [ -n "${CLIENT_INBOUNDS:-}" ]; then raw=$(printf '%s' "$CLIENT_INBOUNDS" | tr ',' ' ')
  else raw=$(xdb "SELECT id FROM inbounds WHERE enable=1 AND protocol IN ('vless','hysteria','hysteria2') ORDER BY id;" | tr '\n' ' '); fi
  for i in $raw; do case "$i" in ''|*[!0-9]*) ;; *) printf '%s ' "$i" ;; esac; done
}
cl_inb_desc() { local i; for i in $1; do xdb "SELECT '#'||id||' '||protocol||':'||port FROM inbounds WHERE id=$i;"; done | tr '\n' ' '; }
cl_fmt_exp() { # $1 мс
  if [ "${1:-0}" -le 0 ] 2>/dev/null; then echo 'без срока'; return; fi
  TZ="$CLIENT_TZ" date -d "@$(( $1 / 1000 ))" '+%d.%m.%Y %H:%M'
}
cl_exists() { cl_api GET /panel/api/clients/list | jq -e --arg e "$1" '.success==true and ((.obj // []) | map(.email) | index($e) != null)' >/dev/null 2>&1; }
cl_reset() { CL_STATE=''; CL_NAME=''; CL_LIMIT=0; CL_EXP=0; CL_DEL=''; }

kb_cl_limit() { jq -nc '{inline_keyboard:[[{text:"1",callback_data:"cl:lim:1"},{text:"2",callback_data:"cl:lim:2"},{text:"3",callback_data:"cl:lim:3"},{text:"5",callback_data:"cl:lim:5"},{text:"без лимита",callback_data:"cl:lim:0"}],[{text:"❌ Отмена",callback_data:"cl:cancel"}]]}'; }
kb_cl_exp() { jq -nc '{inline_keyboard:[[{text:"+30 дн",callback_data:"cl:exp:30"},{text:"+90 дн",callback_data:"cl:exp:90"},{text:"+365 дн",callback_data:"cl:exp:365"}],[{text:"без срока",callback_data:"cl:exp:0"},{text:"✍ ввести дату",callback_data:"cl:exp:man"}],[{text:"❌ Отмена",callback_data:"cl:cancel"}]]}'; }
kb_cl_yes() { jq -nc --arg y "$1" '{inline_keyboard:[[{text:"✅ Да",callback_data:$y},{text:"❌ Отмена",callback_data:"cl:cancel"}]]}'; }

cl_confirm_create() { # $1 chat
  local ids
  ids=$(cl_inbounds)
  send_card "$1" "➕ <b>Новый клиент</b>
Имя: <code>$(esc "$CL_NAME")</code>
Лимит IP: $([ "$CL_LIMIT" -eq 0 ] && echo 'без лимита' || echo "$CL_LIMIT")
Срок: $(cl_fmt_exp "$CL_EXP")
Протоколы: $(esc "$(cl_inb_desc "$ids")")
Создать?" "$(kb_cl_yes cl:create)"
}
cl_do_create() { # $1 chat
  local ids idsj sub payload r link suburi
  ids=$(cl_inbounds)
  if [ -z "$ids" ]; then send_txt "$1" "[$NODE_NAME] ОШИБКА: не нашёл инбаунды (vless/hysteria) — задай CLIENT_INBOUNDS в /etc/tgbot/env"; return; fi
  idsj=$(printf '%s\n' $ids | jq -Rsc 'split("\n") | map(select(length>0) | tonumber)')
  sub=$(LC_ALL=C tr -dc 'a-z0-9' </dev/urandom | head -c 16)
  payload=$(jq -nc --arg e "$CL_NAME" --arg s "$sub" --argjson l "$CL_LIMIT" --argjson x "$CL_EXP" --argjson ids "$idsj" \
    '{client:{email:$e,subId:$s,limitIp:$l,totalGB:0,expiryTime:$x,enable:true,tgId:0,comment:"создан ботом",flow:"xtls-rprx-vision"},inboundIds:$ids}')
  r=$(cl_api POST /panel/api/clients/add "$payload")
  if jq -e '.success==true' <<<"$r" >/dev/null 2>&1 && cl_exists "$CL_NAME"; then
    suburi=$(xdb "SELECT value FROM settings WHERE key='subURI' LIMIT 1;")
    link="${suburi}${sub}"
    send_txt "$1" "[$NODE_NAME] ✅ Клиент $CL_NAME создан (срок: $(cl_fmt_exp "$CL_EXP"), лимит IP: $CL_LIMIT).
Подписка (одна ссылка — все протоколы):
$link"
  else
    send_txt "$1" "[$NODE_NAME] ОШИБКА создания клиента: $(jq -r '.msg // "нет ответа"' <<<"$r" 2>/dev/null | cut -c1-300)"
  fi
  cl_reset
}
cl_do_delete() { # $1 chat
  local r
  r=$(cl_api POST "/panel/api/clients/del/$CL_DEL")
  if jq -e '.success==true' <<<"$r" >/dev/null 2>&1 && ! cl_exists "$CL_DEL"; then
    send_txt "$1" "[$NODE_NAME] 🗑 Клиент $CL_DEL удалён."
  else
    send_txt "$1" "[$NODE_NAME] ОШИБКА удаления $CL_DEL: $(jq -r '.msg // "нет ответа"' <<<"$r" 2>/dev/null | cut -c1-300)"
  fi
  cl_reset
}
cl_do_list() { # $1 chat
  local r out n e x en l
  r=$(cl_api GET /panel/api/clients/list)
  if ! jq -e '.success==true' <<<"$r" >/dev/null 2>&1; then
    send_txt "$1" "[$NODE_NAME] ОШИБКА списка: $(jq -r '.msg // "нет ответа"' <<<"$r" 2>/dev/null | cut -c1-300)"; return
  fi
  n=$(jq '(.obj // []) | length' <<<"$r")
  out="[$NODE_NAME] Клиентов: $n"
  while IFS=$'\t' read -r e x en l; do
    [ -z "$e" ] && continue
    out="$out
$([ "$en" = true ] && echo '🟢' || echo '⚪') $e — до $(cl_fmt_exp "$x"), IP: $l"
  done < <(jq -r '(.obj // [])[:60][] | [.email, (.expiryTime // 0), (.enable // false), (.limitIp // 0)] | @tsv' <<<"$r")
  [ "$n" -gt 60 ] && out="$out
… показаны первые 60"
  [ "${#out}" -gt 3900 ] && out=${out:0:3900}
  send_txt "$1" "$out"
}
cl_cb() { # $1 chat, $2 callback_id, $3 data
  local d="${3#cl:}" days
  if ! cl_enabled; then answer "$2" 'управление клиентами выключено (нет PANEL_API_TOKEN)'; return; fi
  if [ -n "$CL_STATE" ] && [ $(( $(date +%s) - CL_TS )) -gt 600 ]; then cl_reset; fi
  case "$d" in
    add)  cl_reset; CL_STATE=name; CL_TS=$(date +%s); answer "$2" ''
          send_txt "$1" 'Имя нового клиента: латиница, цифры, _ и -, 3–32 символа. /cancel — отмена.' ;;
    del)  cl_reset; CL_STATE=delname; CL_TS=$(date +%s); answer "$2" ''
          send_txt "$1" 'Имя клиента для удаления (точно как в списке). /cancel — отмена.' ;;
    list) answer "$2" 'читаю…'; cl_do_list "$1" ;;
    cancel) cl_reset; answer "$2" 'отменено' ;;
    lim:*)
      [ "$CL_STATE" = limit ] || { answer "$2" 'шаг устарел — начни заново'; return; }
      case "${d#lim:}" in 0|1|2|3|5) CL_LIMIT="${d#lim:}" ;; *) answer "$2" 'неверное значение'; return ;; esac
      CL_STATE=exp; CL_TS=$(date +%s); answer "$2" ''
      send_card "$1" 'Срок действия:' "$(kb_cl_exp)" ;;
    exp:*)
      [ "$CL_STATE" = exp ] || { answer "$2" 'шаг устарел — начни заново'; return; }
      days="${d#exp:}"
      case "$days" in
        0)   CL_EXP=0 ;;
        30|90|365) CL_EXP=$(( ($(date +%s) + days * 86400) * 1000 )) ;;
        man) CL_STATE=exp_manual; CL_TS=$(date +%s); answer "$2" ''
             send_txt "$1" "Дата и время окончания в формате ДД.ММ.ГГГГ ЧЧ:ММ (часовой пояс $CLIENT_TZ). /cancel — отмена."; return ;;
        *)   answer "$2" 'неверное значение'; return ;;
      esac
      CL_STATE=confirm; CL_TS=$(date +%s); answer "$2" ''
      cl_confirm_create "$1" ;;
    create)
      [ "$CL_STATE" = confirm ] || { answer "$2" 'подтверждение устарело — начни заново'; return; }
      answer "$2" 'создаю…'; cl_do_create "$1" ;;
    delyes)
      [ "$CL_STATE" = delconfirm ] && [ -n "$CL_DEL" ] || { answer "$2" 'подтверждение устарело — начни заново'; return; }
      answer "$2" 'удаляю…'; cl_do_delete "$1" ;;
    *) answer "$2" 'неизвестно' ;;
  esac
}
cl_text() { # $1 chat, $2 text — ввод в процессе мастера
  local t="$2" sec
  if [ $(( $(date +%s) - CL_TS )) -gt 600 ]; then cl_reset; send_txt "$1" 'Время ввода вышло — начни заново: /menu'; return; fi
  case "$CL_STATE" in
    name)
      if ! printf '%s' "$t" | grep -qE '^[A-Za-z0-9_-]{3,32}$'; then send_txt "$1" 'Имя: латиница, цифры, _ и -, 3–32 символа. Ещё раз или /cancel.'; return; fi
      if cl_exists "$t"; then send_txt "$1" 'Такой клиент уже есть. Другое имя или /cancel.'; return; fi
      CL_NAME="$t"; CL_STATE=limit; CL_TS=$(date +%s)
      send_card "$1" 'Лимит одновременных IP (устройств):' "$(kb_cl_limit)" ;;
    exp_manual)
      if ! printf '%s' "$t" | grep -qE '^[0-9]{2}\.[0-9]{2}\.[0-9]{4} [0-9]{2}:[0-9]{2}$'; then send_txt "$1" 'Формат: ДД.ММ.ГГГГ ЧЧ:ММ, например 31.12.2026 23:59. Ещё раз или /cancel.'; return; fi
      sec=$(TZ="$CLIENT_TZ" date -d "${t:6:4}-${t:3:2}-${t:0:2} ${t:11:5}" +%s 2>/dev/null) || { send_txt "$1" 'Такой даты не существует. Ещё раз или /cancel.'; return; }
      if [ "$sec" -le "$(date +%s)" ]; then send_txt "$1" 'Дата уже прошла. Ещё раз или /cancel.'; return; fi
      CL_EXP=$(( sec * 1000 )); CL_STATE=confirm; CL_TS=$(date +%s)
      cl_confirm_create "$1" ;;
    delname)
      if ! printf '%s' "$t" | grep -qE '^[A-Za-z0-9_@.-]{1,64}$'; then send_txt "$1" 'Недопустимое имя. Ещё раз или /cancel.'; return; fi
      if ! cl_exists "$t"; then send_txt "$1" 'Клиент не найден (см. 📋 Список). Ещё раз или /cancel.'; return; fi
      CL_DEL="$t"; CL_STATE=delconfirm; CL_TS=$(date +%s)
      send_card "$1" "🗑 Удалить клиента <code>$(esc "$t")</code> со всеми протоколами? Это необратимо." "$(kb_yes_del)" ;;
    *) send_txt "$1" 'кнопки: /menu' ;;
  esac
}
kb_yes_del() { kb_cl_yes cl:delyes; }

script_file() {
  if [ -n "${SCRIPT_PATH:-}" ] && [ -f "$SCRIPT_PATH" ]; then echo "$SCRIPT_PATH"; return; fi
  ls -1 /root/3x-ui-dual-domain*.sh 2>/dev/null | tail -1
}
snippet() { # $1 cmd — фиксированный словарь, исполнение локально
  case "$1" in
    status)
      cat <<'EOS'
echo "панель: $(systemctl is-active x-ui 2>/dev/null); nginx: $(systemctl is-active nginx 2>/dev/null); xray: $(pgrep -c xray 2>/dev/null || echo 0)"
for d in /etc/letsencrypt/live/*/; do
  [ -f "$d/cert.pem" ] || continue
  echo "серт $(basename "$d"): до $(openssl x509 -enddate -noout -in "$d/cert.pem" 2>/dev/null | cut -d= -f2)"
done
echo "диск: $(df -h / | tail -1 | awk "{print \$4}") свободно; load: $(cut -d" " -f1-3 /proc/loadavg)"
EOS
      ;;
    versions)
      cat <<'EOS'
echo "панель: $(/usr/local/x-ui/x-ui -v 2>/dev/null | head -1 || echo '?')"
xbin="/usr/local/x-ui/bin/xray-linux-$(uname -m | sed 's/x86_64/amd64/; s/aarch64/arm64/')"
echo "xray: $([ -x "$xbin" ] && "$xbin" -version 2>/dev/null | head -1 | awk '{print $2}' || echo '?')"
echo "скрипт: $(cat /root/.lucx-script-version 2>/dev/null || echo '?')"
EOS
      ;;
    disk)    echo 'df -h /' ;;
    log)     echo 'journalctl -u x-ui -n 15 --no-pager 2>/dev/null | tail -15 | cut -c1-200' ;;
    backup)  echo 'f="/root/x-ui-backup-$(date +%F-%H%M).db"; sqlite3 /etc/x-ui/x-ui.db ".backup $f" && [ -s "$f" ] && echo "бэкап: $f" || echo "ОШИБКА бэкапа"' ;;
    restart_panel) echo 'systemctl restart x-ui && echo "панель перезапущена" || echo "ОШИБКА рестарта"' ;;
    restart_xray)  echo 'pkill -f "[x]ray-linux-"; sleep 3; n=$(pgrep -c -f "[x]ray-linux-" 2>/dev/null); n=${n:-0}; if [ "$n" -eq 0 ]; then sleep 5; n=$(pgrep -c -f "[x]ray-linux-" 2>/dev/null); n=${n:-0}; fi; echo "xray процессов: $n"' ;;
    update_panel)
      echo 'printf "y\n4\n" | timeout 300 x-ui update >/dev/null 2>&1; sleep 30; echo "сервис: $(systemctl is-active x-ui); версия: $(/usr/local/x-ui/x-ui -v 2>/dev/null | head -1)"'
      ;;
    *)
      echo ''
      ;;
  esac
}
snippet_hc() { # $1 путь к скрипту установки
  cat <<EOS
s="$1"
if [ -z "\$s" ]; then echo "ОШИБКА: скрипт установки не найден — задай SCRIPT_PATH в /etc/tgbot/env"; else
  o=\$(timeout 280 bash "\$s" healthcheck 2>&1)
  echo "\$o" | grep -E "Итого:|FAIL\]" || echo "\$o" | tail -5
fi
EOS
}
snippet_upgrade() { # $1 путь к скрипту установки
  cat <<EOS
s="$1"
if [ -z "\$s" ]; then echo "ОШИБКА: скрипт установки не найден — задай SCRIPT_PATH в /etc/tgbot/env"; else
  o=\$(timeout 120 bash "\$s" upgrade 2>&1)
  grep -E "Обновлено|уже актуален|ОТКАЗ|ОШИБКА" <<<"\$o" | head -3 || echo "upgrade: вывода нет — проверь hc"
fi
EOS
}
run_cmd() { # $1 cmd — словарь проверен вызывающим
  local sf
  case "$1" in
    hc)      sf=$(script_file); bash -c "$(snippet_hc "$sf")" 2>&1 ;;
    upgrade) sf=$(script_file); bash -c "$(snippet_upgrade "$sf")" 2>&1 ;;
    *)       bash -c "$(snippet "$1")" 2>&1 ;;
  esac
}

on_callback() { # $1 = callback_query json
  local cbid data mid cid c t out
  cbid=$(jq -r '.id' <<<"$1")
  cid=$(jq -r '.message.chat.id // .from.id // empty' <<<"$1")
  mid=$(jq -r '.message.message_id // empty' <<<"$1")
  data=$(jq -r '.data // empty' <<<"$1")
  if [ -z "$cid" ] || [ "$cid" != "${CHAT_ID:-}" ]; then answer "$cbid" 'нет доступа'; return; fi
  case "$data" in
    home)
      answer "$cbid" ''
      edit_card "$cid" "$mid" "$(home_text)" "$(kb_home)"
      ;;
    cmd:*)
      c=${data#cmd:}
      case "$c" in status|versions|disk|log|backup|hc) ;; *) answer "$cbid" 'неизвестная команда'; return ;; esac
      if [ "$c" = 'hc' ]; then answer "$cbid" 'гоняю healthcheck…'; else answer "$cbid" 'выполняю…'; fi
      out=$(run_cmd "$c")
      [ -z "$out" ] && out='пустой ответ'
      [ "${#out}" -gt 3900 ] && out=${out:0:3900}
      send_txt "$cid" "[$NODE_NAME]
$out"
      ;;
    ask:*)
      c=${data#ask:}
      case "$c" in restart_panel|restart_xray|upgrade|update_panel) ;; *) answer "$cbid" 'неизвестная команда'; return ;; esac
      ASK_CMD="$c"; ASK_TS=$(date +%s)
      case "$c" in
        restart_panel) t='рестарт панели' ;;
        restart_xray)  t='рестарт xray (клиенты переподключатся)' ;;
        upgrade)       t='обновление скрипта (до новейшей + hc)' ;;
        update_panel)  t='обновление панели (~1-2 мин, панель кратко недоступна)' ;;
      esac
      answer "$cbid" ''
      edit_card "$cid" "$mid" "⚠ <b>$(esc "$NODE_NAME")</b>: $t. Выполнять?" "$(kb_confirm "$c")"
      ;;
    yes:*)
      c=${data#yes:}
      if [ "$c" = "$ASK_CMD" ] && [ $(( $(date +%s) - ASK_TS )) -le 120 ]; then
        answer "$cbid" 'выполняю…'
        out=$(run_cmd "$c")
        [ -z "$out" ] && out='пустой ответ'
        [ "${#out}" -gt 3900 ] && out=${out:0:3900}
        send_txt "$cid" "[$NODE_NAME]
$out"
        ASK_CMD=''
      else
        answer "$cbid" 'подтверждение истекло — запроси заново'
      fi
      ;;
    cl:*)
      cl_cb "$cid" "$cbid" "$data"
      ;;
    *)
      answer "$cbid" 'неизвестно'
      ;;
  esac
}

handle() { # $1 chat_id, $2 text
  if [ -z "${CHAT_ID:-}" ]; then
    if [ "$2" = '/start' ] || [ "$2" = '/help' ]; then
      send_txt "$1" "ACCESS_CODE: chat_id=$1 — пришли этот номер владельцу. Он вписывает его в CHAT_ID в /etc/tgbot/env и делает systemctl restart tgbot. До этого команды не работают."
    fi
    return
  fi
  [ "$1" != "$CHAT_ID" ] && return
  case "$2" in
    /cancel)
      cl_reset
      send_txt "$1" 'Отменено. /menu'
      return
      ;;
  esac
  if [ -n "$CL_STATE" ] && [ "$2" != '/start' ] && [ "$2" != '/menu' ] && [ "$2" != '/help' ]; then
    cl_text "$1" "$2"
    return
  fi
  case "$2" in
    /start|/help|/menu)
      cl_reset
      show_home "$1"
      ;;
    *)
      send_txt "$1" 'кнопки: /menu'
      ;;
  esac
}

if [ "${1:-}" = selftest ]; then
  kb_home | jq -e '.inline_keyboard | length >= 5' >/dev/null && echo 'kb_home: ok' || echo 'kb_home: ПРОВАЛ'
  kb_cl_limit | jq -e '.inline_keyboard[0] | length == 5' >/dev/null && kb_cl_exp | jq -e '.inline_keyboard | length == 3' >/dev/null && kb_cl_yes cl:create | jq -e '.inline_keyboard[0] | length == 2' >/dev/null && echo 'kb_clients: ok' || echo 'kb_clients: ПРОВАЛ'
  if cl_enabled; then echo 'клиенты: включено (PANEL_API_TOKEN задан)'; else echo 'клиенты: выключено (нет PANEL_API_TOKEN)'; fi
  kb_confirm restart_panel | jq -e '.inline_keyboard[0] | length == 2' >/dev/null && echo 'kb_confirm: ok' || echo 'kb_confirm: ПРОВАЛ'
  ok=1
  for c in status versions disk log backup restart_panel restart_xray update_panel; do
    [ -n "$(snippet "$c")" ] || { echo "snippet $c: ПУСТОЙ"; ok=0; }
  done
  [ -n "$(snippet_hc /root/3x-ui-dual-domain.sh)" ] || { echo 'snippet hc: ПУСТОЙ'; ok=0; }
  [ -n "$(snippet_upgrade /root/3x-ui-dual-domain.sh)" ] || { echo 'snippet upgrade: ПУСТОЙ'; ok=0; }
  [ "$ok" = 1 ] && echo 'SELFTEST: ВСЁ ОК' || echo 'SELFTEST: ЕСТЬ ПРОВАЛЫ'
  exit 0
fi

while true; do
  resp=$(curl -s --max-time 40 "$API/getUpdates?timeout=30&offset=$OFFSET") || { sleep 5; continue; }
  n=$(jq '.result | length' <<<"$resp" 2>/dev/null) || n=0
  i=0
  while [ "$i" -lt "$n" ]; do
    upd=$(jq -c ".result[$i]" <<<"$resp" 2>/dev/null)
    OFFSET=$(jq -r '.update_id + 1' <<<"$upd" 2>/dev/null)
    if jq -e '.callback_query != null' <<<"$upd" >/dev/null 2>&1; then
      on_callback "$(jq -c '.callback_query' <<<"$upd")"
    else
      cid=$(jq -r '.message.chat.id // empty' <<<"$upd" 2>/dev/null)
      text=$(jq -r '.message.text // empty' <<<"$upd" 2>/dev/null)
      [ -n "$cid" ] && [ -n "$text" ] && handle "$cid" "$text"
    fi
    i=$((i + 1))
  done
done
TGBOT_EOF
  chmod 700 "$TGBOT_DIR/tgbot.sh"
  echo "$TGBOT_BODY_VERSION" > "$TGBOT_DIR/.version"
}

tgbot_write_unit() {
  cat > /etc/systemd/system/tgbot.service <<'TGBOT_UNIT_EOF'
[Unit]
Description=3x-ui TG node bot
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
EnvironmentFile=/etc/tgbot/env
ExecStart=/opt/tgbot/tgbot.sh
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
TGBOT_UNIT_EOF
  systemctl daemon-reload
}

tgbot_sh_quote() { # значение для env: одиночные кавычки -> '\''
  printf "%s" "$1" | sed "s/'/'\\\\''/g"
}

tgbot_install_files() { # $1 token, $2 chat_id, $3 name, $4 script_path, $5 panel API token (опц.).
  # Пустой ввод сохраняет старое значение env (повторный add-bot с Enter
  # везде = безопасное обновление тела); непустой ввод ЗАМЕНЯЕТ значение.
  local tok="$1" cid="$2" nm="$3" sp="$4" apit="${5:-}" k v
  mkdir -p "$(dirname "$TGBOT_ENV")"
  touch "$TGBOT_ENV"
  chmod 600 "$TGBOT_ENV"
  for k in TOKEN CHAT_ID NODE_NAME SCRIPT_PATH PANEL_API_TOKEN; do
    case "$k" in
      TOKEN) v="$tok" ;;
      CHAT_ID) v="$cid" ;;
      NODE_NAME) v="$nm" ;;
      SCRIPT_PATH) v="$sp" ;;
      PANEL_API_TOKEN) v="$apit" ;;
    esac
    if [ -z "$v" ]; then
      continue
    fi
    if grep -q "^${k}=" "$TGBOT_ENV"; then
      sed -i "/^${k}=/d" "$TGBOT_ENV"
    fi
    printf "%s='%s'\n" "$k" "$(tgbot_sh_quote "$v")" >> "$TGBOT_ENV"
  done
  tgbot_write_body
  tgbot_write_unit
}

cmd_add_bot() {
  echo "=== Telegram-бот управления (один бот = эта нода) ==="
  echo "Понадобится токен от @BotFather (в Telegram: /newbot, займёт минуту)."
  echo
  local tok cid nm sp ans apit
  read -rs -rp "Токен от @BotFather (пусто — вписать позже в $TGBOT_ENV; ввод скрыт): " tok || tok=""
  echo
  if [ -n "$tok" ] && ! printf '%s' "$tok" | grep -qE '^[0-9]+:[A-Za-z0-9_-]{30,}$'; then
    echo "ВНИМАНИЕ: строка не похожа на токен BotFather (вида 123456789:AAx...)."
    read -rp "Всё равно вписать? [y/N]: " ans || ans=""
    if ! [[ "$ans" =~ ^[Yy] ]]; then
      echo "Отменено."
      return 0
    fi
  fi
  read -rp "Твой Telegram ID — узнать у @userinfobot (пусто — режим обучения: бот сам пришлёт chat_id по /start): " cid || cid=""
  read -rp "Название ноды в боте (пусто — оставить текущее; при первой установке будет $(hostname)): " nm || nm=""
  echo
  echo "Управление клиентами из бота (создать/удалить/список) — опционально."
  echo "Нужен API-токен панели со scope «admin» (панель → настройки → API-токены). Он хранится в $TGBOT_ENV (600)."
  read -rs -rp "API-токен панели (пусто — не менять / не использовать; ввод скрыт): " apit || apit=""
  echo
  if [ -n "$apit" ] && ! printf '%s' "$apit" | grep -qE '^[A-Za-z0-9._~+/=-]{8,200}$'; then
    echo "ВНИМАНИЕ: токен содержит недопустимые символы — не вписываю."
    apit=""
  fi
  sp=$(readlink -f "$0" 2>/dev/null || true)
  if ! command -v jq >/dev/null 2>&1; then
    echo "Ставлю jq (нужен боту)..."
    apt-get install -y jq >/dev/null 2>&1 || { echo "ОШИБКА: не поставить jq"; return 1; }
  fi
  tgbot_install_files "$tok" "$cid" "$nm" "$sp" "$apit"
  # фактические значения берём из env: пустой ввод сохранял старое
  local tok_eff cid_eff
  tok_eff=$(grep "^TOKEN=" "$TGBOT_ENV" 2>/dev/null | head -1 | sed "s/^TOKEN='//; s/'\$//" || true)
  cid_eff=$(grep "^CHAT_ID=" "$TGBOT_ENV" 2>/dev/null | head -1 | sed "s/^CHAT_ID='//; s/'\$//" || true)
  if systemctl is-active --quiet tgbot 2>/dev/null; then
    systemctl try-restart tgbot
    echo "  Тело бота обновлено, сервис перезапущен (env сохранён)."
  elif [ -n "$tok_eff" ]; then
    systemctl enable --now tgbot >/dev/null 2>&1 || true
  fi
  if [ -n "$tok_eff" ]; then
    sleep 1
    if [ "$(systemctl is-active tgbot 2>/dev/null)" = "active" ]; then
      echo "✓ Бот установлен и запущен."
      if [ -n "$cid_eff" ]; then
        echo "  Открой бота в Telegram и отправь /start — придёт карточка ноды."
      else
        echo "  РЕЖИМ ОБУЧЕНИЯ: отправь боту /start — он пришлёт ACCESS_CODE (твой chat_id)."
        echo "  Впиши его в $TGBOT_ENV (CHAT_ID=...) и выполни: systemctl restart tgbot"
      fi
    else
      echo "ВНИМАНИЕ: юнит не поднялся — смотри journalctl -u tgbot -n 20"
    fi
  else
    echo "✓ Файлы бота установлены (юнит не включён — токен не вписан)."
    echo "  Когда вписать токен в $TGBOT_ENV (TOKEN=...), выполни: systemctl enable --now tgbot"
  fi
  echo "  Проверка: sudo bash $0 healthcheck (проверка [12])"
}

cmd_remove_bot() {
  echo "=== Удаление Telegram-бота ==="
  local ans
  read -rp "Снести бота (юнит + $TGBOT_DIR + env с токеном)? [y/N]: " ans || ans=""
  if ! [[ "$ans" =~ ^[Yy] ]]; then
    echo "Отменено."
    return 0
  fi
  systemctl disable --now tgbot >/dev/null 2>&1 || true
  rm -f /etc/systemd/system/tgbot.service
  systemctl daemon-reload
  rm -rf "$TGBOT_DIR"
  rm -f "$TGBOT_ENV"
  rmdir /etc/tgbot 2>/dev/null || true
  echo "✓ Бот удалён."
}

# ================== РЕЖИМ: ADD-SWAP / REMOVE-SWAP (v0.5.1, опционально) ==================
# Зачем: на VPS с 1 ГБ ОЗУ нет запаса на пики (сборка модуля AWG через DKMS,
# обновление панели) — без swap ядро убивает процесс (x-ui/xray), ноду «роняет»
# на минуты. Swap-файл — страховка от OOM, а не ускорение: при swappiness=10 он
# используется только под давлением памяти. На ВМ с подвисающим диском (hc [13]
# даёт WARN про io-давление) swap может ухудшить подвисания — там не включать.
# Ставится ТОЛЬКО явной командой, из install не вызывается.
SWAP_FILE="/swapfile"
SWAP_MARK="# 3x-ui-dual-domain add-swap"
SWAP_SYSCTL="/etc/sysctl.d/99-3x-ui-swap.conf"

cmd_add_swap() {
  local size_arg="1G" size_mb=0 arg
  while [[ $# -gt 0 ]]; do
    arg="$1"
    case "$arg" in
      --size) size_arg="${2:-}"; shift 2 || { echo "ОШИБКА: у --size нет значения (512M|1G|2G)"; return 1; } ;;
      --size=*) size_arg="${arg#--size=}"; shift ;;
      *) echo "ОШИБКА: неизвестный аргумент: $arg (допустимо: --size 512M|1G|2G)"; return 1 ;;
    esac
  done
  if ! [[ "$size_arg" =~ ^[0-9]+[MG]$ ]]; then
    echo "ОШИБКА: размер должен быть вида 512M, 1G, 2G (получено: '${size_arg}')"; return 1
  fi
  if [[ "$size_arg" == *G ]]; then size_mb=$(( ${size_arg%G} * 1024 )); else size_mb=${size_arg%M}; fi
  if (( size_mb < 256 || size_mb > 4096 )); then
    echo "ОШИБКА: допустимый размер от 256M до 4G (получено: ${size_arg})"; return 1
  fi
  [[ $EUID -eq 0 ]] || { echo "ОШИБКА: нужен root (sudo)"; return 1; }

  echo "=== add-swap: swap-файл ${size_arg} ==="
  echo "Зачем: страховка от OOM на ноде с малой памятью (пики при DKMS/обновлении панели)."
  echo "Это не ускорение: при swappiness=10 swap используется только под давлением памяти."
  echo

  # уже есть swap — ничего не делаем
  if [[ -n "$(swapon --show --noheadings 2>/dev/null)" ]]; then
    echo "Swap уже подключён — ничего не делаю:"
    swapon --show 2>/dev/null | sed 's/^/  /'
    return 0
  fi
  # контейнерная виртуализация без прав на swap
  local virt
  virt=$(systemd-detect-virt -c 2>/dev/null || true)
  if [[ -n "$virt" && "$virt" != "none" ]]; then
    echo "ОТКАЗ: контейнер (${virt}) — swap-файл там обычно недоступен/управляется хостом."
    return 1
  fi
  local fst
  fst=$(stat -f -c %T / 2>/dev/null || echo unknown)
  case "$fst" in
    btrfs|zfs)
      echo "ОТКАЗ: корневая ФС ${fst} — для swap-файла нужна особая подготовка, скрипт её не делает."
      return 1 ;;
  esac
  if [[ -e "$SWAP_FILE" ]]; then
    echo "ОТКАЗ: ${SWAP_FILE} уже существует (но не подключён). Не трогаю чужой файл — удали/переименуй сам."
    return 1
  fi
  local avail_mb
  avail_mb=$(df -Pm / | awk 'NR==2{print $4}')
  if [[ -z "$avail_mb" ]] || (( avail_mb < size_mb * 3 )); then
    echo "ОТКАЗ: мало места на / (свободно ${avail_mb:-?} МБ, нужно не меньше ${size_mb}*3 = $(( size_mb * 3 )) МБ)."
    return 1
  fi
  # предупреждение про подвисания диска
  if [[ -r /proc/pressure/io ]]; then
    local psi
    psi=$(awk '/^full/{for(i=1;i<=NF;i++) if($i ~ /^avg300=/){sub("avg300=","",$i); print $i}}' /proc/pressure/io 2>/dev/null | head -1)
    if [[ -n "$psi" ]] && awk -v v="$psi" -v t="$PSI_WARN_PCT" 'BEGIN{exit !(v+0>=t+0)}'; then
      echo "ВНИМАНИЕ: io-давление диска ${psi}% (порог ${PSI_WARN_PCT}%) — на ВМ с подвисающим диском swap может ухудшить ситуацию."
      echo "         Продолжаю, т.к. команда запущена явно; откат: sudo bash $0 remove-swap"
    fi
  fi

  if ! fallocate -l "${size_mb}M" "$SWAP_FILE" 2>/dev/null; then
    echo "fallocate не поддерживается — создаю через dd (подожди)…"
    if ! dd if=/dev/zero of="$SWAP_FILE" bs=1M count="$size_mb" status=none; then
      rm -f "$SWAP_FILE"; echo "ОШИБКА: не удалось создать ${SWAP_FILE}"; return 1
    fi
  fi
  chmod 600 "$SWAP_FILE"
  if ! mkswap "$SWAP_FILE" >/dev/null; then
    rm -f "$SWAP_FILE"; echo "ОШИБКА: mkswap не удался"; return 1
  fi
  if ! swapon "$SWAP_FILE"; then
    rm -f "$SWAP_FILE"; echo "ОШИБКА: swapon не удался (ядро/хостер не разрешает swap?)"; return 1
  fi
  if ! grep -qF "$SWAP_MARK" /etc/fstab 2>/dev/null; then
    cp -a /etc/fstab "/etc/fstab.backup.$(date +%s)"
    echo "${SWAP_FILE} none swap sw 0 0 ${SWAP_MARK}" >> /etc/fstab
  fi
  printf 'vm.swappiness=10\n' > "$SWAP_SYSCTL"
  sysctl -q -p "$SWAP_SYSCTL" >/dev/null 2>&1 || sysctl -w vm.swappiness=10 >/dev/null 2>&1 || true
  echo "Готово: swap ${size_arg} подключён, vm.swappiness=10, запись в /etc/fstab добавлена."
  swapon --show 2>/dev/null | sed 's/^/  /'
  echo "Откат: sudo bash $0 remove-swap"
}

cmd_remove_swap() {
  [[ $EUID -eq 0 ]] || { echo "ОШИБКА: нужен root (sudo)"; return 1; }
  echo "=== remove-swap: откат add-swap ==="
  if ! grep -qF "$SWAP_MARK" /etc/fstab 2>/dev/null && [[ ! -f "$SWAP_SYSCTL" ]]; then
    echo "Swap, созданный этим скриптом (метка '${SWAP_MARK}'), не найден — ничего не делаю."
    return 0
  fi
  if swapon --show=NAME --noheadings 2>/dev/null | grep -qx "$SWAP_FILE"; then
    # swapoff при полном swap может загнать ноду в OOM — проверяем запас памяти
    local used_kb avail_kb
    used_kb=$(awk '/^SwapTotal:/{t=$2}/^SwapFree:/{f=$2}END{print t-f}' /proc/meminfo)
    avail_kb=$(awk '/^MemAvailable:/{print $2}' /proc/meminfo)
    if [[ -n "$used_kb" && -n "$avail_kb" ]] && (( used_kb > avail_kb )); then
      echo "ОТКАЗ: в swap лежит ${used_kb} КБ, а свободной памяти ${avail_kb} КБ — swapoff может вызвать OOM. Освободи память и повтори."
      return 1
    fi
    if ! swapoff "$SWAP_FILE"; then echo "ОШИБКА: swapoff не удался"; return 1; fi
  fi
  if grep -qF "$SWAP_MARK" /etc/fstab 2>/dev/null; then
    cp -a /etc/fstab "/etc/fstab.backup.$(date +%s)"
    grep -vF "$SWAP_MARK" /etc/fstab > /etc/fstab.tmp.3xui && cat /etc/fstab.tmp.3xui > /etc/fstab
    rm -f /etc/fstab.tmp.3xui
  fi
  rm -f "$SWAP_FILE"
  if [[ -f "$SWAP_SYSCTL" ]]; then
    rm -f "$SWAP_SYSCTL"
    sysctl -w vm.swappiness=60 >/dev/null 2>&1 || true
    echo "vm.swappiness возвращён к 60 (умолчание Ubuntu)."
  fi
  echo "Готово: swap-файл, запись в fstab и sysctl-файл удалены."
}

# ================== РАЗБОР АРГУМЕНТОВ ==================

case "${1:-install}" in
  install|i|setup)
    cmd_install
    ;;
  healthcheck|check|status|hc)
    cmd_healthcheck
    ;;
  add-hy2|hy2|retrofit)
    cmd_add_hy2
    ;;
  add-bot|bot)
    cmd_add_bot
    ;;
  ensure-awg-dropin|awg-dropin)
    # v0.5.0: оставлено для совместимости (апгрейд из v0.4.9 вызывает эту команду
    # у нового файла). Ничего не делает: drop-in больше не нужен (lucx.292+).
    echo "v0.5.0: drop-in песочницы не требуется (lucx.292+ сам разрешает /etc/amnezia) — пропуск"
    ;;
  remove-bot|unbot)
    cmd_remove_bot
    ;;
  rebind-ip|rebind|newip)
    cmd_rebind_ip
    ;;
  add-vls|vls|tls)
    cmd_switch_mode tls
    ;;
  add-reality|reality)
    cmd_switch_mode reality
    ;;
  upgrade|update-script)
    cmd_upgrade
    ;;
  add-swap|swap)
    shift
    cmd_add_swap "$@"
    ;;
  remove-swap|unswap)
    cmd_remove_swap
    ;;
  *)
    echo "Использование:"
    echo "  sudo bash $0 install       — установить всё с нуля (чистый сервер;"
    echo "                               спросит режим 443: VLESS+TLS или Reality)"
    echo "  sudo bash $0 upgrade       — обновить сам этот скрипт до новейшей версии"
    echo "                               с GitHub (патч без переустановки)"
    echo "  sudo bash $0 add-vls       — переключить 443 на vless+TLS (с Reality-"
    echo "                               сервера; ключи сохраняются в /root/.lucx-mode-backup/)"
    echo "  sudo bash $0 add-reality   — вернуть Reality (из бэкапа ключей)"
    echo "  sudo bash $0 add-hy2       — добавить Hysteria 2 на существующий сервер"
    echo "  sudo bash $0 add-bot       — поставить/обновить Telegram-бота управления"
    echo "                               (спросит токен @BotFather; env не затирает)"
    echo "  sudo bash $0 remove-bot    — удалить Telegram-бота"
    echo "  sudo bash $0 healthcheck   — проверить текущую связку"
    echo "  sudo bash $0 rebind-ip     — сменить IP в stream-роутере"
    echo "                               (после смены IP у провайдера)"
    echo "  sudo bash $0 add-swap      — (опц.) swap-файл против OOM на нодах с 1 ГБ ОЗУ"
    echo "                               (--size 512M|1G|2G; не включай на ВМ с подвисающим диском)"
    echo "  sudo bash $0 remove-swap   — убрать swap-файл, созданный add-swap"
    exit 1
    ;;
esac
